//! Build-time wikitext presentation compiler. No HTML strings are executed and no network is required.
//! Reuses the portable document IR tokenizer, adding block layout, HTML, references,
//! entities, and a deliberately bounded set of Wiktionary template presentations.
const std = @import("std");
const ir = @import("blob_encoder").document_ir;
const entities = @import("shared_xml_decode").html_entities;
const syntax = @import("blob_encoder").wikitext_syntax;
const templates = @import("presentation_templates.zig");
const diagnostics = @import("build_diagnostics");
const hieroglyphs = @import("hieroglyph_unicode.zig");
const A = std.mem.Allocator;

fn optionalTableEnd(input: []const u8, opening: syntax.Tag) syntax.Pair {
    return optionalTableEndFrom(input, opening.name, opening.end, false);
}
fn optionalTableEndFrom(input: []const u8, name: []const u8, start: usize, implicit_row: bool) syntax.Pair {
    var cursor = start;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (!tag.closing and tag.is("table")) {
            if (syntax.matchingTag(input, tag)) |pair| {
                cursor = pair.end;
                continue;
            }
        }
        if (tag.closing and tag.is(name)) return .{ .inner_end = at, .end = tag.end };
        const row = std.ascii.eqlIgnoreCase(name, "tr");
        const sibling = !tag.closing and (if (row) tag.is("tr") else tag.is("td") or tag.is("th") or tag.is("tr"));
        // Authored row-group tags are escaped by the sanitizer. Their closing
        // spelling is visible text, not an optional row or cell boundary.
        const parent = tag.closing and (tag.is("table") or (!row and tag.is("tr")));
        // Omitted tr starts at the first actual cell. A caption belongs to
        // the surrounding table; authored group tags do not split this row.
        const implicit_boundary = implicit_row and !tag.closing and tag.is("caption");
        if (sibling or parent or implicit_boundary) return .{ .inner_end = at, .end = at };
    }
    return .{ .inner_end = input.len, .end = input.len };
}
// Raw unsupported group spellings must reach the ordinary HTML table path,
// where existing foster parenting and literal compilation retain their order.
// This admission scan uses the same tag/protected-scope rules as table parsing.
fn hasAuthoredTableGroup(input: []const u8) bool {
    var scan: syntax.OpaqueScan = .{};
    var no_more_nowiki_close = false;
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            cursor = end;
            continue;
        }
        const tag = scan.tagAt(input, at, &no_more_nowiki_close) orelse {
            cursor = at + 1;
            continue;
        };
        if (tag.is("tbody") or tag.is("thead") or tag.is("tfoot")) return true;
        cursor = tag.end;
    }
    return false;
}

fn optionalListItemEnd(input: []const u8, opening: syntax.Tag) syntax.Pair {
    if (opening.self_closing) return .{ .inner_end = opening.end, .end = opening.end };
    var cursor = opening.end;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (!tag.closing and (tag.is("ul") or tag.is("ol") or tag.is("dl") or tag.is("table"))) {
            if (syntax.matchingTag(input, tag)) |pair| {
                cursor = pair.end;
                continue;
            }
        }
        if (tag.closing and tag.is(opening.name)) return .{ .inner_end = at, .end = tag.end };
        const sibling = !tag.closing and (if (opening.is("li")) tag.is("li") else tag.is("dt") or tag.is("dd"));
        const parent = tag.closing and (tag.is("ul") or tag.is("ol") or tag.is("dl"));
        if (sibling or parent) return .{ .inner_end = at, .end = at };
    }
    return .{ .inner_end = input.len, .end = input.len };
}
// Explicit ruby fallback punctuation belongs to this ruby, not nested ruby or
// protected literal markup. Existing rp text must pass through unchanged.
fn rubyHasFallback(input: []const u8) bool {
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (tag.closing) continue;
        if (tag.is("rp")) return true;
        if (tag.is("ruby")) {
            if (syntax.matchingTag(input, tag)) |pair| cursor = pair.end;
        }
    }
    return false;
}

fn htmlAttributePresent(tag: syntax.Tag, key: []const u8) bool {
    var at: usize = 0;
    while (at < tag.attrs.len) {
        while (at < tag.attrs.len and (std.ascii.isWhitespace(tag.attrs[at]) or tag.attrs[at] == '/')) : (at += 1) {}
        const begin = at;
        while (at < tag.attrs.len and !std.ascii.isWhitespace(tag.attrs[at]) and tag.attrs[at] != '=' and tag.attrs[at] != '/') : (at += 1) {}
        if (at == begin) {
            at += 1;
            continue;
        }
        if (std.ascii.eqlIgnoreCase(tag.attrs[begin..at], key)) return true;
        while (at < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[at])) : (at += 1) {}
        if (at == tag.attrs.len or tag.attrs[at] != '=') continue;
        at += 1;
        while (at < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[at])) : (at += 1) {}
        if (at == tag.attrs.len) break;
        const quote = tag.attrs[at];
        const quoted = quote == '\'' or quote == '"';
        if (quoted) at += 1;
        while (at < tag.attrs.len and (if (quoted) tag.attrs[at] != quote else !std.ascii.isWhitespace(tag.attrs[at]))) : (at += 1) {}
        if (quoted and at < tag.attrs.len) at += 1;
    }
    return false;
}
const HtmlListNumberStyle = enum { decimal, lower_alpha, upper_alpha, lower_roman, upper_roman };
fn htmlListNumberStyle(value: []const u8) ?HtmlListNumberStyle {
    if (std.mem.eql(u8, value, "1")) return .decimal;
    if (std.mem.eql(u8, value, "a")) return .lower_alpha;
    if (std.mem.eql(u8, value, "A")) return .upper_alpha;
    if (std.mem.eql(u8, value, "i")) return .lower_roman;
    if (std.mem.eql(u8, value, "I")) return .upper_roman;
    return null;
}
fn htmlListItemCount(input: []const u8) i32 {
    var count: i32 = 0;
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (tag.closing) continue;
        if (tag.is("li")) {
            count +|= 1;
            cursor = optionalListItemEnd(input, tag).end;
        } else if (tag.is("ul") or tag.is("ol") or tag.is("dl") or tag.is("table")) {
            if (syntax.matchingTag(input, tag)) |pair| cursor = pair.end;
        }
    }
    return count;
}
pub const media_types = @import("presentation_media.zig");
pub const Error = A.Error || error{ RenderLimit, InvalidPreContext };

// Build-only coordinates in an already page-TOC-prepared owner fragment.
// The source owner map, rather than a new tag search here, proves these scopes.
pub const FormattingAttributes = struct {
    classes: []const u8 = "",
    role: Role = .normal,
    relation_note: bool = false,
    language: []const u8 = "",
    direction: []const u8 = "",
};
pub const FragmentPreContext = struct {
    pub const Kind = enum { pre, formatting, link, refused_link };
    pub const Initial = struct { body_end: usize, resume_at: usize, kind: FragmentPreContext.Kind = .pre, formatting: SpanFlags = .{}, target: []const u8 = "", attributes: FormattingAttributes = .{}, quote: ?QuoteSeed = null, resume_quote: ?QuoteSeed = null };
    pub const Trailing = struct { opening_start: usize, body_start: usize, kind: FragmentPreContext.Kind = .pre, formatting: SpanFlags = .{}, target: []const u8 = "", attributes: FormattingAttributes = .{}, quote: ?QuoteSeed = null };
    initial: []const Initial = &.{},
    trailing: []const Trailing = &.{},
    initial_block_pre: bool = false,
    quote: ?QuoteSeed = null,
};

// Sparse gate for the existing full-page observer. Complete single-line
// roots are skipped once; malformed overlap is bounded by the shared stack.
// This is only an observation hint. The existing renderer decides whether a
// matched formatting wrapper owns a body scope, and which headings it crosses.
pub fn mayHaveFormattingScopes(input: []const u8) bool {
    var opaque_scan: syntax.OpaqueScan = .{};
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |opening| {
        if (opaque_scan.protectedEnd(input, opening, null)) |end| {
            cursor = end;
            continue;
        }
        if (opaque_scan.tagAt(input, opening, null)) |tag| {
            cursor = tag.end;
            if (tag.closing or tag.self_closing) continue;
            if (Renderer.blockFormattingFlags(tag) != null) return true;
        } else cursor = opening + 1;
    }
    return false;
}

pub fn mayHaveMultilineLinks(source: []const u8) bool {
    var scan: syntax.OpaqueScan = .{};
    var at: usize = 0;
    while (at < source.len) {
        if (source[at] == '<') {
            if (scan.protectedEnd(source, at, null)) |end| {
                at = end;
                continue;
            }
            if (scan.tagAt(source, at, null)) |tag| {
                at = tag.end;
                continue;
            }
        }
        if (starts(source[at..], "{{") or starts(source[at..], "[[")) {
            if (syntax.balancedWithOpaqueScan(source, at, &scan)) |pair| {
                if (starts(source[at..], "[[") and std.mem.indexOfScalar(u8, source[at..pair.end], '\n') != null) return true;
                at = pair.end;
                continue;
            }
        }
        at += 1;
    }
    return false;
}

pub const PreScopeObserver = struct {
    ctx: ?*anyopaque,
    enter: *const fn (?*anyopaque, []const u8, ?usize, usize, usize, usize, usize, bool, FragmentPreContext.Kind, SpanFlags, []const u8, FormattingAttributes) Error!void,
};

// Optional build-only native extension provenance. A phase is validated once
// against the complete wire output/title before language regrouping. Renderers
// own copies of referenced strings, not pointers into the page transport arena.
pub const PoemPhaseItem = struct {
    token: []const u8,
    kind: enum { br, space, indent, scope, literal },
    depth: ?u8 = null,
    tag: ?[]const u8 = null,
    body: ?[]const u8 = null,
};
const PoemPhaseWire = struct {
    schema: []const u8,
    handled: bool,
    output_sha256: []const u8,
    display_title_sha256: []const u8,
    items: []const PoemPhaseItem,
};
pub const PoemPhase = struct {
    items: []const PoemPhaseItem,
    // Borrowed only during this page's synchronous Writer compilation. JSON
    // values and Renderer-owned strings have their separate allocator lifetimes.
    full_output: []const u8,
};
const native_poem_prefix = "\x7fWDPOEM:";
const max_poem_metadata_bytes = 16 * 1024 * 1024;
fn nativePoemLooking(value: []const u8) bool {
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, value, cursor, '<')) |lt| {
        cursor = lt + 1;
        if (cursor < value.len and value[cursor] == '/') cursor += 1;
        if (value.len - cursor < 4 or !std.ascii.eqlIgnoreCase(value[cursor..][0..4], "poem")) continue;
        if (value.len == cursor + 4 or value[cursor + 4] == '>' or value[cursor + 4] == '/' or std.ascii.isWhitespace(value[cursor + 4])) return true;
    }
    return false;
}
fn nativePoemIndex(value: []const u8) ?usize {
    if (!std.mem.startsWith(u8, value, native_poem_prefix)) return null;
    const rest = value[native_poem_prefix.len..];
    const colon = std.mem.indexOfScalar(u8, rest[0..@min(rest.len, 21)], ':') orelse return null;
    if (colon == 0 or (colon > 1 and rest[0] == '0')) return null;
    for (rest[0..colon]) |ch| if (!std.ascii.isDigit(ch)) return null;
    return std.fmt.parseInt(usize, rest[0..colon], 10) catch null;
}
const PoemReferenceMetrics = struct { bytes: usize, depth: usize };
fn poemReferenceMetrics(value: []const u8, items: []const PoemPhaseItem, before: usize, costs: []const usize, depths: []const usize) !PoemReferenceMetrics {
    var pos: usize = 0;
    var bytes: usize = 0;
    var depth: usize = 0;
    while (std.mem.indexOfPos(u8, value, pos, native_poem_prefix)) |found| {
        const index = nativePoemIndex(value[found..]) orelse return error.OrphanPoemMarker;
        if (index >= items.len or index >= before or !std.mem.startsWith(u8, value[found..], items[index].token)) return error.OrphanPoemMarker;
        bytes = std.math.add(usize, bytes, found - pos) catch return error.FrameTooLarge;
        bytes = std.math.add(usize, bytes, costs[index]) catch return error.FrameTooLarge;
        if (bytes > max_poem_metadata_bytes) return error.FrameTooLarge;
        depth = @max(depth, depths[index] + 1);
        if (depth > max_depth) return error.InvalidPoemMetadata;
        pos = found + items[index].token.len;
    }
    bytes = std.math.add(usize, bytes, value.len - pos) catch return error.FrameTooLarge;
    if (bytes > max_poem_metadata_bytes) return error.FrameTooLarge;
    return .{ .bytes = bytes, .depth = depth };
}
pub fn parsePoemPhaseAlloc(a: A, full_output: []const u8, display_title: ?[]const u8, metadata: ?[]const u8) !?*const PoemPhase {
    const title = display_title orelse "";
    if (full_output.len > max_poem_metadata_bytes or title.len > 64 * 1024) return error.FrameTooLarge;
    const encoded = metadata orelse {
        if (std.mem.indexOf(u8, full_output, native_poem_prefix) != null or std.mem.indexOf(u8, title, native_poem_prefix) != null) return error.OrphanPoemMarker;
        if (nativePoemLooking(full_output) or nativePoemLooking(title)) return error.MissingPoemMetadata;
        return null;
    };
    if (encoded.len > max_poem_metadata_bytes) return error.FrameTooLarge;
    const phase = try a.create(PoemPhaseWire);
    phase.* = std.json.parseFromSliceLeaky(PoemPhaseWire, a, encoded, .{ .allocate = .alloc_always, .ignore_unknown_fields = false, .duplicate_field_behavior = .@"error" }) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return error.InvalidPoemMetadata,
    };
    if (!phase.handled or !std.mem.eql(u8, phase.schema, "wikidict.poem-phase.v1") or phase.items.len > 100_000) return error.InvalidPoemMetadata;
    var output_hash: [32]u8 = undefined;
    var title_hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(full_output, &output_hash, .{});
    std.crypto.hash.sha2.Sha256.hash(title, &title_hash, .{});
    const output_hex = std.fmt.bytesToHex(output_hash, .lower);
    const title_hex = std.fmt.bytesToHex(title_hash, .lower);
    if (!std.mem.eql(u8, phase.output_sha256, &output_hex) or !std.mem.eql(u8, phase.display_title_sha256, &title_hex)) return error.InvalidPoemMetadata;
    const costs = try a.alloc(usize, phase.items.len);
    const depths = try a.alloc(usize, phase.items.len);
    var literal_bytes: usize = 0;
    for (phase.items, 0..) |item, index| {
        if (item.token.len > 128 or nativePoemIndex(item.token) != index) return error.InvalidPoemMetadata;
        const rest = item.token[native_poem_prefix.len..];
        const colon = native_poem_prefix.len + (std.mem.indexOfScalar(u8, rest, ':') orelse return error.InvalidPoemMetadata);
        const tail = item.token[colon + 1 ..];
        if (tail.len != 65 or tail[64] != 0x7f) return error.InvalidPoemMetadata;
        for (tail[0..64]) |ch| if (!std.ascii.isDigit(ch) and (ch < 'a' or ch > 'f')) return error.InvalidPoemMetadata;
        if (item.kind == .indent) {
            const depth = item.depth orelse return error.InvalidPoemMetadata;
            if (depth == 0 or depth > 32) return error.InvalidPoemMetadata;
        } else if (item.depth != null) return error.InvalidPoemMetadata;
        costs[index] = if (item.kind == .br or item.kind == .space) 1 else 0;
        depths[index] = 0;
        if (item.kind == .literal) {
            const tag = item.tag orelse return error.InvalidPoemMetadata;
            const body = item.body orelse return error.InvalidPoemMetadata;
            if (!oneOf(tag, &.{ "text", "nowiki", "pre", "source", "syntaxhighlight", "poem" })) return error.InvalidPoemMetadata;
            if (body.len > max_poem_metadata_bytes -| literal_bytes) return error.FrameTooLarge;
            literal_bytes += body.len;
            var body_hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(body, &body_hash, .{});
            const body_hex = std.fmt.bytesToHex(body_hash, .lower);
            if (!std.mem.eql(u8, tail[0..64], &body_hex)) return error.InvalidPoemMetadata;
            if (std.mem.eql(u8, tag, "text")) {
                costs[index] = body.len;
                depths[index] = 1;
            } else {
                const metrics = try poemReferenceMetrics(body, phase.items, index, costs, depths);
                costs[index] = metrics.bytes;
                depths[index] = metrics.depth;
            }
        } else if (item.tag != null or item.body != null) return error.InvalidPoemMetadata;
    }
    _ = try poemReferenceMetrics(full_output, phase.items, phase.items.len, costs, depths);
    const title_metrics = try poemReferenceMetrics(title, phase.items, phase.items.len, costs, depths);
    if (title_metrics.bytes > 64 * 1024) return error.FrameTooLarge;
    const result = try a.create(PoemPhase);
    result.* = .{ .items = phase.items, .full_output = full_output };
    return result;
}

pub const Context = struct {
    poem_phase: ?*const PoemPhase = null,
    image_options: ?*const @import("namespace_registry").image_options.Registry = null,
    behavior_switches: ?*const @import("namespace_registry").behavior_switches.Registry = null,
    namespace_catalog: ?*const @import("namespace_registry").Registry = null,
    title: []const u8 = "Entry",
    // Build-only opt-in; never serialized into typed presentation data.
    unclosed_fragment_trace: bool = false,
    language: []const u8 = "English",
    link_trail: ir.LinkTrail = .{},
};
pub const Role = enum { normal, label, pronunciation, headword, example, quotation, citation, reference };
pub const Provenance = enum { parsed, protected_literal, entity_literal };
pub const Style = struct {
    provenance: Provenance = .parsed,
    kind: ir.InlineKind = .text,
    target: []const u8 = "",
    language: []const u8 = "",
    classes: []const u8 = "",
    direction: []const u8 = "",
    bold: bool = false,
    italic: bool = false,
    code: bool = false,
    small: bool = false,
    superscript: bool = false,
    subscript: bool = false,
    strike: bool = false,
    underline: bool = false,
    role: Role = .normal,
    // Build-only context: decorative file names are not semantic heading text.
    heading: bool = false,
    // Build-only annotation boundary; readers receive ordinary semantic spans.
    ruby_parentheses: bool = false,
    // Unmatched pre is ordinary parsed HTML, with preformatted whitespace.
    preserve_whitespace: bool = false,
    // Build-only generated Poem wrapper; never inferred from lexical classes.
    poem_indent: ?u8 = null,
    // Poem recursively parses its body before an enclosing internal holder.
    // Navigation remains inherited; a newly created holder clears this phase.
    poem_independent_parse: bool = false,
};
pub const SpanFlags = packed struct(u8) {
    bold: bool = false,
    italic: bool = false,
    code: bool = false,
    small: bool = false,
    superscript: bool = false,
    subscript: bool = false,
    strike: bool = false,
    underline: bool = false,
};
pub const Span = struct {
    // Build-only validation origin. Never serialized into DPR2.
    provenance: Provenance = .parsed,
    kind: ir.InlineKind = .text,
    text: []const u8,
    target: []const u8 = "",
    language: []const u8 = "",
    classes: []const u8 = "",
    direction: []const u8 = "",
    flags: SpanFlags = .{},
    role: Role = .normal,
};
pub const Feature = struct { kind: []const u8, language: []const u8 = "", data: []const u8 = "", tail_kind: []const u8 = "none", tail: []const u8 = "" };
const SemanticHints = struct { relation_note: bool = false };
pub const Kind = enum { paragraph, blank, definition, example, quotation, list_item, list_detail, indent, term, heading, preformatted, rule, table };
pub const Cell = struct { spans: []const Span, header: bool = false, colspan: u16 = 1, rowspan: u16 = 1 };
pub const Row = struct { cells: []const Cell };
pub const Table = struct { caption: []const Span = &.{}, rows: []const Row };
pub const Block = struct {
    kind: Kind,
    depth: u8 = 0,
    text: []const u8 = "",
    spans: []const Span = &.{},
    feature: ?Feature = null,
    list_path: []const u8 = "",
    number: []const u8 = "",
    level: u8 = 0,
    table: ?Table = null,
    // Build-only hint captured while rendering; it is not serialized into DPR2.
    relation_note: bool = false,
};

// Quotes are resolved at build time before HTML repair. Internal labels have
// their own quote scope; authored HTML belongs to the surrounding line scope.
const QuoteBoundaries = struct {
    link_close: ?usize,
    template_close: ?usize,
    fn init(input: []const u8) QuoteBoundaries {
        return .{ .link_close = std.mem.lastIndexOf(u8, input, "]]"), .template_close = std.mem.lastIndexOf(u8, input, "}}") };
    }
    fn canClose(self: QuoteBoundaries, input: []const u8, at: usize) bool {
        const last = if (starts(input[at..], "[[")) self.link_close else self.template_close;
        return if (last) |end| end > at else false;
    }
};
fn quoteOpaqueEnd(a: A, input: []const u8, at: usize, boundaries: QuoteBoundaries, opaque_scan: *syntax.OpaqueScan, context: Context) Error!?usize {
    if (input[at] == '<') {
        if (opaque_scan.protectedEnd(input, at, null)) |end| return end;
        if (opaque_scan.tagAt(input, at, null)) |tag| return tag.end;
    }
    if ((starts(input[at..], "[[") or starts(input[at..], "{{")) and boundaries.canClose(input, at)) {
        if (syntax.balancedWithOpaqueScan(input, at, opaque_scan)) |pair| {
            if (starts(input[at..], "[[") and try ordinaryBodyLinkRefused(a, input[at..pair.end], context)) return null;
            return pair.end;
        }
    }
    return null;
}
fn ordinaryBodyLinkRefused(a: A, input: []const u8, context: Context) Error!bool {
    var it: ir.InlineIterator = .{ .input = input, .renderer_boundaries = true, .link_trail = context.link_trail };
    const token = it.next() orelse return false;
    if (token.kind != .link or !token.link_has_pipe or it.cursor != input.len or
        std.mem.indexOfScalar(u8, token.text, '\n') == null or syntax.delimiter(token.text, "[[", 0) == null) return false;
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    var resolved: ?[]const u8 = null;
    var refused = false;
    var probe: Renderer = .{ .a = arena.allocator(), .context = context, .navigation_target_probe = &resolved, .navigation_refused_probe = &refused, .navigation_probe_source = input };
    try probe.inlineText(input, .{}, 0);
    return refused;
}
const QuoteBehaviorRegistry = @import("namespace_registry").behavior_switches.Registry;
fn quoteControlEnd(a: A, input: []const u8, at: usize, registry: ?*const QuoteBehaviorRegistry) Error!?usize {
    const end = (if (registry) |captured| try captured.matchAt(a, input, at) else syntax.behaviorSwitchEnd(input, at)) orelse return null;
    const toc = if (registry) |captured| try captured.tocMatchAt(a, input, at) else if (std.ascii.eqlIgnoreCase(input[at..end], "__TOC__")) end else null;
    return if (toc != null and toc.? == end) null else end;
}
const QuoteRun = struct { count: usize, end: usize };
fn quoteRun(a: A, input: []const u8, at: usize, registry: ?*const QuoteBehaviorRegistry) Error!QuoteRun {
    var end = at;
    var count: usize = 0;
    while (end < input.len and input[end] == '\'') {
        count += 1;
        end += 1;
        var next = end;
        while (next < input.len) {
            if (try quoteControlEnd(a, input, next, registry)) |skip| next = skip else break;
        }
        // Consume empty controls only when another apostrophe joins this run.
        // Otherwise their exact authored bytes remain for the existing phase.
        if (next < input.len and input[next] == '\'') end = next;
    }
    return .{ .count = count, .end = end };
}
fn quoteRemember(previous: *[2]u8, bytes: []const u8) void {
    if (bytes.len >= 2) {
        previous.* = .{ bytes[bytes.len - 1], bytes[bytes.len - 2] };
    } else if (bytes.len == 1) {
        // Untyped aggregate assignment writes into previous element by element.
        const prior_first = previous[0];
        previous.* = .{ bytes[0], prior_first };
    }
}

const QuoteState = enum { none, b, i, bi, ib, both };
pub const QuoteSeed = struct { state: QuoteState, correction: ?usize, line_end: usize, boundaries: QuoteBoundaries, label_scope: bool = false };
pub const LinkQuoteObservation = struct { entry: QuoteSeed, resume_quote: QuoteSeed };

const QuoteTransition = struct { prefix: []const u8, suffix: []const u8 = "", state: QuoteState };
fn quoteTransitionValue(state: QuoteState, run: usize) QuoteTransition {
    const transitions = [6][3]QuoteTransition{
        .{ .{ .prefix = "<i>", .state = .i }, .{ .prefix = "<b>", .state = .b }, .{ .prefix = "", .state = .both } },
        .{ .{ .prefix = "<i>", .state = .bi }, .{ .prefix = "</b>", .state = .none }, .{ .prefix = "</b><i>", .state = .i } },
        .{ .{ .prefix = "</i>", .state = .none }, .{ .prefix = "<b>", .state = .ib }, .{ .prefix = "</i><b>", .state = .b } },
        .{ .{ .prefix = "</i>", .state = .b }, .{ .prefix = "</i></b><i>", .state = .i }, .{ .prefix = "</i></b>", .state = .none } },
        .{ .{ .prefix = "</b></i><b>", .state = .b }, .{ .prefix = "</b>", .state = .i }, .{ .prefix = "</b></i>", .state = .none } },
        .{ .{ .prefix = "<b><i>", .suffix = "</i>", .state = .b }, .{ .prefix = "<i><b>", .suffix = "</b>", .state = .i }, .{ .prefix = "<i><b>", .suffix = "</b></i>", .state = .none } },
    };
    const index: usize = switch (run) {
        2 => 0,
        3 => 1,
        5 => 2,
        else => unreachable,
    };
    return transitions[@backingInt(state)][index];
}
fn quoteTransition(out: *std.ArrayList(u8), buffer: *std.ArrayList(u8), a: A, state: *QuoteState, run: usize) Error!void {
    const transition = quoteTransitionValue(state.*, run);
    try out.appendSlice(a, transition.prefix);
    if (state.* == .both) {
        try out.appendSlice(a, buffer.items);
        buffer.clearRetainingCapacity();
    }
    try out.appendSlice(a, transition.suffix);
    state.* = transition.state;
}
fn quoteFinish(out: *std.ArrayList(u8), buffer: *std.ArrayList(u8), a: A, state: QuoteState) Error!void {
    const close: []const u8 = switch (state) {
        .none => "",
        .b => "</b>",
        .i => "</i>",
        .bi => "</i></b>",
        .ib => "</b></i>",
        .both => "",
    };
    if (state == .both and buffer.items.len != 0) {
        try out.appendSlice(a, "<b><i>");
        try out.appendSlice(a, buffer.items);
        try out.appendSlice(a, "</i></b>");
        buffer.clearRetainingCapacity();
    }
    try out.appendSlice(a, close);
}
fn hasWikiQuoteMarkers(a: A, input: []const u8, depth: usize, boundaries: QuoteBoundaries, registry: ?*const QuoteBehaviorRegistry, context: Context) Error!bool {
    if (depth >= max_depth or std.mem.indexOfScalar(u8, input, '\'') == null) return false;
    var at: usize = 0;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (at < input.len) {
        if (try quoteOpaqueEnd(a, input, at, boundaries, &opaque_scan, context)) |end| {
            if (starts(input[at..], "[[")) {
                const inner = input[at + 2 .. end - 2];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    if (try hasWikiQuoteMarkers(a, inner[pipe + 1 ..], depth + 1, QuoteBoundaries.init(inner[pipe + 1 ..]), registry, context)) return true;
                }
            }
            at = end;
        } else {
            if (try quoteControlEnd(a, input, at, registry)) |skip| {
                at = skip;
                continue;
            }
            if (input[at] == '\'' and (try quoteRun(a, input, at, registry)).count >= 2) return true;
            at += 1;
        }
    }
    return false;
}

const QuoteLineInfo = struct { end: usize, correction: ?usize };
fn quoteLineInfo(a: A, input: []const u8, start: usize, label_scope: bool, boundaries: QuoteBoundaries, registry: ?*const QuoteBehaviorRegistry, opaque_scan: *syntax.OpaqueScan, context: Context) Error!QuoteLineInfo {
    var end = start;
    var bold_count: usize = 0;
    var italic_count: usize = 0;
    var single: ?usize = null;
    var multi: ?usize = null;
    var space: ?usize = null;
    var previous: [2]u8 = .{ 0, 0 };
    while (end < input.len and (label_scope or input[end] != '\n')) {
        if (try quoteOpaqueEnd(a, input, end, boundaries, opaque_scan, context)) |skip| {
            quoteRemember(&previous, input[end..skip]);
            end = skip;
            continue;
        }
        if (try quoteControlEnd(a, input, end, registry)) |skip| {
            end = skip;
            continue;
        }
        const quote = try quoteRun(a, input, end, registry);
        const run = quote.count;
        const normalized = if (run == 4) @as(usize, 3) else if (run > 5) @as(usize, 5) else run;
        if (normalized == 2 or normalized == 5) italic_count += 1;
        if (normalized == 3 or normalized == 5) bold_count += 1;
        if (normalized == 3) {
            const x1: u8 = if (run == 4) '\'' else previous[0];
            const x2: u8 = if (run == 4) previous[0] else previous[1];
            if (x1 == ' ') {
                if (space == null) space = end;
            } else if (x2 == ' ') {
                if (single == null) single = end;
            } else if (multi == null) multi = end;
        }
        if (run == 0) {
            quoteRemember(&previous, input[end .. end + 1]);
            end += 1;
        } else {
            quoteRemember(&previous, if (run == 1) "'" else "''");
            end = quote.end;
        }
    }
    const counted_correction: ?usize = if (bold_count % 2 == 1 and italic_count % 2 == 1)
        (if (single) |at| at else if (multi) |at| at else space)
    else
        null;
    return .{ .end = end, .correction = counted_correction };
}
const QuoteBoundaryScan = struct {
    input: []const u8,
    boundaries: QuoteBoundaries,
    cursor: usize = 0,
    line: ?QuoteLineInfo = null,
    state: QuoteState = .none,
    label_scope: bool = false,
    count_opaque: syntax.OpaqueScan = .{},
    walk_opaque: syntax.OpaqueScan = .{},
    context: Context = .{},

    fn init(input: []const u8, seed: ?QuoteSeed) QuoteBoundaryScan {
        return .{ .input = input, .boundaries = if (seed) |value| value.boundaries else QuoteBoundaries.init(input), .state = if (seed) |value| value.state else .none, .label_scope = if (seed) |value| value.label_scope else false, .line = if (seed) |value| .{ .end = @min(value.line_end, input.len), .correction = value.correction } else null };
    }
    fn initWithContext(input: []const u8, seed: ?QuoteSeed, context: Context) QuoteBoundaryScan {
        var scan = init(input, seed);
        scan.context = context;
        return scan;
    }
    fn shifted(boundary: ?usize, offset: usize) ?usize {
        return if (boundary) |end| (if (end >= offset) end - offset else null) else null;
    }
    fn at(self: *QuoteBoundaryScan, a: A, position: usize, registry: ?*const QuoteBehaviorRegistry) Error!QuoteSeed {
        if (position < self.cursor or position > self.input.len) return error.InvalidPreContext;
        while (true) {
            if (self.line == null) self.line = try quoteLineInfo(a, self.input, self.cursor, self.label_scope, self.boundaries, registry, &self.count_opaque, self.context);
            const line = self.line.?;
            if (self.cursor == position) return .{ .state = self.state, .correction = shifted(line.correction, position), .line_end = line.end - position, .boundaries = .{ .link_close = shifted(self.boundaries.link_close, position), .template_close = shifted(self.boundaries.template_close, position) }, .label_scope = self.label_scope };
            if (self.cursor == line.end) {
                self.cursor += 1;
                self.line = null;
                self.state = .none;
                continue;
            }
            if (try quoteOpaqueEnd(a, self.input, self.cursor, self.boundaries, &self.walk_opaque, self.context)) |end| {
                if (end > position) return error.InvalidPreContext;
                self.cursor = end;
                continue;
            }
            if (try quoteControlEnd(a, self.input, self.cursor, registry)) |end| {
                if (end > position) return error.InvalidPreContext;
                self.cursor = end;
                continue;
            }
            const run = try quoteRun(a, self.input, self.cursor, registry);
            if (run.count >= 2) {
                const normalized: usize = if (line.correction != null and line.correction.? == self.cursor) 2 else if (run.count == 4) 3 else if (run.count > 5) 5 else run.count;
                self.state = quoteTransitionValue(self.state, normalized).state;
            }
            const end = if (run.count == 0) self.cursor + 1 else run.end;
            if (end > position) return error.InvalidPreContext;
            self.cursor = end;
        }
    }
};

fn labelQuoteSeed(a: A, input: []const u8, registry: ?*const QuoteBehaviorRegistry) Error!QuoteSeed {
    return labelQuoteSeedWithContext(a, input, .{ .behavior_switches = registry });
}
fn labelQuoteSeedWithContext(a: A, input: []const u8, context: Context) Error!QuoteSeed {
    var opaque_scan: syntax.OpaqueScan = .{};
    const boundaries = QuoteBoundaries.init(input);
    const info = try quoteLineInfo(a, input, 0, true, boundaries, context.behavior_switches, &opaque_scan, context);
    return .{ .state = .none, .correction = info.correction, .line_end = info.end, .boundaries = boundaries, .label_scope = true };
}

// A single forward walk over one admitted raw label supplies all owner cuts.
// Values contain offsets and state only; no probe-arena storage escapes.
pub fn linkQuoteCutSeedsAlloc(a: A, input: []const u8, cuts: []const usize, entry: QuoteSeed, registry: ?*const QuoteBehaviorRegistry) Error![]QuoteSeed {
    return linkQuoteCutSeedsWithContextAlloc(a, input, cuts, entry, .{ .behavior_switches = registry });
}
pub fn linkQuoteCutSeedsWithContextAlloc(a: A, input: []const u8, cuts: []const usize, entry: QuoteSeed, context: Context) Error![]QuoteSeed {
    if (!entry.label_scope) return error.InvalidPreContext;
    return quoteCutSeedsAlloc(a, input, cuts, entry, context);
}
pub fn bodyQuoteCutSeedsAlloc(a: A, input: []const u8, cuts: []const usize, registry: ?*const QuoteBehaviorRegistry) Error![]QuoteSeed {
    return bodyQuoteCutSeedsWithContextAlloc(a, input, cuts, .{ .behavior_switches = registry });
}
pub fn bodyQuoteCutSeedsWithContextAlloc(a: A, input: []const u8, cuts: []const usize, context: Context) Error![]QuoteSeed {
    return quoteCutSeedsAlloc(a, input, cuts, null, context);
}
fn quoteCutSeedsAlloc(a: A, input: []const u8, cuts: []const usize, entry: ?QuoteSeed, context: Context) Error![]QuoteSeed {
    const result = try a.alloc(QuoteSeed, cuts.len);
    errdefer a.free(result);
    var scan = QuoteBoundaryScan.initWithContext(input, entry, context);
    var previous: ?usize = null;
    for (cuts, result) |cut, *seed| {
        if (cut > input.len or (previous != null and cut <= previous.?)) return error.InvalidPreContext;
        seed.* = try scan.at(a, cut, context.behavior_switches);
        previous = cut;
    }
    return result;
}

fn quoteFormatting(state: QuoteState) SpanFlags {
    return switch (state) {
        .b => .{ .bold = true },
        .i => .{ .italic = true },
        .bi, .ib, .both => .{ .bold = true, .italic = true },
        .none => .{},
    };
}

fn normalizeWikiQuotes(a: A, input: []const u8, depth: usize, label_scope: bool) Error![]const u8 {
    return normalizeWikiQuotesWithControls(a, input, depth, label_scope, null);
}
fn normalizeWikiQuotesWithControls(a: A, input: []const u8, depth: usize, label_scope: bool, registry: ?*const QuoteBehaviorRegistry) Error![]const u8 {
    return normalizeWikiQuotesSeeded(a, input, depth, label_scope, registry, null);
}
fn normalizeWikiQuotesSeeded(a: A, input: []const u8, depth: usize, label_scope: bool, registry: ?*const QuoteBehaviorRegistry, initial: ?QuoteSeed) Error![]const u8 {
    return normalizeWikiQuotesSeededWithContext(a, input, depth, label_scope, .{ .behavior_switches = registry }, initial);
}
fn normalizeWikiQuotesSeededWithContext(a: A, input: []const u8, depth: usize, label_scope: bool, context: Context, initial: ?QuoteSeed) Error![]const u8 {
    const registry = context.behavior_switches;
    const boundaries = if (initial) |seed| seed.boundaries else QuoteBoundaries.init(input);
    if (initial == null and !try hasWikiQuoteMarkers(a, input, depth, boundaries, registry, context)) return input;
    var out: std.ArrayList(u8) = .empty;
    var buffer: std.ArrayList(u8) = .empty;
    var line_start: usize = 0;
    var count_opaque: syntax.OpaqueScan = .{};
    var emit_opaque: syntax.OpaqueScan = .{};
    while (line_start < input.len) {
        const info: QuoteLineInfo = if (line_start == 0 and initial != null)
            .{ .end = @min(initial.?.line_end, input.len), .correction = initial.?.correction }
        else
            try quoteLineInfo(a, input, line_start, label_scope, boundaries, registry, &count_opaque, context);
        const end = info.end;
        const correction = info.correction;
        var cursor = line_start;
        var state: QuoteState = if (line_start == 0 and initial != null) initial.?.state else .none;
        if (state != .none and state != .both) try out.appendSlice(a, switch (state) {
            .b => "<b>",
            .i => "<i>",
            .bi => "<b><i>",
            .ib => "<i><b>",
            else => unreachable,
        });
        while (cursor < end) {
            const sink = if (state == .both) &buffer else &out;
            if (try quoteOpaqueEnd(a, input, cursor, boundaries, &emit_opaque, context)) |skip| {
                if (starts(input[cursor..], "[[")) {
                    const inner = input[cursor + 2 .. skip - 2];
                    if (syntax.delimiter(inner, "|", 0)) |pipe| {
                        try sink.appendSlice(a, input[cursor .. cursor + 2 + pipe + 1]);
                        try sink.appendSlice(a, try normalizeMisnestedHtmlDepth(a, try normalizeWikiQuotesSeededWithContext(a, inner[pipe + 1 ..], depth + 1, true, context, null), depth + 1, false));
                        try sink.appendSlice(a, "]]");
                    } else try sink.appendSlice(a, input[cursor..skip]);
                } else try sink.appendSlice(a, input[cursor..skip]);
                cursor = skip;
                continue;
            }
            if (try quoteControlEnd(a, input, cursor, registry)) |skip| {
                try sink.appendSlice(a, input[cursor..skip]);
                cursor = skip;
                continue;
            }
            const quote = try quoteRun(a, input, cursor, registry);
            const run = quote.count;
            if (run >= 2) {
                var normalized = if (run == 4) @as(usize, 3) else if (run > 5) @as(usize, 5) else run;
                var literal = if (run == 4) @as(usize, 1) else if (run > 5) run - 5 else 0;
                if (correction != null and correction.? == cursor) {
                    normalized = 2;
                    literal += 1;
                }
                // Encoded extras cannot become fresh quote markers in recursive HTML.
                for (0..literal) |_| try sink.appendSlice(a, "&#39;");
                try quoteTransition(&out, &buffer, a, &state, normalized);
                cursor = quote.end;
            } else {
                try sink.append(a, input[cursor]);
                cursor += 1;
            }
        }
        try quoteFinish(&out, &buffer, a, state);
        if (end < input.len) try out.append(a, '\n');
        line_start = if (end < input.len) end + 1 else end;
    }
    return out.toOwnedSlice(a);
}

pub const Reference = struct { number: usize, group_number: usize, name: []const u8 = "", group: []const u8 = "", body: []const u8 = "", spans: []const Span = &.{}, poem: bool = false, poem_direction: []const u8 = "" };
pub const ReferenceDefinition = struct { name: []const u8, group: []const u8 = "", body: []const u8 = "" };
pub const ReferenceDefinitions = struct { items: []const ReferenceDefinition = &.{}, fallbacks: @import("presentation_fallback.zig").Report = .{} };

/// Collect names once without rendering reference bodies or creating citations.
pub fn referenceDefinitionsAlloc(a: std.mem.Allocator, source: []const u8) Error!ReferenceDefinitions {
    var renderer: Renderer = .{ .a = a, .context = .{} };
    try renderer.referenceDefinitions(source, "");
    return .{ .items = try renderer.ref_defs.toOwnedSlice(a), .fallbacks = renderer.fallbacks };
}

const max_nodes = 100_000;
const max_depth = 48;
fn starts(text: []const u8, prefix: []const u8) bool {
    return syntax.starts(text, prefix);
}
fn trim(text: []const u8) []const u8 {
    return syntax.trim(text);
}
fn listRoot(mark: u8) u8 {
    return if (mark == ';' or mark == ':') ';' else mark;
}
fn resetChangedListCounters(counts: []usize, previous: []const u8, current: []const u8) void {
    const limit = @min(counts.len, @min(previous.len, current.len));
    var common: usize = 0;
    while (common < limit and listRoot(previous[common]) == listRoot(current[common])) : (common += 1) {}
    // A different nested list family closes that list, but keeps common parents.
    @memset(counts[common..], 0);
}
// MediaWiki chooses definition separators after quote/link rendering, outside
// accepted HTML nesting. Keep the shared template delimiter rules unchanged.
const DefinitionColonScanner = struct {
    input: []const u8,
    cursor: usize = 0,
    html_depth: usize = 0,

    fn next(self: *DefinitionColonScanner, after: usize) ?usize {
        const text = self.input;
        while (self.cursor < text.len) {
            const colon = syntax.delimiter(text, ":", self.cursor) orelse return null;
            while (self.cursor < colon) {
                if (text[self.cursor] == '<') {
                    if (syntax.protectedEnd(text, self.cursor)) |end| {
                        self.cursor = end;
                        continue;
                    }
                    if (syntax.tagAt(text, self.cursor)) |tag| {
                        if (normalizableHtmlTag(tag.name) or oneOf(tag.name, &.{ "table", "tr", "td", "th", "caption" })) {
                            if (tag.closing) {
                                self.html_depth -|= 1;
                            } else {
                                // A slash does not close a non-void HTML container.
                                self.html_depth += 1;
                            }
                        }
                        self.cursor = tag.end;
                        continue;
                    }
                }
                if (starts(text[self.cursor..], "[[") or starts(text[self.cursor..], "{{")) {
                    if (syntax.balanced(text, self.cursor)) |pair| {
                        self.cursor = pair.end;
                        continue;
                    }
                }
                self.cursor += 1;
            }
            self.cursor = colon + 1;
            // A link-label opener can scope later text beyond the link itself.
            // Advance through it once; rejecting a link's colon must not reset depth.
            if (self.html_depth == 0 and colon >= after) return colon;
        }
        return null;
    }
};
pub fn inlineDefinitionSplit(text: []const u8) ?struct { term: []const u8, definition: []const u8 } {
    var scanner: DefinitionColonScanner = .{ .input = text };
    var colon = scanner.next(0) orelse return null;
    // Links become anchors before MediaWiki's definition-list pass. Reuse the
    // accepted bracketed/free-link extents without changing template delimiters.
    var tokens: ir.InlineIterator = .{ .input = text };
    while (true) {
        const before = tokens.cursor;
        const token = tokens.next() orelse break;
        if (tokens.cursor <= before) break;
        if (tokens.cursor <= colon) continue;
        if (token.kind == .external_link and before <= colon) {
            colon = scanner.next(tokens.cursor) orelse return null;
            continue;
        }
        break;
    }
    const term = std.mem.trim(u8, text[0..colon], " \t");
    const definition = std.mem.trim(u8, text[colon + 1 ..], " \t");
    return .{ .term = term, .definition = definition };
}
fn oneOf(name: []const u8, names: []const []const u8) bool {
    for (names) |n| if (std.ascii.eqlIgnoreCase(name, n)) return true;
    return false;
}

fn adoptionFormattingTag(name: []const u8) bool {
    return oneOf(name, &.{ "b", "big", "code", "em", "font", "i", "s", "small", "strike", "strong", "tt", "u" });
}

fn normalizableHtmlTag(name: []const u8) bool {
    return oneOf(name, &.{
        "b",    "strong", "i",    "em",   "u",    "s",   "del",        "strike", "ins",  "sup",  "sub",  "small",
        "big",  "span",   "font", "code", "tt",   "kbd", "samp",       "var",    "cite", "dfn",  "abbr", "q",
        "time", "mark",   "bdi",  "bdo",  "ruby", "rb",  "rt",         "rtc",    "rp",   "data", "h1",   "h2",
        "h3",   "h4",     "h5",   "h6",   "div",  "p",   "blockquote", "center", "ul",   "ol",   "li",   "dl",
        "dt",   "dd",
    });
}

const HtmlNormalizationFrame = struct {
    name: []const u8,
    opener: []const u8,
    formatting: bool,
    external_close_at: ?usize = null,
    label_output_start: usize = 0,
    repair_generated: bool = false,
};
const HtmlNormalizationToken = struct { frame: HtmlNormalizationFrame, closing: bool, end: usize };
const max_html_normalization_frames = max_depth * 4;

// External links are parsed after quotes upstream. Their brackets therefore
// participate in formatting repair, while authored HTML anchors remain literal.
fn htmlNormalizationToken(input: []const u8, at: usize, recognize_external_links: bool) ?HtmlNormalizationToken {
    if (recognize_external_links and input[at] == ']') return .{ .frame = .{ .name = "!external", .opener = "", .formatting = true }, .closing = true, .end = at + 1 };
    if (recognize_external_links and input[at] == '[') {
        if (at + 1 >= input.len or input[at + 1] == '[' or !ir.hasExternalProtocol(input[at + 1 ..])) return null;
        var iterator: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
        const token = iterator.next() orelse return null;
        if (token.kind != .external_link) return null;
        const target_end = @intFromPtr(token.target.ptr) - @intFromPtr(input.ptr) + token.target.len;
        return .{ .frame = .{ .name = "!external", .opener = input[at..target_end], .formatting = true, .external_close_at = at + iterator.cursor - 1 }, .closing = false, .end = target_end };
    }
    const tag = syntax.tagAt(input, at) orelse return null;
    if (!normalizableHtmlTag(tag.name) or tag.self_closing) return null;
    return .{ .frame = .{ .name = tag.name, .opener = input[at..tag.end], .formatting = adoptionFormattingTag(tag.name) }, .closing = tag.closing, .end = tag.end };
}
fn htmlNormalizationMatch(frames: []const HtmlNormalizationFrame, token: HtmlNormalizationToken, at: usize) ?usize {
    var index = frames.len;
    while (index != 0) {
        index -= 1;
        if (std.ascii.eqlIgnoreCase(frames[index].name, token.frame.name)) {
            if (frames[index].external_close_at) |close_at| {
                if (close_at != at) continue;
            }
            return index;
        }
    }
    return null;
}
fn hasMisnestedHtml(input: []const u8, depth: usize, recognize_external_links: bool) bool {
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (depth >= max_depth) return false;
    const boundaries = QuoteBoundaries.init(input);
    if (std.mem.indexOfScalar(u8, input, '<') == null) return false;
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[")) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    if (hasMisnestedHtml(inner[pipe + 1 ..], depth + 1, false)) return true;
                }
                pos = pair.end;
                continue;
            };
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            pos = at + 1;
            continue;
        };
        pos = token.end;
        if (!token.closing) {
            if (frame_count == frames.len) return false;
            frames[frame_count] = token.frame;
            frame_count += 1;
        } else if (htmlNormalizationMatch(frames[0..frame_count], token, at)) |index| {
            if (index + 1 != frame_count) return true;
            frame_count = index;
        }
    }
    return false;
}
fn appendHtmlFrameClose(a: A, out: *std.ArrayList(u8), frame: HtmlNormalizationFrame) Error!void {
    if (frame.external_close_at != null) {
        // Only an empty repair-generated fragment needs a transparent label.
        if (std.mem.trim(u8, out.items[frame.label_output_start..], " \t\r\n").len == 0)
            try out.appendSlice(a, "<span></span>");
        return out.append(a, ']');
    }
    try out.appendSlice(a, "</");
    try out.appendSlice(a, frame.name);
    try out.append(a, '>');
}
fn normalizeMisnestedHtml(a: A, input: []const u8) Error![]const u8 {
    return normalizeMisnestedHtmlDepth(a, input, 0, true);
}
fn normalizeMisnestedHtmlDepth(a: A, input: []const u8, depth: usize, recognize_external_links: bool) Error![]const u8 {
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (!hasMisnestedHtml(input, depth, recognize_external_links)) return input;
    const boundaries = QuoteBoundaries.init(input);
    var out: std.ArrayList(u8) = .empty;
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        try out.appendSlice(a, input[pos..at]);
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            try out.appendSlice(a, input[at..end]);
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[")) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    try out.appendSlice(a, input[at .. at + 2 + pipe + 1]);
                    try out.appendSlice(a, try normalizeMisnestedHtmlDepth(a, inner[pipe + 1 ..], depth + 1, false));
                    try out.appendSlice(a, "]]");
                } else try out.appendSlice(a, input[at..pair.end]);
                pos = pair.end;
                continue;
            };
            try out.appendSlice(a, input[at .. at + 2]);
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                try out.appendSlice(a, input[at..tag.end]);
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            try out.append(a, input[at]);
            pos = at + 1;
            continue;
        };
        const raw = input[at..token.end];
        if (!token.closing) {
            try out.appendSlice(a, raw);
            if (frame_count == frames.len) return input;
            var frame = token.frame;
            if (frame.external_close_at != null) frame.label_output_start = out.items.len;
            frames[frame_count] = frame;
            frame_count += 1;
            pos = token.end;
            continue;
        }
        const index = htmlNormalizationMatch(frames[0..frame_count], token, at) orelse {
            try out.appendSlice(a, raw);
            pos = token.end;
            continue;
        };
        const above = frames[index + 1 .. frame_count];
        var close_index = above.len;
        while (close_index != 0) {
            close_index -= 1;
            try appendHtmlFrameClose(a, &out, above[close_index]);
        }
        const closed = frames[index];
        if (closed.external_close_at != null and closed.repair_generated and
            std.mem.trim(u8, out.items[closed.label_output_start..], " \t\r\n").len == 0)
            try out.appendSlice(a, "<span></span>");
        try out.appendSlice(a, raw);
        var retained: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
        var retained_len: usize = 0;
        for (above) |frame| if (frame.formatting) {
            retained[retained_len] = frame;
            retained_len += 1;
        };
        frame_count = index;
        for (retained[0..retained_len]) |frame| {
            try out.appendSlice(a, frame.opener);
            var reopened = frame;
            if (frame.external_close_at != null) {
                try out.append(a, ' ');
                reopened.label_output_start = out.items.len;
                reopened.repair_generated = true;
            }
            frames[frame_count] = reopened;
            frame_count += 1;
        }
        pos = token.end;
    }
    try out.appendSlice(a, input[pos..]);
    return out.toOwnedSlice(a);
}
inline fn referenceStringEqual(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    if (a.len == 0) return true;
    if (a.len < 4) {
        const middle = a.len / 2;
        return ((a[0] ^ b[0]) | (a[a.len - 1] ^ b[b.len - 1]) | (a[middle] ^ b[middle])) == 0;
    }
    if (a.len <= 8) {
        return std.mem.readInt(u32, a[0..4], .little) == std.mem.readInt(u32, b[0..4], .little) and
            std.mem.readInt(u32, a[a.len - 4 ..][0..4], .little) == std.mem.readInt(u32, b[b.len - 4 ..][0..4], .little);
    }
    if (a.len <= 16) {
        return std.mem.readInt(u64, a[0..8], .little) == std.mem.readInt(u64, b[0..8], .little) and
            std.mem.readInt(u64, a[a.len - 8 ..][0..8], .little) == std.mem.readInt(u64, b[b.len - 8 ..][0..8], .little);
    }
    return std.mem.eql(u8, a, b);
}

fn pipeTrickLabel(target: []const u8) []const u8 {
    // MediaWiki's pre-save pipe trick is intentionally syntactic: the first
    // colon prefix is removed even when it is not a registered namespace. It
    // does not apply to section/anchor links.
    if (std.mem.indexOfScalar(u8, target, '#') != null) return target;
    var label = target;
    if (std.mem.indexOfScalar(u8, label, ':')) |colon| label = std.mem.trimStart(u8, label[colon + 1 ..], " \t");
    if (label.len != 0 and label[label.len - 1] == ')') {
        if (std.mem.lastIndexOf(u8, label, " (")) |paren| label = label[0..paren];
    } else if (std.mem.indexOf(u8, label, ", ")) |comma| {
        label = label[0..comma];
    }
    return label;
}

pub fn safeUrl(url: []const u8) bool {
    if (!ir.validExternalUrl(url)) return false;
    for (url) |ch| if (ch <= 32 or ch == 127) return false;
    return true;
}

const MagicLinkKind = enum { rfc, pmid, isbn };
const MagicLink = struct {
    kind: MagicLinkKind,
    end: usize,
    text: []const u8,
    payload: []const u8,
};

fn magicSpace(ch: u8) bool {
    return ch == ' ' or ch == '\t';
}

// MediaWiki Parser::SPACE_NOT_NL, on authored source. Do not decode arbitrary
// entities here: encoded prefixes and double-encoded spaces remain literal.
fn isbnSpaceLen(input: []const u8) usize {
    if (input.len == 0) return 0;
    if (magicSpace(input[0])) return 1;
    if (std.mem.startsWith(u8, input, "&nbsp;")) return 6;
    if (std.mem.startsWith(u8, input, "&#")) {
        var pos: usize = 2;
        const hex = pos < input.len and (input[pos] == 'x' or input[pos] == 'X');
        if (hex) pos += 1;
        while (pos < input.len and input[pos] == '0') : (pos += 1) {}
        if (hex) {
            if (pos + 3 <= input.len and (input[pos] == 'a' or input[pos] == 'A') and
                input[pos + 1] == '0' and input[pos + 2] == ';') return pos + 3;
        } else if (std.mem.startsWith(u8, input[pos..], "160;")) return pos + 4;
        return 0;
    }
    if (input[0] < 0x80) return 0;
    const len = std.unicode.utf8ByteSequenceLength(input[0]) catch return 0;
    if (len > input.len) return 0;
    const cp = std.unicode.utf8Decode(input[0..len]) catch return 0;
    return if (cp == 0xa0 or cp == 0x1680 or (cp >= 0x2000 and cp <= 0x200a) or
        cp == 0x202f or cp == 0x205f or cp == 0x3000) len else 0;
}

fn isbnDelimiterLen(input: []const u8) usize {
    return if (input.len != 0 and input[0] == '-') 1 else isbnSpaceLen(input);
}

// The optional second slice starts at an entity boundary in ordinary text.
// Matching this view avoids copying or decoding the unconsumed page suffix.
const MagicSource = struct {
    first: []const u8,
    tail: []const u8 = "",

    fn remaining(self: MagicSource, pos: usize) []const u8 {
        return if (pos < self.first.len) self.first[pos..] else self.tail[pos - self.first.len ..];
    }
    fn byte(self: MagicSource, pos: usize) ?u8 {
        const rest = self.remaining(pos);
        return if (rest.len == 0) null else rest[0];
    }
    fn boundaryAfter(self: MagicSource, pos: usize) bool {
        return if (pos < self.first.len)
            ir.linkBoundaryAfter(self.first, pos)
        else
            ir.linkBoundaryAfter(self.tail, pos - self.first.len);
    }
};

const MagicMatch = struct { kind: MagicLinkKind, end: usize, payload_start: usize };

fn isbnPayloadEnd(input: MagicSource, start: usize, thirteen: bool) ?usize {
    var pos = start;
    if (thirteen) {
        const rest = input.remaining(pos);
        if (!std.mem.startsWith(u8, rest, "978") and !std.mem.startsWith(u8, rest, "979")) return null;
        pos += 3;
        pos += isbnDelimiterLen(input.remaining(pos));
    }
    for (0..9) |_| {
        const ch = input.byte(pos) orelse return null;
        if (!std.ascii.isDigit(ch)) return null;
        pos += 1;
        pos += isbnDelimiterLen(input.remaining(pos));
    }
    const check = input.byte(pos) orelse return null;
    if (!std.ascii.isDigit(check) and check != 'X' and check != 'x') return null;
    pos += 1;
    return if (input.boundaryAfter(pos)) pos else null;
}

fn magicMatchAt(input: MagicSource, start: usize) ?MagicMatch {
    if (!ir.linkBoundaryBefore(input.first, start)) return null;
    const Prefix = struct { kind: MagicLinkKind, len: usize };
    const prefix: Prefix = if (std.mem.startsWith(u8, input.first[start..], "RFC"))
        .{ .kind = .rfc, .len = 3 }
    else if (std.mem.startsWith(u8, input.first[start..], "PMID"))
        .{ .kind = .pmid, .len = 4 }
    else if (std.mem.startsWith(u8, input.first[start..], "ISBN"))
        .{ .kind = .isbn, .len = 4 }
    else
        return null;

    var pos = start + prefix.len;
    const spaces_start = pos;
    while (true) {
        const rest = input.remaining(pos);
        const len = if (prefix.kind == .isbn)
            isbnSpaceLen(rest)
        else if (rest.len != 0 and magicSpace(rest[0]))
            @as(usize, 1)
        else
            0;
        if (len == 0) break;
        pos += len;
    }
    if (pos == spaces_start) return null;
    const payload_start = pos;
    if (prefix.kind == .rfc or prefix.kind == .pmid) {
        while (input.byte(pos)) |ch| {
            if (!std.ascii.isDigit(ch)) break;
            pos += 1;
        }
        if (pos == payload_start or !input.boundaryAfter(pos)) return null;
        return .{ .kind = prefix.kind, .end = pos, .payload_start = payload_start };
    }
    // The upstream optional 97[89] prefix is greedy, but may backtrack to the
    // ten-digit alternative. Each digit position allows only one delimiter.
    const end = isbnPayloadEnd(input, payload_start, true) orelse
        isbnPayloadEnd(input, payload_start, false) orelse return null;
    return .{ .kind = .isbn, .end = end, .payload_start = payload_start };
}

fn magicLinkAt(input: []const u8, start: usize) ?MagicLink {
    const matched = magicMatchAt(.{ .first = input }, start) orelse return null;
    return .{
        .kind = matched.kind,
        .end = matched.end,
        .text = input[start..matched.end],
        .payload = input[matched.payload_start..matched.end],
    };
}

fn isbnCandidateStart(value: []const u8) ?usize {
    var cursor: usize = 0;
    while (std.mem.indexOfPos(u8, value, cursor, "ISBN")) |at| {
        const after = at + 4;
        if (ir.linkBoundaryBefore(value, at) and
            (after == value.len or isbnSpaceLen(value[after..]) != 0)) return at;
        cursor = after;
    }
    return null;
}

fn magicLinkStart(input: []const u8, start: usize) ?usize {
    var pos = start;
    while (pos < input.len) {
        const relative = std.mem.indexOfAny(u8, input[pos..], "RPI") orelse return null;
        pos += relative;
        if (magicLinkAt(input, pos) != null) return pos;
        pos += 1;
    }
    return null;
}
fn internalTargetHasNowikiRegion(target: []const u8) bool {
    var cursor: usize = 0;
    var no_more_close = false;
    while (std.mem.indexOfScalarPos(u8, target, cursor, '<')) |open| {
        if (syntax.nowikiRegionAtCached(target, open, &no_more_close) != null) return true;
        cursor = open + 1;
    }
    return false;
}

fn safeInternalTarget(target: []const u8) bool {
    var has_non_ascii = false;
    for (target) |ch| {
        if (ch < 32 or ch == 127 or std.mem.indexOfScalar(u8, "[]{}", ch) != null) return false;
        has_non_ascii = has_non_ascii or ch >= 128;
    }
    if (!has_non_ascii) return true;
    if (!std.unicode.utf8ValidateSlice(target)) return false;
    var view = std.unicode.Utf8View.initUnchecked(target);
    var it = view.iterator();
    while (it.nextCodepoint()) |cp| if (cp >= 0x80 and cp <= 0x9f) return false;
    return true;
}
test "safe internal target ASCII fast path preserves Unicode and control checks" {
    try std.testing.expect(safeInternalTarget("cat#section"));
    try std.testing.expect(safeInternalTarget("caf\xc3\xa9"));
    try std.testing.expect(safeInternalTarget("cat \xf0\x9f\x90\x88"));
    try std.testing.expect(!safeInternalTarget("cat\x7f"));
    try std.testing.expect(!safeInternalTarget("cat\xc2\x85"));
    try std.testing.expect(!safeInternalTarget("cat\xff"));
    try std.testing.expect(safeInternalTarget("Tom''s"));
    try std.testing.expect(!safeInternalTarget("[[taking]]"));
    try std.testing.expect(!safeInternalTarget("{{{7}}}"));
    try std.testing.expect(!safeInternalTarget("taking#x[y]"));
}

/// The caller uses an arena for a page; returned arrays/text share its lifetime.
pub fn unclosedFragmentTraceEnabled(value: ?[]const u8) !bool {
    const raw = value orelse return false;
    if (std.mem.eql(u8, raw, "0")) return false;
    if (std.mem.eql(u8, raw, "1")) return true;
    return error.InvalidUnclosedFragmentTrace;
}
fn boundedTraceHex(buffer: []u8, bytes: []const u8) []const u8 {
    const count = @min(bytes.len, buffer.len / 2);
    const digits = "0123456789abcdef";
    for (bytes[0..count], 0..) |byte, i| {
        buffer[2 * i] = digits[byte >> 4];
        buffer[2 * i + 1] = digits[byte & 15];
    }
    return buffer[0 .. count * 2];
}

/// Preserve only the first active page-body TOC boundary before owner regrouping.
/// Returns input when unchanged; otherwise the caller owns the allocated slice.
/// Reference/list bodies retain the existing deferred-reference policy, not Cite parity.
pub fn preparePageTocSourceAlloc(a: A, input: []const u8, registry: ?*const @import("namespace_registry").behavior_switches.Registry) Error![]const u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(a);
    var emitted: usize = 0;
    var scan: usize = 0;
    var first_toc = false;
    // Track the copied output line once, so TOC elision cannot create or
    // extend an earlier-phase horizontal-rule prefix.
    var hyphen_line = true;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (scan < input.len) {
        if (input[scan] == '<') {
            const tag = opaque_scan.tagAt(input, scan, &no_more_nowiki_close);
            if (opaque_scan.protectedEnd(input, scan, &no_more_nowiki_close)) |end| {
                scan = end;
                continue;
            }
            if (tag) |opening| {
                scan = opening.end;
                continue;
            }
        }
        const matched = if (registry) |captured| try captured.matchAt(a, input, scan) else syntax.behaviorSwitchEnd(input, scan);
        if (matched) |end| {
            const toc_end = if (registry) |captured| try captured.tocMatchAt(a, input, scan) else if (std.ascii.eqlIgnoreCase(input[scan..end], "__TOC__")) end else null;
            if (toc_end != null and toc_end.? == end) {
                if (first_toc) {
                    const copied = input[emitted..scan];
                    try out.appendSlice(a, copied);
                    for (copied) |ch| {
                        if (ch == '\n') hyphen_line = true else if (ch != '-') hyphen_line = false;
                    }
                    emitted = end;
                    if (hyphen_line and end < input.len and input[end] == '-') {
                        // Preserve this existing suffix byte without joining it
                        // to an authored hyphen run across the removed control.
                        try out.appendSlice(a, "&#45;");
                        emitted = end + 1;
                        hyphen_line = false;
                    }
                } else first_toc = true;
            }
            scan = @max(end, emitted);
        } else scan += 1;
    }
    if (emitted == 0) return input;
    try out.appendSlice(a, input[emitted..]);
    return try out.toOwnedSlice(a);
}

pub const Renderer = struct {
    fallbacks: @import("presentation_fallback.zig").Report = .{},
    a: A,
    context: Context,
    rendered_templates: usize = 0,
    unresolved_templates: usize = 0,
    nodes: usize = 0,
    truncated: bool = false,
    span_limit_marker: bool = false,
    block_limit_reached: bool = false,
    body_depth: usize = 0,
    parsed_pre: bool = false,
    pre_block: bool = false,
    // An HTML li/dd suppresses implicit paragraphs and leading-space pre.
    html_list_item_flow: bool = false,
    pre_scope_observer: ?PreScopeObserver = null,
    body_link_target: []const u8 = "",
    // Only an active structural parent supplies this lexical lang/dir base.
    body_language_direction: ?Style = null,
    body_formatting_attributes: FormattingAttributes = .{},
    body_paragraph_join: ?*BodyParagraphJoin = null,
    navigation_target_probe: ?*?[]const u8 = null,
    navigation_refused_probe: ?*bool = null,
    link_quote_observation: ?LinkQuoteObservation = null,
    navigation_probe_source: []const u8 = "",
    next_quote_seed: ?QuoteSeed = null,
    unclosed_trace_events: usize = 0,
    block_formatting: SpanFlags = .{},
    refs: std.ArrayList(Reference) = .empty,
    ref_defs: std.ArrayList(ReferenceDefinition) = .empty,
    // Borrowed build-only page definitions. Unused names never become references.
    page_reference_definitions: []const ReferenceDefinition = &.{},
    default_group_reference_count: usize = 0,
    media_caption_spans: std.ArrayList([]const Span) = .empty,
    media: std.ArrayList(media_types.Media) = .empty,
    media_depth: usize = 0,
    spans: std.ArrayList(Span) = .empty,
    in_reference: bool = false,
    semantic_capture: ?*SemanticHints = null,
    // Confined build-only strip items survive quote/HTML normalization and
    // deferred reference bodies. Neither item tokens nor source bodies ship.
    poem_items: std.ArrayList(PoemItem) = .empty,
    poem_phase_loaded: bool = false,
    poem_item_dispatches: usize = 0,
    poem_dispatch_limit: bool = false,
    poem_definition_dispatches: usize = 0,
    poem_definitions_complete: bool = false,
    poem_depth: usize = 0,
    poem_direction: []const u8 = "",
    poem_base_style: Style = .{},
    poem_line_indent: u8 = 0,
    poem_boundary_pending: bool = false,
    poem_authored_token: bool = false,

    const poem_prefix = "\x7fWDPOEM:";
    const PoemItem = struct {
        token: []const u8,
        kind: enum { line_break, soft_space, indent, scope, literal },
        indent: u8 = 0,
        tag: []const u8 = "",
        body: []const u8 = "",
    };
    pub fn loadPoemPhase(self: *Renderer) Error!void {
        if (self.poem_phase_loaded) return;
        self.poem_phase_loaded = true;
        const phase = self.context.poem_phase orelse return;
        if (phase.items.len == 0) return;
        try self.poem_items.ensureTotalCapacity(self.a, phase.items.len);
        for (phase.items) |item| {
            self.poem_items.appendAssumeCapacity(.{
                .token = try self.a.dupe(u8, item.token),
                .kind = switch (item.kind) {
                    .br => .line_break,
                    .space => .soft_space,
                    .indent => .indent,
                    .scope => .scope,
                    .literal => .literal,
                },
                .indent = item.depth orelse 0,
                .tag = if (item.tag) |value| try self.a.dupe(u8, value) else "",
                .body = if (item.body) |value| try self.a.dupe(u8, value) else "",
            });
        }
        // Follow only emitted page roots, in source order. Authenticated but
        // discarded items and display-title-only definitions remain unused.
        var has_poem = false;
        for (self.poem_items.items) |item| if (item.kind == .literal and std.mem.eql(u8, item.tag, "poem")) {
            has_poem = true;
            break;
        };
        if (has_poem) {
            try self.referenceDefinitionsInner(phase.full_output, "", 0);
            self.poem_definitions_complete = true;
        }
    }
    fn poemItemAt(self: *Renderer, value: []const u8) ?PoemItem {
        if (!starts(value, poem_prefix)) return null;
        const rest = value[poem_prefix.len..];
        const colon = std.mem.indexOfScalar(u8, rest[0..@min(rest.len, 21)], ':') orelse return null;
        if (colon == 0) return null;
        for (rest[0..colon]) |ch| if (!std.ascii.isDigit(ch)) return null;
        const index = std.fmt.parseInt(usize, rest[0..colon], 10) catch return null;
        if (index >= self.poem_items.items.len) return null;
        const item = self.poem_items.items[index];
        return if (starts(value, item.token)) item else null;
    }
    fn poemItemBefore(self: *Renderer, value: []const u8, at: usize) ?PoemItem {
        // Item tokens are under 100 bytes, independent of page/indent size.
        const begin = at -| 100;
        const prefix = std.mem.lastIndexOf(u8, value[begin..at], poem_prefix) orelse return null;
        const item = self.poemItemAt(value[begin + prefix ..]) orelse return null;
        return if (begin + prefix + item.token.len == at) item else null;
    }
    fn poemHasUnregisteredItem(self: *Renderer, input: []const u8) bool {
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, input, at, poem_prefix)) |found| {
            const item = self.poemItemAt(input[found..]) orelse return true;
            at = found + item.token.len;
        }
        return false;
    }
    fn poemToken(self: *Renderer, kind: @FieldType(PoemItem, "kind"), indent: u8, digest: *const [64]u8) Error![]const u8 {
        if (self.poem_items.items.len >= max_nodes) return error.RenderLimit;
        const token = try std.fmt.allocPrint(self.a, "{s}{d}:{s}\x7f", .{ poem_prefix, self.poem_items.items.len, digest });
        try self.poem_items.append(self.a, .{ .token = token, .kind = kind, .indent = indent });
        return token;
    }
    fn poemClasses(self: *Renderer, existing: []const u8, indent: u8) Error![]const u8 {
        var out: std.ArrayList(u8) = .empty;
        var parts = std.mem.tokenizeAny(u8, existing, " \t\r\n\x0b\x0c");
        while (parts.next()) |part| {
            if (std.mem.eql(u8, part, "wikidict-poem") or starts(part, "wikidict-poem-indent") or starts(part, "wikidict-poem-dir")) continue;
            if (out.items.len != 0) try out.append(self.a, ' ');
            try out.appendSlice(self.a, part);
        }
        if (out.items.len != 0) try out.append(self.a, ' ');
        try out.appendSlice(self.a, "wikidict-poem");
        if (indent != 0) try out.appendSlice(self.a, try std.fmt.allocPrint(self.a, " wikidict-poem-indent-{d}", .{indent}));
        if (oneOf(self.poem_direction, &.{ "ltr", "rtl" }))
            try out.appendSlice(self.a, try std.fmt.allocPrint(self.a, " wikidict-poem-dir-{s}", .{self.poem_direction}));
        return out.toOwnedSlice(self.a);
    }
    fn poemCleanField(self: *Renderer, value: []const u8) Error![]const u8 {
        if (self.poem_items.items.len == 0) return value;
        if (std.mem.indexOf(u8, value, poem_prefix) == null) return value;
        var out: std.ArrayList(u8) = .empty;
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, value, at, poem_prefix)) |found| {
            try out.appendSlice(self.a, value[at..found]);
            if (self.poemItemAt(value[found..])) |item| {
                // Only explicit authored text is lexical identity; generated
                // instructions cannot become navigation.
                if (item.kind == .literal and std.mem.eql(u8, item.tag, "text")) {
                    try out.appendSlice(self.a, item.body);
                } else {
                    self.fallbacks.unsupported_element = true;
                    if (item.kind != .indent) try out.append(self.a, ' ');
                }
                at = found + item.token.len;
            } else {
                try out.appendSlice(self.a, poem_prefix);
                at = found + poem_prefix.len;
            }
        }
        try out.appendSlice(self.a, value[at..]);
        return out.toOwnedSlice(self.a);
    }
    fn poemProjection(self: *Renderer, input: []const u8) Error![]const u8 {
        if (std.mem.count(u8, input, "\n") > max_nodes / 2) return error.RenderLimit;
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(input, &hash, .{});
        const digest = std.fmt.bytesToHex(hash, .lower);
        // Stage order is the official handler's raw colon transform, outer-LF
        // trimming/break insertion, then leading ASCII-space entity conversion.
        var colon: std.ArrayList(u8) = .empty;
        var pos: usize = 0;
        while (pos < input.len) {
            const end = std.mem.indexOfScalarPos(u8, input, pos, '\n') orelse input.len;
            const line = input[pos..end];
            var count: usize = 0;
            while (count < line.len and line[count] == ':') : (count += 1) {}
            if (count != 0 and count < line.len) {
                if (count > 32) self.fallbacks.render_limit = true;
                try colon.appendSlice(self.a, try self.poemToken(.indent, @intCast(@min(count, 32)), &digest));
                // Exact official spelling is retained if a nested protected
                // body later displays the wrapper rather than parsing it.
                try colon.appendSlice(self.a, try std.fmt.allocPrint(self.a, "<span class=\"mw-poem-indented\" style=\"display: inline-block; margin-inline-start: {d}em;\">", .{count}));
                try colon.appendSlice(self.a, line[count..]);
                try colon.appendSlice(self.a, "</span>");
            } else try colon.appendSlice(self.a, line);
            if (end < input.len) try colon.append(self.a, '\n');
            pos = if (end < input.len) end + 1 else end;
        }
        var transformed: []const u8 = colon.items;
        if (starts(transformed, "\n")) transformed = transformed[1..];
        if (std.mem.endsWith(u8, transformed, "\n")) transformed = transformed[0 .. transformed.len - 1];
        var out: std.ArrayList(u8) = .empty;
        pos = 0;
        while (pos < transformed.len) {
            const end = std.mem.indexOfScalarPos(u8, transformed, pos, '\n') orelse transformed.len;
            const line = transformed[pos..end];
            var spaces: usize = 0;
            while (spaces < line.len and line[spaces] == ' ') : (spaces += 1) {}
            for (0..spaces) |_| try out.appendSlice(self.a, "&#160;");
            try out.appendSlice(self.a, line[spaces..]);
            if (end < transformed.len) {
                try out.appendSlice(self.a, try self.poemToken(if (std.mem.eql(u8, line, "----")) .soft_space else .line_break, 0, &digest));
                try out.append(self.a, '\n');
            }
            pos = if (end < transformed.len) end + 1 else end;
        }
        return out.toOwnedSlice(self.a);
    }
    fn poem(self: *Renderer, input: []const u8, style: Style, depth: usize) Error!void {
        return self.poemWithPhase(input, style, depth, false);
    }
    fn poemWithPhase(self: *Renderer, input: []const u8, style: Style, depth: usize, prepared: bool) Error!void {
        if (self.poem_depth >= max_depth or depth >= max_depth) {
            self.fallbacks.render_limit = true;
            try self.protectedLiteral(input, style);
            return;
        }
        if (self.poem_authored_token or self.poemHasUnregisteredItem(input)) {
            // An authored token-like spelling is never interpreted as an item.
            self.fallbacks.unsupported_element = true;
            try self.protectedLiteral(input, style);
            return;
        }
        const projected = if (prepared) input else self.poemProjection(input) catch |err| switch (err) {
            error.RenderLimit => {
                self.fallbacks.render_limit = true;
                try self.protectedLiteral(input, style);
                return;
            },
            else => return err,
        };
        const previous_depth = self.poem_depth;
        const previous_direction = self.poem_direction;
        const previous_style = self.poem_base_style;
        const previous_indent = self.poem_line_indent;
        const previous_body_link_target = self.body_link_target;
        if (self.spans.items.len != 0 and self.spans.items[self.spans.items.len - 1].kind != .line_break)
            try self.lineBreak(.{});
        self.poem_depth += 1;
        self.poem_direction = style.direction;
        self.poem_base_style = style;
        self.poem_base_style.poem_indent = null;
        self.poem_base_style.poem_independent_parse = true;
        self.poem_line_indent = 0;
        self.body_link_target = "";
        defer {
            self.poem_depth = previous_depth;
            self.poem_direction = previous_direction;
            self.poem_base_style = previous_style;
            self.poem_line_indent = previous_indent;
            self.body_link_target = previous_body_link_target;
        }
        // The existing block parser owns lists, headings, rules and tables.
        // Span-only containment flattens their preserved reading order; its
        // non-equivalent geometry remains explicitly diagnosed below.
        const blocks = try self.renderBody(projected);
        for (blocks, 0..) |block_value, index| {
            if (index != 0 and self.spans.items.len != 0 and self.spans.items[self.spans.items.len - 1].kind != .line_break)
                try self.lineBreak(style);
            if (block_value.kind == .rule) {
                self.fallbacks.unsupported_element = true;
                try self.text("────────", style);
                try self.lineBreak(style);
                continue;
            }
            if (block_value.kind == .table or block_value.depth != 0 or block_value.kind == .heading)
                self.fallbacks.unsupported_element = true;
            if (block_value.feature) |feature| {
                self.fallbacks.unsupported_element = true;
                try self.text(feature.data, style);
            }
            if (block_value.list_path.len != 0) switch (block_value.list_path[block_value.list_path.len - 1]) {
                '*' => try self.text("• ", style),
                '#' => {
                    try self.text(block_value.number, style);
                    try self.text(". ", style);
                },
                else => {},
            };
            // Remove the post-HR generated break once (official late exception).
            var first: usize = 0;
            if (index != 0 and blocks[index - 1].kind == .rule and block_value.spans.len != 0 and
                (block_value.spans[0].kind == .line_break or trim(block_value.spans[0].text).len == 0)) first = 1;
            try self.spans.appendSlice(self.a, block_value.spans[first..]);
            if (block_value.table) |table| {
                try self.spans.appendSlice(self.a, table.caption);
                for (table.rows) |row| {
                    try self.lineBreak(style);
                    for (row.cells, 0..) |cell, ci| {
                        if (ci != 0) try self.text(" · ", style);
                        try self.spans.appendSlice(self.a, cell.spans);
                    }
                }
            }
        }
        self.poem_boundary_pending = true;
    }

    fn markUnclosed(self: *Renderer, input: []const u8, tag: syntax.Tag, comptime site: []const u8) void {
        self.fallbacks.unclosed_formatting = true;
        if (!self.context.unclosed_fragment_trace or self.unclosed_trace_events >= 8) return;
        self.unclosed_trace_events += 1;
        // parseSpans can normalize quotes/HTML into a new allocation. This
        // offset is local to the exact compiler fragment, never a page offset.
        const name_offset = @intFromPtr(tag.name.ptr) - @intFromPtr(input.ptr);
        var fragment_buffer: [1024]u8 = undefined;
        var title_buffer: [256]u8 = undefined;
        const window_offset = name_offset -| 256;
        const window_end = @min(input.len, window_offset + fragment_buffer.len / 2);
        const fragment_hex = boundedTraceHex(&fragment_buffer, input[window_offset..window_end]);
        const title_hex = boundedTraceHex(&title_buffer, self.context.title);
        diagnostics.logLine("presentation unclosed site={s} title_hex={s} title_bytes={d} title_truncated={any} tag={s} name_offset={d} fragment_bytes={d} fragment_window_offset={d} fragment_window_hex={s} fragment_truncated={any}", .{
            site,         title_hex,                                     self.context.title.len, self.context.title.len > title_hex.len / 2,
            tag.name,     name_offset,                                   input.len,              window_offset,
            fragment_hex, window_offset != 0 or window_end != input.len,
        });
    }

    fn namespaceOfTarget(self: *const Renderer, title: []const u8) ?i32 {
        const colon = std.mem.indexOfScalar(u8, title, ':') orelse return null;
        const prefix = title[0..colon];
        if (self.context.namespace_catalog) |registry|
            return if (registry.byName(prefix)) |spec| spec.id else null;
        // Canonical standard names are also useful to standalone semantic
        // presentation callers that have no edition-local aliases.
        if (std.ascii.eqlIgnoreCase(prefix, "Category")) return 14;
        if (std.ascii.eqlIgnoreCase(prefix, "File") or std.ascii.eqlIgnoreCase(prefix, "Image")) return 6;
        return null;
    }

    fn nestedLabelRefusal(self: *const Renderer, target: []const u8, label: []const u8, explicit: bool) ?bool {
        const namespace = self.namespaceOfTarget(target);
        if (!explicit and namespace == 6) return null;
        if (syntax.delimiter(label, "[[", 0) == null) return null;
        return safeInternalTarget(target) and (explicit or namespace != 14);
    }

    fn canonicalMediaFile(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        var identity = raw;
        if (std.mem.indexOf(u8, raw, poem_prefix) != null) {
            var at: usize = 0;
            while (std.mem.indexOfPos(u8, raw, at, poem_prefix)) |found| {
                const item = self.poemItemAt(raw[found..]) orelse {
                    self.fallbacks.unsupported_element = true;
                    return null;
                };
                if (item.kind != .literal or !std.mem.eql(u8, item.tag, "text")) {
                    self.fallbacks.unsupported_element = true;
                    return null;
                }
                at = found + item.token.len;
            }
            identity = try self.poemCleanField(raw);
        }
        const file = try self.a.dupe(u8, std.mem.trim(u8, identity, " \t\r\n"));
        std.mem.replaceScalar(u8, file, '_', ' ');
        return file;
    }
    fn mediaClasses(self: *Renderer, raw: []const u8) Error![]const u8 {
        const file = (try self.canonicalMediaFile(raw)) orelse return "wikidict-media";
        // Only an actual emitted Media.file can authorize ownership metadata.
        var present = false;
        for (self.media.items) |item| if (std.mem.eql(u8, item.file, file)) {
            present = true;
            break;
        };
        if (!present) return "wikidict-media";
        const prefix = "wikidict-media wikidict-media-file-";
        // DPR2 already limits each classes string to 32 MiB. Check before doubling.
        if (file.len > (32 * 1024 * 1024 - prefix.len) / 2) return error.RenderLimit;
        const value = try self.a.alloc(u8, prefix.len + file.len * 2);
        @memcpy(value[0..prefix.len], prefix);
        const hex = "0123456789abcdef";
        for (file, 0..) |byte, index| {
            value[prefix.len + index * 2] = hex[byte >> 4];
            value[prefix.len + index * 2 + 1] = hex[byte & 15];
        }
        return value;
    }
    pub fn mediaFile(self: *Renderer, raw: []const u8, caption: []const u8) Error!void {
        return self.mediaFileKind(raw, caption, null);
    }
    fn mediaFileKind(self: *Renderer, raw: []const u8, caption: []const u8, authoritative_kind: ?media_types.Kind) Error!void {
        _ = try self.mediaFileKindWithSpans(raw, caption, authoritative_kind, null);
    }
    const MediaCaptionCapture = struct {
        mode: enum { spans, inline_body, link } = .spans,
        style: Style,
        depth: usize = 0,
        target: []const u8 = "",
        external: bool = false,
    };
    fn captureMediaCaption(self: *Renderer, input: []const u8, capture: MediaCaptionCapture) Error![]const Span {
        if (capture.mode == .spans) return self.parseSpans(input, capture.style);
        const parent = self.spans;
        self.spans = try .initCapacity(self.a, 4);
        defer self.spans = parent;
        errdefer self.spans.deinit(self.a);
        switch (capture.mode) {
            .spans => unreachable,
            .inline_body => {
                if (std.mem.indexOf(u8, input, "{|") != null) {
                    try self.blocksInline(try self.renderBody(input), capture.style);
                } else try self.inlineText(input, capture.style, capture.depth);
            },
            .link => try self.link(input, capture.target, capture.style, capture.depth, capture.external),
        }
        return self.spans.toOwnedSlice(self.a);
    }
    pub fn mediaCaptionLink(self: *Renderer, file: []const u8, caption: []const u8, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        const capture: MediaCaptionCapture = .{ .mode = .link, .style = style, .depth = depth, .target = target, .external = external };
        const parsed = (try self.mediaFileKindWithSpans(file, caption, null, capture)) orelse try self.captureMediaCaption(caption, capture);
        try self.spans.appendSlice(self.a, parsed);
    }
    fn mediaFileKindWithSpans(self: *Renderer, raw: []const u8, caption: []const u8, authoritative_kind: ?media_types.Kind, caption_style: ?MediaCaptionCapture) Error!?[]const Span {
        // Media is supplemental presentation. Pathological nesting or a page with
        // hundreds of assets must not make the entry itself unreadable.
        if (self.media_depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return null;
        }
        self.media_depth += 1;
        defer self.media_depth -= 1;
        const file = (try self.canonicalMediaFile(raw)) orelse return null;
        const kind = authoritative_kind orelse media_types.referencedKind(file) orelse return null;
        for (self.media.items) |item| if (std.mem.eql(u8, item.file, file)) return null;
        if (self.media.items.len >= 128) {
            self.fallbacks.render_limit = true;
            return null;
        }
        const caption_spans = if (caption_style) |capture| try self.captureMediaCaption(caption, capture) else try self.parseSpans(caption, .{});
        // Caption parsing can register nested media. Recheck the same canonical
        // identity and budget before committing this metadata record. Preserve
        // the captured occurrence so its caller never repeats caption effects.
        for (self.media.items) |item| if (std.mem.eql(u8, item.file, file))
            return if (caption_style != null) caption_spans else null;
        if (self.media.items.len >= 128) {
            self.fallbacks.render_limit = true;
            return if (caption_style != null) caption_spans else null;
        }
        const description = try plainText(self.a, caption_spans);
        try self.media.append(self.a, .{ .file = file, .kind = kind, .caption = description });
        try self.media_caption_spans.append(self.a, caption_spans);
        return if (caption_style != null) caption_spans else null;
    }
    fn spend(self: *Renderer) bool {
        if (self.nodes >= max_nodes) {
            self.fallbacks.render_limit = true;
            self.truncated = true;
            return false;
        }
        self.nodes += 1;
        return true;
    }
    pub fn text(self: *Renderer, value: []const u8, original: Style) Error!void {
        try self.loadPoemPhase();
        if (self.poem_dispatch_limit) return;
        // Ordinary pages retain the original single-span emission path.
        if (self.poem_items.items.len == 0 and self.poem_depth == 0 and !self.poem_boundary_pending)
            return self.textRaw(value, original);
        var style = original;
        if (self.poem_boundary_pending and value.len != 0) {
            self.poem_boundary_pending = false;
            if (original.kind != .line_break and self.spans.items.len != 0 and self.spans.items[self.spans.items.len - 1].kind != .line_break)
                try self.textRaw("\n", .{ .kind = .line_break });
            self.poem_line_indent = 0;
        }
        var at: usize = 0;
        while (at < value.len) {
            const found = std.mem.indexOfPos(u8, value, at, poem_prefix) orelse break;
            try self.poemText(value[at..found], style);
            if (self.poemItemAt(value[found..])) |item| {
                if (self.poem_item_dispatches >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    self.poem_dispatch_limit = true;
                    try self.textRaw("[render output truncated]", style);
                    return;
                }
                self.poem_item_dispatches += 1;
                at = found + item.token.len;
                if (item.kind == .line_break) {
                    var break_style = style;
                    break_style.kind = .line_break;
                    try self.poemText("\n", break_style);
                    // The accompanying source-formatting LF is not a second
                    // semantic break, including inside nowiki/pre/source.
                    if (at < value.len and value[at] == '\n') at += 1;
                    style.poem_indent = null;
                } else if (item.kind == .literal) {
                    var literal_style = style;
                    if (std.mem.eql(u8, item.tag, "poem")) {
                        try self.inlineText(item.body, literal_style, self.poem_depth + 1);
                    } else if (std.mem.eql(u8, item.tag, "text")) {
                        try self.poemText(item.body, literal_style);
                    } else {
                        const nowiki = std.mem.eql(u8, item.tag, "nowiki");
                        if (!nowiki) {
                            literal_style.code = true;
                            literal_style.preserve_whitespace = true;
                        }
                        literal_style.provenance = .protected_literal;
                        if (oneOf(item.tag, &.{ "source", "syntaxhighlight" }))
                            try self.text(item.body, literal_style)
                        else if (nowiki)
                            try self.protectedNowikiLiteral(item.body, literal_style)
                        else
                            try self.protectedLiteral(item.body, literal_style);
                    }
                } else if (item.kind == .soft_space) {
                    // Core nowiki collapses this unspecialized LF as HTML
                    // whitespace; actual pre/source literal contexts retain LF.
                    if (style.preserve_whitespace) {
                        var break_style = style;
                        break_style.kind = .line_break;
                        try self.poemText("\n", break_style);
                        style.poem_indent = null;
                    } else try self.poemText(" ", style);
                    if (at < value.len and value[at] == '\n') at += 1;
                }
            } else {
                try self.poemText(poem_prefix, style);
                at = found + poem_prefix.len;
            }
        }
        try self.poemText(value[at..], style);
    }
    fn poemText(self: *Renderer, value: []const u8, original: Style) Error!void {
        if (value.len == 0) return;
        var style = original;
        if (self.poem_depth != 0) {
            const parent = self.poem_base_style;
            style.bold = style.bold or parent.bold;
            style.italic = style.italic or parent.italic;
            style.code = style.code or parent.code;
            style.small = style.small or parent.small;
            style.superscript = style.superscript or parent.superscript;
            style.subscript = style.subscript or parent.subscript;
            style.strike = style.strike or parent.strike;
            style.underline = style.underline or parent.underline;
            if (style.language.len == 0) style.language = parent.language;
            if (style.direction.len == 0) style.direction = parent.direction;
            if (parent.classes.len != 0) style.classes = try std.fmt.allocPrint(self.a, "{s} {s}", .{ parent.classes, style.classes });
            if (style.poem_indent) |indent| self.poem_line_indent = indent;
            style.classes = try self.poemClasses(style.classes, self.poem_line_indent);
        }
        // A nowiki item captured before Poem projection has no registered
        // break for its raw LF. It remains HTML whitespace after unstripping.
        // Registered breaks have already been dispatched with line_break kind;
        // pre/source contexts preserve their literal whitespace.
        if (self.poem_depth != 0 and style.kind != .line_break and
            style.provenance == .protected_literal and !style.preserve_whitespace and
            std.mem.indexOfAny(u8, value, "\r\n") != null)
        {
            var normalized: std.ArrayList(u8) = .empty;
            var whitespace = false;
            for (value) |ch| {
                if (ch == '\n' or ch == '\r' or ch == '\t') {
                    if (!whitespace) try normalized.append(self.a, ' ');
                    whitespace = true;
                } else {
                    try normalized.append(self.a, ch);
                    whitespace = ch == ' ';
                }
            }
            return self.textRaw(try normalized.toOwnedSlice(self.a), style);
        }
        if (self.poem_depth != 0 and style.kind != .line_break) {
            var at: usize = 0;
            while (std.mem.indexOfScalarPos(u8, value, at, '\n')) |lf| {
                try self.textRaw(value[at..lf], style);
                var break_style = style;
                break_style.kind = .line_break;
                try self.textRaw("\n", break_style);
                self.poem_line_indent = 0;
                style.poem_indent = null;
                style.classes = try self.poemClasses(style.classes, 0);
                at = lf + 1;
            }
            try self.textRaw(value[at..], style);
        } else try self.textRaw(value, style);
        if (style.kind == .line_break) self.poem_line_indent = 0;
    }
    fn textRaw(self: *Renderer, value: []const u8, original: Style) Error!void {
        var s = original;
        if (self.poem_items.items.len != 0) {
            const target = try self.poemCleanField(s.target);
            if (target.ptr != s.target.ptr) {
                s.kind = .text;
                s.target = "";
            }
            s.classes = try self.poemCleanField(s.classes);
            s.language = try self.poemCleanField(s.language);
            s.direction = try self.poemCleanField(s.direction);
