                if (!whitespace) try out.append(self.a, ' ');
                whitespace = true;
            } else {
                try out.append(self.a, ch);
                whitespace = ch == ' ';
            }
        }
        try self.text(try out.toOwnedSlice(self.a), style);
    }
    fn renderMagicLink(self: *Renderer, link_value: MagicLink, style: Style) Error!void {
