                const entity_bytes = bytes[0..count];
                if (std.mem.eql(u8, entity_bytes, "&lt;") or std.mem.eql(u8, entity_bytes, "&gt;")) return cursor;
                if (bracketed) return null;
                if (std.mem.eql(u8, entity_bytes, "&nbsp;")) return cursor;
