                    try source_ends.append(self.a, scan);
                }
                delimiters += 1;
                // Prefix spaces may repeat, but payload slots allow one.
                if (digits != 0 and delimiters == 2) break;
                continue;
            }
            const ch = value[scan];
            if (std.ascii.isDigit(ch) or ch == 'X' or ch == 'x' or ch == '-') {
                scan += 1;
                try text_value.append(self.a, ch);
                try source_ends.append(self.a, scan);
