        // aliases belong only to XML recovery. MediaWiki additionally accepts
        // these Hebrew/Arabic spellings of the right-to-left mark.
        const value: []const u8 = if (std.mem.eql(u8, name, "רלמ") or std.mem.eql(u8, name, "رلم"))
            "\u{200f}"
