        // Parsed pre keeps authored whitespace; Poem dispatches its registered
        // semantic breaks through the existing protected-literal path.
        if (style.preserve_whitespace or self.poem_depth != 0)
            return self.protectedLiteral(input, style);
        var literal_style = style;
        literal_style.provenance = .protected_literal;
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, start, '&')) |i| {
            try self.plain(input[start..i], literal_style);
            if (try self.entity(input[i..], literal_style)) |n| {
                start = i + n;
            } else {
                try self.text("&", literal_style);
                start = i + 1;
            }
        }
        try self.plain(input[start..], literal_style);
    }
    fn literal(self: *Renderer, input: []const u8, style: Style) Error!void {
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, start, '&')) |i| {
            try self.text(input[start..i], style);
            if (try self.entity(input[i..], style)) |n| {
                start = i + n;
            } else {
                try self.text("&", style);
                start = i + 1;
            }
        }
        try self.text(input[start..], style);
    }
    fn externalUrlTarget(self: *Renderer, value: []const u8) Error![]const u8 {
        if (std.mem.indexOfScalar(u8, value, '&') == null) return value;
        var out: std.ArrayList(u8) = .empty;
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, value, start, '&')) |i| {
            try out.appendSlice(self.a, value[start..i]);
            var buf: [4]u8 = undefined;
            if (decodeEntity(value[i..], &buf, false)) |decoded| {
                // Literal lowercase entities are source delimiters handled by
                // DocIR. Other encoded angles belong to the URL, not its label.
                const delimiter = starts(value[i..], "&lt;") or starts(value[i..], "&gt;");
                if (!delimiter and std.mem.eql(u8, decoded.bytes, "<")) {
                    try out.appendSlice(self.a, "%3C");
                } else if (!delimiter and std.mem.eql(u8, decoded.bytes, ">")) {
                    try out.appendSlice(self.a, "%3E");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, " ")) {
                    try out.append(self.a, '+');
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\t")) {
                    try out.appendSlice(self.a, "%09");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\n")) {
                    try out.appendSlice(self.a, "%0A");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\r")) {
                    try out.appendSlice(self.a, "%EF%BF%BD");
                } else if (std.mem.eql(u8, decoded.bytes, "\"")) {
                    try out.appendSlice(self.a, "%22");
                } else if (std.mem.eql(u8, decoded.bytes, "\xc2\xa0")) {
                    try out.appendSlice(self.a, "%C2%A0");
                } else try out.appendSlice(self.a, decoded.bytes);
                start = i + decoded.consumed;
            } else {
                try out.append(self.a, '&');
                start = i + 1;
            }
