    pub fn link(self: *Renderer, label: []const u8, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        var s = style;
        const resolved_target = if (external) try self.externalUrlTarget(target) else target;
        if (resolved_target.len != 0 and (!external or safeUrl(resolved_target))) {
            s.kind = if (external) .external_link else .link;
            s.target = resolved_target;
            if (!external) s.poem_independent_parse = false;
        }
        if (external and std.mem.eql(u8, label, target)) {
            const decoded_label = try self.entityText(label);
            // URL text containing encoded controls/whitespace uses its escaped
            // destination spelling, never raw navigation control characters.
            const escaped_label = std.mem.indexOfAny(u8, decoded_label, " \t\n\r\"") != null or
                std.mem.indexOf(u8, decoded_label, "\xc2\xa0") != null;
            try self.text(if (escaped_label) resolved_target else decoded_label, s);
            return;
        }
        try self.inlineText(label, s, depth + 1);
    }
    fn referenceIndex(self: *Renderer, name: []const u8, group: []const u8, body: []const u8) Error!?usize {
        const use_short_name_compare = self.refs.items.len >= 16;
        if (name.len != 0) for (self.refs.items, 0..) |*ref, i| {
            const same_name = if (use_short_name_compare) referenceStringEqual(ref.name, name) else std.mem.eql(u8, ref.name, name);
            if (!same_name or !std.mem.eql(u8, ref.group, group)) continue;
            if (ref.body.len == 0 and body.len != 0) ref.body = body;
            return i;
        };
        var resolved_body = body;
        // Authenticated native phase definitions include opaque Poem bodies
        // in emitted page order. The legacy raw table cannot see those bodies.
        // Ordinary/legacy calls retain the exact previous table and precedence.
        const page_definitions = if (self.poem_definitions_complete) self.ref_defs.items else self.page_reference_definitions;
        if (name.len != 0) for (page_definitions) |definition| {
            if (definition.body.len != 0 and std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                break;
            }
        };
        if (name.len != 0 and resolved_body.len == 0) for (self.ref_defs.items) |definition| {
            if (std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                break;
            }
        };
        if (!self.spend()) return null;
        const index = self.refs.items.len;
        var group_number: usize = 1;
        if (group.len == 0) {
            self.default_group_reference_count += 1;
            group_number = self.default_group_reference_count;
        } else {
            for (self.refs.items) |ref| {
                if (std.mem.eql(u8, ref.group, group)) group_number += 1;
            }
        }
        try self.refs.append(self.a, .{ .number = index + 1, .group_number = group_number, .name = name, .group = group, .body = resolved_body, .poem = self.poem_depth != 0, .poem_direction = self.poem_direction });
        return index;
    }
    fn reference(self: *Renderer, name: []const u8, group: []const u8, body: []const u8, style: Style) Error!void {
        if (self.in_reference) {
            try self.text("[nested reference]", style);
            return;
        }
        const index = (try self.referenceIndex(name, group, body)) orelse {
            try self.text("[render output truncated]", style);
            return;
        };
        const ref = self.refs.items[index];
        var s = style;
        s.superscript = true;
        s.role = .reference;
        s.kind = .link;
        s.target = try std.fmt.allocPrint(self.a, "#reference-{d}", .{ref.number});
        const marker = if (group.len == 0)
            try std.fmt.allocPrint(self.a, "[{d}]", .{ref.group_number})
        else
            try std.fmt.allocPrint(self.a, "[{s} {d}]", .{ group, ref.group_number });
        try self.text(marker, s);
    }
    fn referenceDefinitions(self: *Renderer, content: []const u8, default_group: []const u8) Error!void {
        try self.referenceDefinitionsInner(content, default_group, 0);
    }
    fn referenceDefinitionsInner(self: *Renderer, content: []const u8, default_group: []const u8, depth: usize) Error!void {
        if (depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return;
        }
        var pos: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        var next_tag = std.mem.indexOfScalar(u8, content, '<');
        var next_item = if (self.poem_items.items.len != 0) std.mem.indexOf(u8, content, poem_prefix) else null;
        while (true) {
            if (next_tag) |at| if (at < pos) {
                next_tag = std.mem.indexOfScalarPos(u8, content, pos, '<');
            };
            if (next_item) |at| if (at < pos) {
                next_item = std.mem.indexOfPos(u8, content, pos, poem_prefix);
            };
            const open = next_tag orelse content.len;
            const marker = next_item orelse content.len;
            if (open == content.len and marker == content.len) break;
            if (marker < open) {
                const item = self.poemItemAt(content[marker..]) orelse {
                    pos = marker + poem_prefix.len;
                    continue;
                };
                pos = marker + item.token.len;
                if (item.kind != .literal or !std.mem.eql(u8, item.tag, "poem")) continue;
                if (self.poem_definition_dispatches >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    return;
                }
                self.poem_definition_dispatches += 1;
                const inner_open = std.mem.indexOfScalar(u8, item.body, '<') orelse continue;
                const inner_tag = syntax.tagAt(item.body, inner_open) orelse continue;
                if (!inner_tag.is("poem") or inner_tag.closing or inner_tag.self_closing) continue;
                const inner_pair = syntax.matchingTag(item.body, inner_tag) orelse continue;
                try self.referenceDefinitionsInner(item.body[inner_tag.end..inner_pair.inner_end], default_group, depth + 1);
                continue;
            }
            if (starts(content[open..], "<!--")) {
                pos = syntax.protectedEnd(content, open) orelse content.len;
                continue;
            }
            const tag = try self.semanticTagAt(content, open) orelse {
                pos = open + 1;
                continue;
            };
            pos = tag.end;
            if (!tag.closing and tag.is("references")) {
                const pair = opaque_scan.pair(content, tag) orelse continue;
                const own_group = ((try self.semanticAttribute(tag, "group")) orelse "");
                try self.referenceDefinitionsInner(content[tag.end..pair.inner_end], if (own_group.len != 0) own_group else default_group, depth + 1);
                pos = pair.end;
                continue;
            }
            if (!tag.closing and tag.isOpaque() and !tag.is("ref")) {
                pos = if (opaque_scan.pair(content, tag)) |pair| pair.end else tag.end;
                continue;
            }
            if (tag.closing or !tag.is("ref")) continue;
            const pair = opaque_scan.pair(content, tag) orelse continue;
            const name = ((try self.semanticAttribute(tag, "name")) orelse "");
            if (name.len == 0) {
                pos = pair.end;
                continue;
            }
            const own_group = ((try self.semanticAttribute(tag, "group")) orelse "");
            const group = if (own_group.len != 0) own_group else default_group;
            const body = if (tag.self_closing) "" else content[tag.end..pair.inner_end];
            var found = false;
            for (self.ref_defs.items) |*definition| {
                if (!std.mem.eql(u8, definition.name, name) or !std.mem.eql(u8, definition.group, group)) continue;
                if (definition.body.len == 0 and body.len != 0) definition.body = body;
                found = true;
                break;
            }
            if (!found) {
                if (self.ref_defs.items.len >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    return;
                }
                try self.ref_defs.append(self.a, .{ .name = name, .group = group, .body = body });
            }
            for (self.refs.items) |*ref| {
                if (std.mem.eql(u8, ref.name, name) and std.mem.eql(u8, ref.group, group) and ref.body.len == 0 and body.len != 0) ref.body = body;
            }
            pos = pair.end;
        }
    }
    pub fn finishReferences(self: *Renderer) Error![]const Reference {
        self.in_reference = true;
        defer self.in_reference = false;
        for (self.refs.items) |*ref| {
            const previous_depth = self.poem_depth;
            const previous_direction = self.poem_direction;
            const previous_style = self.poem_base_style;
            const previous_indent = self.poem_line_indent;
            self.poem_depth = if (ref.poem) 1 else 0;
            self.poem_direction = ref.poem_direction;
            self.poem_base_style = .{};
            self.poem_line_indent = 0;
            defer {
                self.poem_depth = previous_depth;
                self.poem_direction = previous_direction;
                self.poem_base_style = previous_style;
                self.poem_line_indent = previous_indent;
            }
            ref.spans = try self.parseSpans(if (ref.body.len != 0) ref.body else "Reference text unavailable", .{});
        }
