        if (std.ascii.eqlIgnoreCase(ext, ".pdf")) return .pdf;
        if (std.ascii.eqlIgnoreCase(ext, ".djvu") or std.ascii.eqlIgnoreCase(ext, ".djv")) return .djvu;
        if (std.ascii.eqlIgnoreCase(ext, ".svg")) return .svg;
