            return;
        }
        const input = if (self.navigation_target_probe != null) source else try self.externalSourceControls(try self.prepareUnmatchedOpaque(source));
        var it: ir.InlineIterator = .{
            .input = input,
            .bold = inherited.bold,
            .italic = inherited.italic,
            .renderer_boundaries = true,
            // Internal labels are hidden behind MediaWiki link holders before
            // external-link recognition. Keep one continuous inline flow for
            // HTML/quotes across literal bracket/URL text in that label.
            .recognize_external_links = inherited.kind != .link or inherited.poem_independent_parse,
            .link_trail = self.context.link_trail,
        };
        var no_more_nowiki_close = false;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (it.cursor < input.len) {
            if (self.truncated and self.span_limit_marker) return;
            var s = inherited;
            s.bold = it.bold;
            s.italic = it.italic;
