    _ = try r.renderBody("# {{lb|en|rare}} [[cat]] &eacute;<ref>''Book''</ref>\n\n{|\n! A !! B\n|-\n| 1 || {{l|fr|chat}}\n|}\n");
    _ = try r.finishReferences();
}
