        .{ .options = "thumb|175px|Authored caption", .expected = "Authored caption" },
        .{ .options = "thumbnail|noicon", .expected = "noicon" },
        .{ .options = "frame|autoplay", .expected = "autoplay" },
        .{ .options = "thumb|frameless|noicon", .expected = "noicon" },
