    var escaped: Renderer = .{ .a = a, .context = .{} };
    _ = try escaped.parseSpans("<imagemap>image:G50.png|x]] [[File:Other.png|other\ndefault [[wrong]]</imagemap>", .{});
    try std.testing.expectEqual(@as(usize, 0), escaped.media.items.len);
