    try std.testing.expectEqualStrings("inner", content);
    try std.testing.expectEqual(@as(usize, 0), table.caption.len);
    try std.testing.expectEqual(Kind.paragraph, blocks[2].kind);
    try std.testing.expectEqualStrings("tail", try flattened(a, blocks[2].spans));
    try std.testing.expectEqual(Kind.paragraph, blocks[3].kind);
    try std.testing.expectEqualStrings("after", try flattened(a, blocks[3].spans));
    // The nested table's local "::" is below the outer ":" layout indent.
    for (blocks, [_][]const u8{ ":", ":::", ":", "" }, [_]u8{ 1, 3, 1, 0 }) |block, path, depth| {
        try std.testing.expectEqualStrings(path, block.list_path);
        try std.testing.expectEqual(depth, block.depth);
    }
    try std.testing.expect(std.mem.indexOf(u8, content, "{|") == null);
    try std.testing.expect(std.mem.indexOf(u8, content, "|}") == null);
    try std.testing.expect(!nested.fallbacks.malformed_table);
    // Preserve the existing ordinary-table recovery diagnostic; this control
    // makes no fresh malformed-wikitext parity claim against MediaWiki.
    var unclosed: Renderer = .{ .a = a, .context = .{} };
    const recovered = try unclosed.renderBody(": {|\n| cell");
    try std.testing.expectEqual(Kind.table, recovered[0].kind);
    try std.testing.expectEqualStrings(":", recovered[0].list_path);
    try std.testing.expectEqualStrings("cell", try flattened(a, recovered[0].table.?.rows[0].cells[0].spans));
    try std.testing.expect(unclosed.fallbacks.malformed_table);
}

test "wiki table unowned nested source survives a later caption through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn spans(values: anytype, word: []const u8, target: []const u8, bold: bool, italic: bool) !void {
            var visible: std.ArrayList(u8) = .empty;
            defer visible.deinit(std.testing.allocator);
            var links: usize = 0;
            for (values) |span| {
                try visible.appendSlice(std.testing.allocator, span.text);
                if (comptime @hasField(@TypeOf(span), "trail"))
                    try visible.appendSlice(std.testing.allocator, span.trail);
                if (target.len == 0 or span.kind != .link or !std.mem.eql(u8, span.target, target)) continue;
                links += 1;
                try std.testing.expectEqualStrings(word, span.text);
                const actual_bold = if (comptime @hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                const actual_italic = if (comptime @hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                try std.testing.expectEqual(bold, actual_bold);
                try std.testing.expectEqual(italic, actual_italic);
            }
            try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, visible.items, word));
            try std.testing.expectEqual(@as(usize, if (target.len == 0) 0 else 1), links);
            for ([_][]const u8{ "{|", "|+", "|}" }) |marker|
                try std.testing.expect(std.mem.indexOf(u8, visible.items, marker) == null);
        }
        fn blocks(values: anytype, rich: bool) !void {
            try std.testing.expectEqual(@as(usize, 2), values.len);
            try std.testing.expect(values[0].kind == .table and values[1].kind == .table);
            const child = values[0].table.?;
            const outer = values[1].table.?;
            try std.testing.expectEqual(@as(usize, 0), child.caption.len);
            try std.testing.expectEqual(@as(usize, 1), child.rows.len);
            try std.testing.expectEqual(@as(usize, 1), child.rows[0].cells.len);
            try std.testing.expectEqual(@as(usize, 0), outer.rows.len);
            try spans(child.rows[0].cells[0].spans, if (rich) "Nested word" else "nested", if (rich) "nested" else "", rich, false);
            try spans(outer.caption, if (rich) "Caption word" else "caption", if (rich) "caption" else "", false, rich);
        }
        fn notes(values: anytype, rich: bool) !void {
            try std.testing.expectEqual(@as(usize, if (rich) 2 else 0), values.len);
            if (!rich) return;
            try spans(values[0].spans, "Nested note", "", false, false);
            try spans(values[1].spans, "Caption note", "", false, false);
        }
    };
    const cases = [_]struct { source: []const u8, rich: bool }{
        .{ .source = "{|\n{|\n| nested\n|}\n|+ caption\n|}", .rich = false },
        .{ .source = "{|\n{|\n| '''[[nested|Nested word]]''' <ref>Nested note</ref>\n|}\n|+ ''[[caption|Caption word]]'' <ref>Caption note</ref>\n|}", .rich = true },
    };
    for (cases) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        try Check.blocks(blocks, case.rich);
        const refs = try renderer.finishReferences();
        try Check.notes(refs, case.rich);
        for (refs, 0..) |reference, i| try std.testing.expectEqual(i + 1, reference.number);
        try std.testing.expect(!renderer.fallbacks.any());
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, refs, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "unowned nested table", .language, .{ .code = "en", .heading = "English" });
        try Check.blocks(decoded.entry.sections[0].blocks, case.rich);
        try Check.notes(decoded.entry.references, case.rich);
    }
}

test "wiki table boundary: caption-only tables retain links and continuation references" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var plain: Renderer = .{ .a = a, .context = .{} };
    const simple = try plain.renderBody("{|\n|+ Caption [[word]]\n|-\n|}");
    try std.testing.expectEqual(@as(usize, 1), simple.len);
    try std.testing.expectEqual(Kind.table, simple[0].kind);
    try std.testing.expectEqual(@as(usize, 0), simple[0].table.?.rows.len);
    try std.testing.expectEqualStrings("Caption word", try flattened(a, simple[0].table.?.caption));
    var word_link = false;
    for (simple[0].table.?.caption) |s| if (std.mem.eql(u8, s.text, "word")) {
        word_link = s.kind == .link and std.mem.eql(u8, s.target, "word");
    };
    try std.testing.expect(word_link);
    try std.testing.expect(!plain.fallbacks.malformed_table);
    var r: Renderer = .{ .a = a, .context = .{} };
    const blocks = try r.renderBody(": {|\nbefore <ref name=b>Before</ref>\n|+ Caption <ref name=c>Caption</ref>\nafter <ref name=a>After</ref>\n|-\n|}");
    try std.testing.expectEqual(@as(usize, 2), blocks.len);
    try std.testing.expectEqualStrings(":", blocks[0].list_path);
    try std.testing.expectEqual(Kind.table, blocks[1].kind);
    try std.testing.expectEqualStrings(":", blocks[1].list_path);
    const before_text = try flattened(a, blocks[0].spans);
    const caption_text = try flattened(a, blocks[1].table.?.caption);
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, before_text, "before"));
    try std.testing.expect(std.mem.indexOf(u8, before_text, "after") == null);
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, caption_text, "Caption"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, caption_text, "after"));
    try std.testing.expect(std.mem.indexOf(u8, caption_text, "|+") == null);
    try std.testing.expect(std.mem.indexOf(u8, caption_text, "|-") == null);
    const refs = try r.finishReferences();
    try std.testing.expectEqual(@as(usize, 3), refs.len);
    for ([_][]const u8{ "b", "c", "a" }, 0..) |name, i| {
        try std.testing.expectEqualStrings(name, refs[i].name);
        try std.testing.expectEqual(i + 1, refs[i].number);
    }
    try std.testing.expect(!r.fallbacks.malformed_table);
    var empty: Renderer = .{ .a = a, .context = .{} };
    const empty_blocks = try empty.renderBody("{|\n|+\n|}");
    try std.testing.expectEqual(Kind.table, empty_blocks[0].kind);
    try std.testing.expectEqual(@as(usize, 0), empty_blocks[0].table.?.caption.len);
    try std.testing.expect(!empty.fallbacks.malformed_table);
    var rowless: Renderer = .{ .a = a, .context = .{} };
    const recovery = try rowless.renderBody("{|\nloose\n|}");
    try std.testing.expectEqualStrings("loose", try flattened(a, recovery[0].spans));
    try std.testing.expect(rowless.fallbacks.malformed_table);
}

