fn unclosedExternalRecoveryHasLink(spans: []const Span, kind: @TypeOf(@as(Span, undefined).kind), target: []const u8) bool {
    for (spans) |span| {
        if (span.kind == kind and std.mem.eql(u8, span.target, target)) return true;
    }
    return false;
}

