    var r: Renderer = .{ .a = a, .context = .{} };
    const blocks = try r.renderBody("<table><caption>Forms</caption><tr><th rowspan='0'><b>Singular</b></th><td>[[cat]]</td></tr><tr><td><i>cats</i></td></tr></table>");
    const table = blocks[0].table.?;
