    try std.testing.expect(!spans[0].flags.code);
    const blocks = try renderer.renderBody("<table><tr><td colspan=\"<nowiki>2</nowiki>\">[[chat]]</td><td>[[Katze]]</td></tr></table>");
    const cells = blocks[0].table.?.rows[0].cells;
