test "authored media captions preserve visual classes roles and owner identity through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn spans(alloc: std.mem.Allocator, values: anytype) !void {
            var visible: std.ArrayList(u8) = .empty;
            var cat_text: std.ArrayList(u8) = .empty;
            var glyphs: usize = 0;
            var ipa: usize = 0;
            var references: usize = 0;
            var breaks: usize = 0;
            var outside: usize = 0;
            for (values) |span| {
                const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                const superscript = if (@hasField(@TypeOf(span), "flags")) span.flags.superscript else span.superscript;
                const trail = if (@hasField(@TypeOf(span), "trail")) span.trail else "";
                const plain = std.mem.eql(u8, std.mem.trim(u8, span.text, " \t"), "plain");
                var media: usize = 0;
                var owners: usize = 0;
                var egyp = false;
                var ipa_class = false;
                var classes = std.mem.tokenizeAny(u8, span.classes, " \t\r\n");
                while (classes.next()) |token| {
                    if (std.mem.eql(u8, token, "wikidict-media")) media += 1;
                    if (std.mem.startsWith(u8, token, "wikidict-media-file-")) {
                        owners += 1;
                        try std.testing.expectEqualStrings("wikidict-media-file-4361742e6a7067", token);
                    }
                    egyp = egyp or std.mem.eql(u8, token, "Egyp");
                    ipa_class = ipa_class or std.mem.eql(u8, token, "IPA");
                }
                try std.testing.expect(!code);
                if (plain) {
                    outside += 1;
                    try std.testing.expect(span.kind == .text and span.role == .normal);
                    try std.testing.expectEqualStrings("", span.target);
                    try std.testing.expectEqual(@as(usize, 0), media);
                    try std.testing.expectEqual(@as(usize, 0), owners);
                } else {
                    try std.testing.expectEqual(@as(usize, 1), media);
                    try std.testing.expectEqual(@as(usize, 1), owners);
                    try std.testing.expect(std.mem.eql(u8, span.target, "File:Cat.jpg") or std.mem.eql(u8, span.target, "cat") or std.mem.eql(u8, span.target, "#reference-1"));
                }
                if (std.mem.eql(u8, span.text, "𓀀")) {
                    glyphs += 1;
                    try std.testing.expect(egyp and span.role == .normal);
                    try std.testing.expectEqualStrings("egy", span.language);
                    try std.testing.expectEqualStrings("ltr", span.direction);
                } else try std.testing.expect(!egyp);
                if (std.mem.eql(u8, span.text, "/kat/")) {
                    ipa += 1;
                    try std.testing.expect(ipa_class and span.role == .pronunciation);
                } else try std.testing.expect(!ipa_class);
                if (std.mem.eql(u8, span.target, "#reference-1")) {
                    references += 1;
                    try std.testing.expect(span.kind == .link and span.role == .reference and superscript);
                    try std.testing.expectEqualStrings("[1]", span.text);
                } else try std.testing.expect(!superscript);
                if (std.mem.eql(u8, span.target, "cat")) {
                    try std.testing.expect(span.kind == .link);
                    try cat_text.appendSlice(alloc, span.text);
                    try cat_text.appendSlice(alloc, trail);
                }
                if (span.kind == .line_break) {
                    breaks += 1;
                    try std.testing.expectEqualStrings("", trail);
                    try visible.append(alloc, '\n');
                } else {
                    try std.testing.expect(span.kind == .text or span.kind == .link);
                    try visible.appendSlice(alloc, span.text);
                    try visible.appendSlice(alloc, trail);
                }
            }
            try std.testing.expectEqualStrings("𓀀 /kat/ [1] cats\ntail plain", visible.items);
            try std.testing.expectEqualStrings("cats", cat_text.items);
            try std.testing.expectEqual(@as(usize, 1), glyphs);
            try std.testing.expectEqual(@as(usize, 1), ipa);
            try std.testing.expectEqual(@as(usize, 1), references);
            try std.testing.expectEqual(@as(usize, 1), breaks);
            try std.testing.expectEqual(@as(usize, 1), outside);
        }
    };
    const source = "[[File:Cat.jpg|thumb|<span class=\"Egyp wikidict-media-file-666f72676564\" lang=\"egy\" dir=\"ltr\">𓀀</span> <span class=\"IPA\">/kat/</span> <ref name=caption>caption note</ref> [[cat]]s<br>tail]] plain";
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    const references = try renderer.finishReferences();
    try std.testing.expectEqual(@as(usize, 1), blocks.len);
    try Check.spans(a, blocks[0].spans);
    try std.testing.expectEqual(@as(usize, 1), renderer.media.items.len);
    try std.testing.expectEqualStrings("Cat.jpg", renderer.media.items[0].file);
    try std.testing.expectEqualStrings("𓀀 /kat/ [1] cats\ntail", renderer.media.items[0].caption);
    try std.testing.expectEqual(@as(usize, 1), references.len);
    try std.testing.expectEqualStrings("caption note", try plainText(a, references[0].spans));
    try std.testing.expect(!renderer.fallbacks.any());
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    const sections = [_]Section{.{ .blocks = blocks }};
    const blob = @import("blob_encoder");
    const payload = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, renderer.media.items);
    const decoded = try blob.presentation_codec.decodeAlloc(a, payload, "caption visual metadata", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.sections[0].blocks.len);
    try Check.spans(a, decoded.entry.sections[0].blocks[0].spans);
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.references.len);
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.media.len);
    try std.testing.expectEqualStrings(renderer.media.items[0].caption, decoded.entry.media[0].caption);
}

test "media owner assignment preserves inherited visual classes through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var class_renderer: Renderer = .{ .a = a, .context = .{} };
    const owned = "wikidict-media wikidict-media-file-4361742e6a7067 Egyp";
    try std.testing.expectEqualStrings(owned, try class_renderer.mediaCaptionClasses(owned, "Egyp"));
    try std.testing.expectEqualStrings(owned, try class_renderer.mediaCaptionClasses(owned, owned));
    try std.testing.expectEqualStrings("wikidict-media wikidict-media-file-4361742e6a7067 Egyp IPA", try class_renderer.mediaCaptionClasses(owned, "Egyp IPA"));

    const Check = struct {
        fn blocks(alloc: std.mem.Allocator, values: anytype) !void {
            var visible: std.ArrayList(u8) = .empty;
            var glyphs: usize = 0;
            var outside: usize = 0;
            for (values) |block_value| for (block_value.spans) |span| {
                const trail = if (@hasField(@TypeOf(span), "trail")) span.trail else "";
                var egyp: usize = 0;
                var media: usize = 0;
                var owners: usize = 0;
                var classes = std.mem.tokenizeAny(u8, span.classes, " \t\r\n");
                while (classes.next()) |token| {
                    if (std.mem.eql(u8, token, "Egyp")) egyp += 1;
                    if (std.mem.eql(u8, token, "wikidict-media")) media += 1;
                    if (std.mem.startsWith(u8, token, "wikidict-media-file-")) {
                        owners += 1;
                        try std.testing.expectEqualStrings("wikidict-media-file-4361742e6a7067", token);
                    }
                }
                if (std.mem.eql(u8, span.text, "𓀀")) {
                    glyphs += 1;
                    try std.testing.expectEqual(@as(usize, 1), egyp);
                    try std.testing.expectEqual(@as(usize, 1), media);
                    try std.testing.expectEqual(@as(usize, 1), owners);
                    try std.testing.expect(span.kind == .link and span.role == .normal);
                    try std.testing.expectEqualStrings("File:Cat.jpg", span.target);
                    try std.testing.expectEqualStrings("egy", span.language);
                    try std.testing.expectEqualStrings("ltr", span.direction);
                } else {
                    try std.testing.expectEqualStrings("plain", std.mem.trim(u8, span.text, " \t\r\n"));
                    outside += 1;
                    try std.testing.expect(span.kind == .text and span.role == .normal);
                    try std.testing.expectEqualStrings("", span.target);
                    try std.testing.expectEqualStrings("", span.language);
                    try std.testing.expectEqualStrings("", span.direction);
                    try std.testing.expectEqual(@as(usize, 0), egyp + media + owners);
                }
                try std.testing.expectEqualStrings("", trail);
                try visible.appendSlice(alloc, span.text);
            };
            try std.testing.expectEqualStrings("𓀀 plain", visible.items);
            try std.testing.expectEqual(@as(usize, 1), glyphs);
            try std.testing.expectEqual(@as(usize, 1), outside);
        }
    };
    const cases = [_][]const u8{
        "<span class=\"Egyp wikidict-media-file-666f72676564\" lang=egy dir=ltr>[[File:Cat.jpg|thumb|𓀀]]</span> plain",
        "<span class=\"Egyp wikidict-media-file-666f72676564\" lang=egy dir=ltr><gallery>Cat.jpg|𓀀</gallery></span> plain",
    };
    for (cases) |source| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        try Check.blocks(a, blocks);
        try std.testing.expectEqual(@as(usize, 1), renderer.media.items.len);
        try std.testing.expectEqualStrings("Cat.jpg", renderer.media.items[0].file);
        try std.testing.expectEqualStrings("𓀀", renderer.media.items[0].caption);
        try std.testing.expect(!renderer.fallbacks.any());
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "inherited media classes", .language, .{ .code = "en", .heading = "English" });
        try Check.blocks(a, decoded.entry.sections[0].blocks);
        try std.testing.expectEqual(@as(usize, 1), decoded.entry.media.len);
        try std.testing.expectEqualStrings("𓀀", decoded.entry.media[0].caption);
    }
}

test "media caption occurrences register references once across files galleries Phonos and audio through DPR2" {
    const Check = struct {
        fn values(a: A, blocks: anytype, references: anytype, notes: []const []const u8, markers: []const usize) !void {
            try std.testing.expectEqual(notes.len, references.len);
            var index: usize = 0;
            for (blocks) |block_value| for (block_value.spans) |span| {
                if (span.role != .reference) continue;
                try std.testing.expect(index < markers.len);
                try std.testing.expect(span.kind == .link);
                try std.testing.expect(if (@hasField(@TypeOf(span), "flags")) span.flags.superscript else span.superscript);
                try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "#reference-{d}", .{markers[index]}), span.target);
                try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "[{d}]", .{markers[index]}), span.text);
                index += 1;
            };
            try std.testing.expectEqual(markers.len, index);
            for (references, notes) |reference_value, note| {
                var text: std.ArrayList(u8) = .empty;
                for (reference_value.spans) |span| {
                    try text.appendSlice(a, span.text);
                    if (@hasField(@TypeOf(span), "trail")) try text.appendSlice(a, span.trail);
                }
                try std.testing.expectEqualStrings(note, text.items);
            }
        }
    };
    const cases = [_]struct { source: []const u8, notes: []const []const u8, markers: []const usize }{
        .{ .source = "[[File:Example.jpg|thumb|caption<ref>note</ref>]]", .notes = &.{"note"}, .markers = &.{1} },
        .{ .source = "[[File:Example.jpg|thumb|first<ref>one</ref>]] [[File:Example.jpg|thumb|second<ref>two</ref>]]", .notes = &.{ "one", "two" }, .markers = &.{ 1, 2 } },
        .{ .source = "[[File:Example.jpg|thumb|first<ref>same</ref>]] [[File:Example.jpg|thumb|second<ref>same</ref>]]", .notes = &.{ "same", "same" }, .markers = &.{ 1, 2 } },
        .{ .source = "[[File:Example.jpg|thumb|first<ref name='n'>named</ref>]] [[File:Example.jpg|thumb|second<ref name='n'/>]]", .notes = &.{"named"}, .markers = &.{ 1, 1 } },
        .{ .source = "<gallery>\nFile:Example.jpg|first<ref>one</ref>\nFile:Example.jpg|second<ref>two</ref>\n</gallery>", .notes = &.{ "one", "two" }, .markers = &.{ 1, 2 } },
        .{ .source = "<span data-phonos-audio='Example.ogg'>caption<ref>note</ref></span>", .notes = &.{"note"}, .markers = &.{1} },
        .{ .source = "{{audio|en|Example.ogg|caption<ref>note</ref>}}", .notes = &.{"note"}, .markers = &.{1} },
    };
    for (cases) |case| {
        errdefer std.debug.print("caption reference source: {s}\n", .{case.source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        const references = try renderer.finishReferences();
        try Check.values(a, blocks, references, case.notes, case.markers);
        try std.testing.expectEqual(@as(usize, 1), renderer.media.items.len);
        try std.testing.expect(!renderer.fallbacks.any());
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "caption references", .language, .{ .code = "en", .heading = "English" });
        try Check.values(a, decoded.entry.sections[0].blocks, decoded.entry.references, case.notes, case.markers);
        try std.testing.expectEqual(@as(usize, 1), decoded.entry.media.len);
    }
}

test "HTML table captions isolate outer navigation while retaining inline language style and pre state through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Word = struct { text: []const u8, target: []const u8 = "", bold: bool = false };
    const Check = struct {
        fn spans(alloc: A, values: anytype, expected: []const Word) !void {
            var text: std.ArrayList(u8) = .empty;
            var targets: std.ArrayList([]const u8) = .empty;
            var linked: std.ArrayList(bool) = .empty;
            var bold: std.ArrayList(bool) = .empty;
            var pending_space = false;
            for (values) |span| {
                if (span.target.len != 0) {
                    try std.testing.expect(span.kind == .link);
                    var allowed_target = false;
                    for (expected) |word| {
                        if (word.target.len != 0 and std.mem.eql(u8, span.target, word.target)) {
                            allowed_target = true;
                            break;
                        }
                    }
                    try std.testing.expect(allowed_target);
                }
                const parts = if (@hasField(@TypeOf(span), "trail"))
                    [_][]const u8{ span.text, span.trail }
                else
                    [_][]const u8{ span.text, "" };
                if (span.kind == .line_break) pending_space = text.items.len != 0;
                for (parts) |part| for (part) |byte| {
                    if (std.ascii.isWhitespace(byte)) {
                        pending_space = text.items.len != 0;
                        continue;
                    }
                    if (pending_space) {
                        try text.append(alloc, ' ');
                        try targets.append(alloc, "");
                        try linked.append(alloc, false);
                        try bold.append(alloc, false);
                        pending_space = false;
                    }
                    try text.append(alloc, byte);
                    try targets.append(alloc, span.target);
                    try linked.append(alloc, span.kind == .link);
                    try bold.append(alloc, if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold);
                    const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                    try std.testing.expect(!code);
                };
            }
            var wanted: std.ArrayList(u8) = .empty;
            for (expected, 0..) |word, i| {
                if (i != 0) try wanted.append(alloc, ' ');
                try wanted.appendSlice(alloc, word.text);
            }
            try std.testing.expectEqualStrings(wanted.items, text.items);
            var offset: usize = 0;
            for (expected, 0..) |word, i| {
                if (i != 0) offset += 1;
                for (word.text) |_| {
                    try std.testing.expectEqualStrings(word.target, targets.items[offset]);
                    try std.testing.expectEqual(word.target.len != 0, linked.items[offset]);
                    try std.testing.expectEqual(word.bold, bold.items[offset]);
                    offset += 1;
                }
            }
        }
        fn captionLanguage(values: anytype, language: []const u8, direction: []const u8) !void {
            for (values) |span| {
                try std.testing.expectEqualStrings(language, span.language);
                try std.testing.expectEqualStrings(direction, span.direction);
            }
        }
        fn blocks(alloc: A, values: anytype, styled: bool) !void {
            try std.testing.expectEqual(@as(usize, 3), values.len);
            try std.testing.expect(values[0].kind == .paragraph);
            try spans(alloc, values[0].spans, &.{.{ .text = "lead", .target = "Target" }});
            try std.testing.expect(values[1].kind == .table);
            const table = values[1].table.?;
            try spans(alloc, table.caption, &.{.{ .text = "cap", .bold = styled }});
            try captionLanguage(table.caption, if (styled) "fr" else "", if (styled) "rtl" else "");
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            try spans(alloc, table.rows[0].cells[0].spans, &.{.{ .text = "cell" }});
            try std.testing.expect(values[2].kind == .paragraph);
            try spans(alloc, values[2].spans, &.{ .{ .text = "end", .target = "Target" }, .{ .text = "outside" } });
        }
        fn explicit(alloc: A, values: anytype) !void {
            try std.testing.expectEqual(@as(usize, 2), values.len);
            try std.testing.expect(values[0].kind == .table);
            const table = values[0].table.?;
            try spans(alloc, table.caption, &.{ .{ .text = "cap", .bold = true }, .{ .text = "explicit", .target = "cat" } });
            try captionLanguage(table.caption, "fr", "rtl");
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            try spans(alloc, table.rows[0].cells[0].spans, &.{.{ .text = "cell" }});
            try captionLanguage(table.rows[0].cells[0].spans, "de", "ltr");
            try spans(alloc, values[1].spans, &.{.{ .text = "outside" }});
            try captionLanguage(values[1].spans, "", "");
        }
    };
    // Current explicit legacy capture01: both table spellings isolate cap/cell
    // while the admitted outer target resumes for end and stops before outside.
    const cases = [_][]const u8{
        "[[Target|lead\n<table><caption>cap</caption><tr><td>cell</td></tr></table>\nend]] outside",
        "[[Target|lead\n{|\n|+ cap\n|-\n| cell\n|}\nend]] outside",
        "[[Target|lead\n<table><caption lang=fr dir=rtl><b>cap</b></caption><tr><td>cell</td></tr></table>\nend]] outside",
        "<table lang=de dir=ltr><caption lang=fr dir=rtl><b>cap</b> [[cat|explicit]]</caption><tr><td>cell</td></tr></table>\noutside",
    };
    for (cases, 0..) |source, index| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        if (index == 3) try Check.explicit(a, blocks) else try Check.blocks(a, blocks, index == 2);
        try std.testing.expectEqualStrings("", renderer.body_link_target);
        try std.testing.expect(renderer.body_language_direction == null);
        try std.testing.expect(!renderer.fallbacks.literal_markup);
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "HTML caption boundary", .language, .{ .code = "en", .heading = "English" });
        if (index == 3) try Check.explicit(a, decoded.entry.sections[0].blocks) else try Check.blocks(a, decoded.entry.sections[0].blocks, index == 2);
    }
    // Entering a local caption must not reset an existing preformatted mode.
    var pre: Renderer = .{ .a = a, .context = .{}, .parsed_pre = true, .body_link_target = "Outer" };
    const pre_spans = try pre.parseSpansWithLanguageDirection("a\nb", .{ .language = "fr", .direction = "rtl" });
    try std.testing.expectEqualStrings("a\nb", try plainText(a, pre_spans));
    for (pre_spans) |span| {
        try std.testing.expectEqualStrings("", span.target);
        try std.testing.expect(span.flags.code);
        try std.testing.expectEqualStrings("fr", span.language);
        try std.testing.expectEqualStrings("rtl", span.direction);
    }
    const PreSection = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    const pre_blocks = [_]Block{.{ .kind = .preformatted, .spans = pre_spans }};
    const pre_sections = [_]PreSection{.{ .blocks = &pre_blocks }};
    const blob = @import("blob_encoder");
    const pre_bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &pre_sections, blob.presentation_types.Layout{}, pre.refs.items, pre.media.items);
    const pre_decoded = try blob.presentation_codec.decodeAlloc(a, pre_bytes, "HTML caption pre state", .language, .{ .code = "en", .heading = "English" });
    const decoded_pre = pre_decoded.entry.sections[0].blocks[0];
    try std.testing.expect(decoded_pre.kind == .preformatted);
    var decoded_text: std.ArrayList(u8) = .empty;
    for (decoded_pre.spans) |span| {
        try decoded_text.appendSlice(a, span.text);
        try decoded_text.appendSlice(a, span.trail);
        try std.testing.expectEqualStrings("", span.target);
        try std.testing.expect(span.code);
        try std.testing.expectEqualStrings("fr", span.language);
        try std.testing.expectEqualStrings("rtl", span.direction);
    }
    try std.testing.expectEqualStrings("a\nb", decoded_text.items);
    try std.testing.expect(pre.parsed_pre);
    try std.testing.expectEqualStrings("Outer", pre.body_link_target);
    try std.testing.expect(pre.body_language_direction == null);
}

test "encoded LF and tab remain soft outside preformatted text through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn blocks(alloc: std.mem.Allocator, values: anytype, expected: []const u8, body_code: bool, expected_breaks: ?usize) !void {
            var body: std.ArrayList(u8) = .empty;
            var links: usize = 0;
            var breaks: usize = 0;
            for (values) |block_value| for (block_value.spans) |span| {
                const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                const trail = if (@hasField(@TypeOf(span), "trail")) span.trail else "";
                try std.testing.expectEqualStrings("", trail);
                if (span.kind == .link) {
                    links += 1;
                    try std.testing.expectEqualStrings("word", span.text);
                    try std.testing.expectEqualStrings("cat", span.target);
                    try std.testing.expect(!code);
                } else {
                    try std.testing.expect(span.kind == .text or span.kind == .line_break);
                    try std.testing.expectEqualStrings("", span.target);
                    if (links == 0) {
                        if (span.kind == .line_break) {
                            breaks += 1;
                            try body.append(alloc, '\n');
                        } else {
                            try body.appendSlice(alloc, span.text);
                            if (std.mem.trim(u8, span.text, " \t\r\n").len != 0)
                                try std.testing.expectEqual(body_code, code);
                        }
                    } else {
                        try std.testing.expectEqualStrings("", std.mem.trim(u8, span.text, " \t\r\n"));
                    }
                }
            };
            try std.testing.expectEqual(@as(usize, 1), links);
            try std.testing.expectEqualStrings(expected, std.mem.trim(u8, body.items, " \t\r\n"));
            if (expected_breaks) |count| try std.testing.expectEqual(count, breaks);
        }
    };
    // Current official legacy captures keep encoded LF/HT in normal p text,
    // including Poem. Only the actual authored Poem LF creates a br. Numeric
    // CR remains literal source spelling; syntaxhighlight never decodes these.
    const cases = [_]struct { source: []const u8, body: []const u8, code: bool = false, breaks: ?usize = null }{
        .{
            .source = "plain a&#10;b c&#9;d e&#13;f g&NewLine;h i&Tab;j; nowiki <nowiki>a&#10;b c&#9;d e&#13;f g&NewLine;h i&Tab;j</nowiki> [[cat|word]]",
            .body = "plain a b c d e&#13;f g h i j; nowiki a b c d e&#13;f g h i j",
            .breaks = 0,
        },
        .{
            .source = "<pre/ >a&#10;b c&#9;d e&#13;f g&NewLine;h i&Tab;j <nowiki>k&#10;l m&#9;n</nowiki>\nactual LF</pre> [[cat|word]]",
            .body = "a\nb c\td e&#13;f g\nh i\tj k\nl m\tn\nactual LF",
            .code = true,
        },
        .{
            .source = "<poem>a&#10;b c&#9;d e&#13;f g&NewLine;h i&Tab;j\n<nowiki>k&#10;l m&#9;n</nowiki> [[cat|word]]</poem>",
            .body = "a b c d e&#13;f g h i j\nk l m n",
            .breaks = 1,
        },
        .{
            .source = "<syntaxhighlight lang=\"text\">a&#10;b c&#9;d e&#13;f g&NewLine;h i&Tab;j\nactual LF</syntaxhighlight> [[cat|word]]",
            .body = "a&#10;b c&#9;d e&#13;f g&NewLine;h i&Tab;j\nactual LF",
            .code = true,
        },
        .{
            .source = "<nowiki>a&amp;#10;b &amp;NewLine; [[fake]]</nowiki> [[cat|word]]",
            .body = "a&#10;b &NewLine; [[fake]]",
            .breaks = 0,
        },
    };
    for (cases) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        try Check.blocks(a, blocks, case.body, case.code, case.breaks);
        try std.testing.expect(!renderer.fallbacks.any());
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const payload = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, payload, "encoded whitespace", .language, .{ .code = "en", .heading = "English" });
        try std.testing.expectEqual(@as(usize, 1), decoded.entry.sections.len);
        try Check.blocks(a, decoded.entry.sections[0].blocks, case.body, case.code, case.breaks);
    }
}

test "matched noinclude bodies retain structural content and diagnostics through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn spans(alloc: std.mem.Allocator, values: anytype, expected: []const u8, target: []const u8, linked_text: []const u8) !void {
            var visible: std.ArrayList(u8) = .empty;
            var linked: std.ArrayList(u8) = .empty;
            for (values) |span| {
                if (span.target.len != 0) {
                    try std.testing.expect(span.kind == .link);
                    try std.testing.expectEqualStrings(target, span.target);
                }
                const parts = if (@hasField(@TypeOf(span), "trail"))
                    [_][]const u8{ span.text, span.trail }
                else
                    [_][]const u8{ span.text, "" };
                for (parts) |part| {
                    try visible.appendSlice(alloc, part);
                    if (span.target.len != 0) try linked.appendSlice(alloc, part);
                }
                const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                try std.testing.expect(!code);
            }
            try std.testing.expectEqualStrings(expected, visible.items);
            try std.testing.expectEqualStrings(linked_text, linked.items);
        }
        fn blocks(alloc: std.mem.Allocator, values: anytype, case_index: usize) !void {
            switch (case_index) {
                0 => {
                    try std.testing.expectEqual(@as(usize, 4), values.len);
                    try std.testing.expect(values[0].kind == .table);
                    const table = values[0].table.?;
                    try std.testing.expectEqual(@as(usize, 1), table.rows.len);
                    try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
                    const cell = table.rows[0].cells[0];
                    try std.testing.expectEqual(@as(u16, 1), cell.colspan);
                    try std.testing.expectEqual(@as(u16, 1), cell.rowspan);
                    try spans(alloc, cell.spans, "cell", "cat", "cell");
                    try std.testing.expect(values[1].kind == .rule);
                    try std.testing.expect(values[2].kind == .list_detail);
                    try std.testing.expectEqual(@as(u8, 1), values[2].depth);
                    try std.testing.expectEqualStrings(":", values[2].list_path);
                    try spans(alloc, values[2].spans, "documentation", "dog", "documentation");
                    try std.testing.expect(values[3].kind == .paragraph);
                    try spans(alloc, values[3].spans, "after", "bird", "after");
                },
                1 => {
                    try std.testing.expectEqual(@as(usize, 2), values.len);
                    try std.testing.expect(values[0].kind == .heading);
                    try std.testing.expectEqual(@as(u8, 2), values[0].level);
                    try spans(alloc, values[0].spans, "French", "", "");
                    try std.testing.expect(values[1].kind == .paragraph);
                    try spans(alloc, values[1].spans, "word", "cat", "word");
                },
                2 => {
                    try std.testing.expectEqual(@as(usize, 1), values.len);
                    try std.testing.expect(values[0].kind == .paragraph);
                    try spans(alloc, values[0].spans, "kept", "dog", "kept");
                },
                3 => {
                    try std.testing.expectEqual(@as(usize, 1), values.len);
                    try std.testing.expect(values[0].kind == .paragraph);
                    try spans(alloc, values[0].spans, "<noinclude> [[fake]] </noinclude> real", "cat", "real");
                },
                else => unreachable,
            }
        }
    };
    const sources = [_][]const u8{
        "{|\n| [[cat|cell]]\n|}<noinclude>\n<div class=\"documentation\">\n----\n<dl><dd>[[dog|documentation]]</dd></dl>\n</div>\n</noinclude> [[bird|after]]",
        "<noinclude>\n==French==\n[[cat|word]]\n</noinclude>",
        "<noinclude>[[dog|kept]]",
        "<nowiki><noinclude>\n[[fake]]\n</noinclude></nowiki> [[cat|real]]",
    };
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    const blob = @import("blob_encoder");
    for (sources, 0..) |source, case_index| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const result = try renderer.renderBody(source);
        errdefer std.debug.print("noinclude case {d}: {s}\n", .{ case_index, source });
        try Check.blocks(a, result, case_index);
        try std.testing.expectEqual(case_index == 2, renderer.fallbacks.unclosed_formatting);
        if (case_index != 2) try std.testing.expect(!renderer.fallbacks.any());
        const sections = [_]Section{.{ .blocks = result }};
        const payload = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, payload, "noinclude boundary", .language, .{ .code = "en", .heading = "English" });
        try Check.blocks(a, decoded.entry.sections[0].blocks, case_index);
    }
}

test "restored raw hiero preserves glyph styling without decoding authored separators through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn blocks(values: anytype, prefix: []const u8, prefix_code: bool, glyphs: bool) !void {
            var position: usize = 0;
            const suffix = "after";
            for (values) |block_value| {
                try std.testing.expect(block_value.kind == .paragraph or block_value.kind == .preformatted);
                try std.testing.expect(block_value.table == null);
                for (block_value.spans) |span| {
                    if (span.target.len != 0) {
                        try std.testing.expect(span.kind == .link);
                        try std.testing.expectEqualStrings("cat", span.target);
                    }
                    const parts = if (@hasField(@TypeOf(span), "trail"))
                        [_][]const u8{ span.text, span.trail }
                    else
                        [_][]const u8{ span.text, "" };
                    for (parts) |part| for (part) |byte| {
                        if (std.ascii.isWhitespace(byte)) continue;
                        try std.testing.expect(position < prefix.len + suffix.len);
                        const in_prefix = position < prefix.len;
                        const expected = if (in_prefix) prefix[position] else suffix[position - prefix.len];
                        try std.testing.expectEqual(expected, byte);
                        const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                        try std.testing.expectEqual(in_prefix and prefix_code, code);
                        try std.testing.expectEqualStrings(if (in_prefix) "" else "cat", span.target);
                        try std.testing.expect(if (in_prefix) span.kind == .text else span.kind == .link);
                        try std.testing.expectEqualStrings(if (in_prefix and glyphs) "egy" else "", span.language);
                        try std.testing.expectEqualStrings(if (in_prefix and glyphs) "ltr" else "", span.direction);
                        try std.testing.expectEqualStrings(if (in_prefix and glyphs) "Egyp" else "", span.classes);
                        position += 1;
                    };
                }
            }
            try std.testing.expectEqual(prefix.len + suffix.len, position);
        }
    };
    const cases = [_]struct { source: []const u8, prefix: []const u8, code: bool = false, glyphs: bool = false, unsupported: bool = false }{
        .{ .source = "<hiero>D35:t*y-nDs-f</hiero> [[cat|after]]", .prefix = "𓂜𓐰𓏏𓐱𓏭𓅪𓆑", .glyphs = true },
        .{ .source = "<hiero>D35&#58;t&#42;y-nDs-f</hiero> [[cat|after]]", .prefix = "D35:t*y-nDs-f", .code = true, .unsupported = true },
        .{ .source = "<hiero>D35&amp;#58;t&amp;#42;y-nDs-f</hiero> [[cat|after]]", .prefix = "D35&#58;t&#42;y-nDs-f", .code = true, .unsupported = true },
        .{ .source = "<nowiki><hiero>D35:t*y-nDs-f</hiero></nowiki> [[cat|after]]", .prefix = "<hiero>D35:t*y-nDs-f</hiero>" },
        .{ .source = "<source><hiero>D35&#58;t&#42;y-nDs-f</hiero></source> [[cat|after]]", .prefix = "<hiero>D35&#58;t&#42;y-nDs-f</hiero>", .code = true },
    };
    const Section = struct { level: u8 = 2, title: []const u8 = "Egyptian", blocks: []const Block };
    const blob = @import("blob_encoder");
    for (cases, 0..) |case, case_index| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        errdefer std.debug.print("hiero separator case {d}: {s}\n", .{ case_index, case.source });
        try Check.blocks(blocks, case.prefix, case.code, case.glyphs);
        try std.testing.expectEqual(case.unsupported, renderer.fallbacks.unsupported_element);
        try std.testing.expect(!renderer.fallbacks.unclosed_formatting);
        if (!case.unsupported) try std.testing.expect(!renderer.fallbacks.any());
        const sections = [_]Section{.{ .blocks = blocks }};
        const payload = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, payload, "hiero separators", .language, .{ .code = "egy", .heading = "Egyptian" });
        try Check.blocks(decoded.entry.sections[0].blocks, case.prefix, case.code, case.glyphs);
    }
}

test "single-cell layout grid admission preserves outer table semantics" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const grid = "{|\n! head !! other\n|-\n| one || two\n|}\n";
    const admitted = "|-\n|<div>before\n" ++ grid ++ "after</div>\n|}suffix";
    const layout = (try r.singleCellLayoutTable(admitted, 0)).?;
    try std.testing.expectEqualStrings("<div>before\n" ++ grid ++ "after</div>\n", layout.body);
    try std.testing.expectEqualStrings("suffix", admitted[layout.end..]);
    inline for (.{
        "|+\ncaption\n|-\n|",
        "|-\n!",
        "|-\n| colspan=2 |",
        "|-\n| colspan=0 |",
        "|-\n| rowspan=0 |",
        "|-\n| rowspan=2 |",
        "|-\n| colspan=invalid |",
        "fostered\n|-\n|",
    }) |prefix| {
        try std.testing.expect(try r.singleCellLayoutTable(prefix ++ "<div>\n" ++ grid ++ "</div>\n|}", 0) == null);
    }
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<div>\n" ++ grid ++ "</div>\n| second\n|}", 0) == null);
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<div>\n" ++ grid ++ "</div>\n|-\n| second\n|}", 0) == null);
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<div>\n" ++ grid ++ "</div> || second\n|}", 0) == null);
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<div>\n" ++ grid ++ "</div>", 0) == null);
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<nowiki>\n" ++ grid ++ "</nowiki>\n|}", 0) == null);
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<!--\n" ++ grid ++ "-->\n|}", 0) == null);
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<source>\n" ++ grid ++ "</source>\n|}", 0) == null);
    inline for (.{ "</pre>", "" }) |closer| {
        try std.testing.expect(try r.singleCellLayoutTable("|-\n|<pre>\n" ++ grid ++ closer ++ "\n|}", 0) == null);
    }
    try std.testing.expect(try r.singleCellLayoutTable("|-\n|<ref>\n" ++ grid ++ "</ref>\n|}", 0) == null);
    inline for (.{ "code", "tt", "kbd", "samp" }) |tag_name| {
        try std.testing.expect(try r.singleCellLayoutTable("|-\n|<" ++ tag_name ++ ">prefix\n" ++ grid ++ "</" ++ tag_name ++ ">\n|}", 0) == null);
    }
}

test "single-cell layout grid renders effects once and restores navigation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    r.body_link_target = "Outer";
    const blocks = try r.renderBody("{|\n|-\n|<div>before<ref>first note</ref>\n" ++
        "{|\n|+ [[Caption|caption]]\n! colspan=2 | header\n|-\n| rowspan=2 | [[Cell|one]] || [[File:Grid.png|thumb|media]]\n" ++
        "|-\n| two\n|}\nafter<ref>second note</ref></div>\n|}[[Suffix|suffix]]");
    try std.testing.expectEqualStrings("Outer", r.body_link_target);
    try std.testing.expectEqual(@as(usize, 4), blocks.len);
    const table = blocks[1].table.?;
    try std.testing.expectEqual(@as(usize, 3), table.rows.len);
    try std.testing.expectEqual(@as(u16, 2), table.rows[0].cells[0].colspan);
    try std.testing.expect(table.rows[0].cells[0].header);
    try std.testing.expectEqual(@as(u16, 2), table.rows[1].cells[0].rowspan);
    try std.testing.expectEqual(@as(usize, 1), r.media.items.len);
    const references = try r.finishReferences();
    try std.testing.expectEqual(@as(usize, 2), references.len);
    var cell_target = false;
    for (table.rows[1].cells[0].spans) |span| {
        try std.testing.expect(!std.mem.eql(u8, span.target, "Outer"));
        if (std.mem.eql(u8, span.target, "Cell")) cell_target = true;
    }
    try std.testing.expect(cell_target);
    var suffix_target = false;
    for (blocks[3].spans) |span| {
        if (std.mem.eql(u8, span.target, "Suffix")) suffix_target = true;
    }
    try std.testing.expect(suffix_target);
}

test "single-cell layout grid keeps a fresh cell quote domain" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const input = "{|\n|-\n|<div>prefix\n* item\n{|\n! header\n|-\n| cell\n|}\n</div>\n|}";
    var ordinary: Renderer = .{ .a = a, .context = .{} };
    const standalone = try ordinary.renderBody(input);
    var linked: Renderer = .{ .a = a, .context = .{} };
    linked.body_link_target = "Outer";
    const seed: QuoteSeed = .{
        .state = .none,
        .correction = null,
        .line_end = input.len,
        .boundaries = QuoteBoundaries.init(input),
        .label_scope = true,
    };
    const inherited = try linked.renderBodySlice(input, false, false, null, seed);
    try std.testing.expectEqual(standalone.len, inherited.len);
    var lists: usize = 0;
    for (standalone, inherited) |plain, scoped| {
        try std.testing.expectEqual(plain.kind, scoped.kind);
        try std.testing.expectEqualStrings(plain.list_path, scoped.list_path);
        try std.testing.expectEqualStrings(try flattened(a, plain.spans), try flattened(a, scoped.spans));
        if (scoped.kind == .list_item) {
            lists += 1;
            try std.testing.expectEqualStrings("item", try flattened(a, scoped.spans));
            for (scoped.spans) |span| try std.testing.expect(!std.mem.eql(u8, span.target, "Outer"));
        }
    }
    try std.testing.expectEqual(@as(usize, 1), lists);
    try std.testing.expectEqualStrings("Outer", linked.body_link_target);

    // The same matched block-wrapper path must retain DOM language/direction
    // when a layout cell becomes root blocks, including partial overrides.
    var language: Renderer = .{ .a = a, .context = .{} };
    const scoped = try language.renderBody(
        "<div lang=fr dir=rtl>[[Inherited|parent]]\n" ++
            "<div lang=de>[[Language|language]]</div>\n" ++
            "<div dir=ltr>[[Direction|direction]]</div>\n" ++
            "<div lang=\"\" dir=auto>[[Reset|reset]]</div>\n" ++
            "[[Sibling|sibling]]</div>[[Outside|outside]]",
    );
    const expected = [_]struct { target: []const u8, language: []const u8, direction: []const u8 }{
        .{ .target = "Inherited", .language = "fr", .direction = "rtl" },
        .{ .target = "Language", .language = "de", .direction = "rtl" },
        .{ .target = "Direction", .language = "fr", .direction = "ltr" },
        .{ .target = "Reset", .language = "", .direction = "auto" },
        .{ .target = "Sibling", .language = "fr", .direction = "rtl" },
        .{ .target = "Outside", .language = "", .direction = "" },
    };
    var seen: [expected.len]usize = @splat(0);
    for (scoped) |block| for (block.spans) |span| {
        for (expected, 0..) |wanted, i| {
            if (!std.mem.eql(u8, span.target, wanted.target)) continue;
            seen[i] += 1;
            try std.testing.expectEqualStrings(wanted.language, span.language);
            try std.testing.expectEqualStrings(wanted.direction, span.direction);
        }
    };
    for (seen) |count| try std.testing.expectEqual(@as(usize, 1), count);
    try std.testing.expect(language.body_language_direction == null);

    var translations: Renderer = .{ .a = a, .context = .{} };
    translations.body_language_direction = .{ .language = "de", .direction = "ltr" };
    const translated = try translations.renderBody(
        "<table class=translations lang=fr dir=rtl>\n<tr><td>[[Translation|translation]]</td></tr>\n</table>[[TableSibling|sibling]]",
    );
    var translated_seen: [2]usize = @splat(0);
    for (translated) |block| for (block.spans) |span| {
        if (std.mem.eql(u8, span.target, "Translation")) {
            translated_seen[0] += 1;
            try std.testing.expectEqualStrings("fr", span.language);
            try std.testing.expectEqualStrings("rtl", span.direction);
        } else if (std.mem.eql(u8, span.target, "TableSibling")) {
            translated_seen[1] += 1;
            try std.testing.expectEqualStrings("de", span.language);
            try std.testing.expectEqualStrings("ltr", span.direction);
        }
    };
    for (translated_seen) |count| try std.testing.expectEqual(@as(usize, 1), count);
    try std.testing.expectEqualStrings("de", translations.body_language_direction.?.language);
    try std.testing.expectEqualStrings("ltr", translations.body_language_direction.?.direction);
}

test "HTML table caption admission preserves earlier effects and rejects late side effects" {
    const Check = struct {
        fn effects(a: A, references: anytype, media: anytype, notes: []const []const u8, files: []const []const u8) !void {
            try std.testing.expectEqual(notes.len, references.len);
            for (references, notes) |reference_value, note| {
                var text: std.ArrayList(u8) = .empty;
                for (reference_value.spans) |span| {
                    try text.appendSlice(a, span.text);
                    if (@hasField(@TypeOf(span), "trail")) try text.appendSlice(a, span.trail);
                }
                try std.testing.expectEqualStrings(note, text.items);
            }
            try std.testing.expectEqual(files.len, media.len);
            for (media, files) |item, file| try std.testing.expectEqualStrings(file, item.file);
        }
        fn ordered(a: A, blocks: anytype, words: []const []const u8) !void {
            var visible: std.ArrayList(u8) = .empty;
            for (blocks) |block_value| {
                for (block_value.spans) |span| {
                    try visible.appendSlice(a, span.text);
                    if (@hasField(@TypeOf(span), "trail")) try visible.appendSlice(a, span.trail);
                }
                if (block_value.table) |table| {
                    for (table.caption) |span| {
                        try visible.appendSlice(a, span.text);
                        if (@hasField(@TypeOf(span), "trail")) try visible.appendSlice(a, span.trail);
                    }
                    for (table.rows) |row| for (row.cells) |cell_value| for (cell_value.spans) |span| {
                        try visible.appendSlice(a, span.text);
                        if (@hasField(@TypeOf(span), "trail")) try visible.appendSlice(a, span.trail);
                    };
                }
            }
            var after: usize = 0;
            for (words) |word| {
                const at = std.mem.indexOf(u8, visible.items, word) orelse return error.TestUnexpectedResult;
                try std.testing.expect(at >= after);
                after = at + word.len;
                try std.testing.expect(std.mem.indexOfPos(u8, visible.items, after, word) == null);
            }
        }
        fn hybridGrid(blocks: anytype) !void {
            var tables: usize = 0;
            for (blocks) |block_value| if (block_value.table) |table| {
                tables += 1;
                try std.testing.expectEqual(@as(usize, 3), table.rows.len);
                try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
                try std.testing.expectEqual(@as(usize, 2), table.rows[1].cells.len);
                try std.testing.expectEqual(@as(usize, 1), table.rows[2].cells.len);
                for (table.rows, 0..) |row, ri| for (row.cells, 0..) |cell_value, ci| {
                    try std.testing.expectEqual(ri == 0, cell_value.header);
                    try std.testing.expectEqual(@as(u16, if (ri == 0) 2 else 1), cell_value.colspan);
                    try std.testing.expectEqual(@as(u16, if (ri == 1 and ci == 0) 2 else 1), cell_value.rowspan);
                };
                var header_actions: usize = 0;
                for (table.rows[0].cells[0].spans) |span| if (std.mem.eql(u8, span.target, "cat")) {
                    header_actions += 1;
                    try std.testing.expectEqualStrings("fr", span.language);
                    try std.testing.expectEqualStrings("rtl", span.direction);
                };
                var cell_actions: usize = 0;
                for (table.rows[1].cells[0].spans) |span| if (std.mem.eql(u8, span.target, "dog")) {
                    cell_actions += 1;
                    try std.testing.expectEqualStrings("", span.language);
                    try std.testing.expectEqualStrings("", span.direction);
                };
                try std.testing.expectEqual(@as(usize, 1), header_actions);
                try std.testing.expectEqual(@as(usize, 1), cell_actions);
            };
            try std.testing.expectEqual(@as(usize, 1), tables);
        }
        fn roundtrip(a: A, renderer: *Renderer, blocks: []const Block, notes: []const []const u8, files: []const []const u8, words: []const []const u8, mixed_case_grid: bool) !void {
            try ordered(a, blocks, words);
            if (mixed_case_grid) try hybridGrid(blocks);
            const references = try renderer.finishReferences();
            try effects(a, references, renderer.media.items, notes, files);
            const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
            const sections = [_]Section{.{ .blocks = blocks }};
            const blob = @import("blob_encoder");
            const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, renderer.media.items);
            const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "table caption admission", .language, .{ .code = "en", .heading = "English" });
            try effects(a, decoded.entry.references, decoded.entry.media, notes, files);
            try ordered(a, decoded.entry.sections[0].blocks, words);
            if (mixed_case_grid) try hybridGrid(decoded.entry.sections[0].blocks);
        }
    };
    const earlier = "kept<ref name=kept>kept note</ref>[[File:Kept.jpg|thumb|kept media]]\n";
    const later = "\nkept again<ref name=kept/>\n<references/>";
    const cell = "<tr><td>cell<ref name=kept>ignored replacement</ref><ref>discarded note</ref>[[File:Discarded.jpg|thumb|discarded media]]</td></tr>";
    const invalid = [_][]const u8{
        "<table>" ++ cell ++ "<caption>unclosed</table>",
        "<table><caption>unclosed" ++ cell ++ "</table>",
    };
    for (invalid) |table_source| {
        errdefer std.debug.print("unclosed caption source: {s}\n", .{table_source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(try std.fmt.allocPrint(a, "{s}{s}{s}", .{ earlier, table_source, later }));
        var literal_tables: usize = 0;
        for (blocks) |block_value| {
            try std.testing.expect(block_value.table == null);
            if (block_value.kind != .preformatted) continue;
            literal_tables += 1;
            try std.testing.expectEqualStrings(table_source, try flattened(a, block_value.spans));
            for (block_value.spans) |span| {
                try std.testing.expect(span.flags.code);
                try std.testing.expectEqualStrings("", span.target);
            }
        }
        try std.testing.expectEqual(@as(usize, 1), literal_tables);
        try Check.roundtrip(a, &renderer, blocks, &.{"kept note"}, &.{"Kept.jpg"}, &.{}, false);
    }

    const valid_caption = "<caption>caption<ref>caption note</ref>[[File:Caption.jpg|thumb|caption media]]</caption>";
    const valid_cell = "<tr><td>cell<ref>cell note</ref>[[File:Cell.jpg|thumb|cell media]]</td></tr>";
    const valid = [_]struct { source: []const u8, notes: []const []const u8, files: []const []const u8 }{
        .{ .source = "<table>" ++ valid_caption ++ valid_cell ++ "</table>", .notes = &.{ "kept note", "caption note", "cell note" }, .files = &.{ "Kept.jpg", "Caption.jpg", "Cell.jpg" } },
        .{ .source = "<table>" ++ valid_cell ++ valid_caption ++ "</table>", .notes = &.{ "kept note", "cell note", "caption note" }, .files = &.{ "Kept.jpg", "Cell.jpg", "Caption.jpg" } },
        .{ .source = "<table><tr><td><nowiki><caption></nowiki><!-- <caption> --><source><caption></source>cell<ref>cell note</ref>[[File:Cell.jpg|thumb|cell media]]</td></tr></table>", .notes = &.{ "kept note", "cell note" }, .files = &.{ "Kept.jpg", "Cell.jpg" } },
    };
    for (valid) |case| {
        errdefer std.debug.print("complete/protected caption source: {s}\n", .{case.source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(try std.fmt.allocPrint(a, "{s}{s}{s}", .{ earlier, case.source, later }));
        var tables: usize = 0;
        for (blocks) |block_value| {
            try std.testing.expect(block_value.kind != .preformatted);
            if (block_value.table) |table| {
                tables += 1;
                try std.testing.expectEqual(@as(usize, 1), table.rows.len);
                try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            }
        }
        try std.testing.expectEqual(@as(usize, 1), tables);
        try Check.roundtrip(a, &renderer, blocks, case.notes, case.files, &.{}, false);
    }

    // A failed hybrid HTML row must remain buffered until either a later row
    // commits the wiki table, or the existing rowless recovery renders it once.
    const fostered = "fostered-prefix<ref>outside note</ref>[[File:Outside.jpg|thumb|asset caption<ref>media note</ref>]]\n";
    const bad_row = "<tr><td>bad-cell</td></tr><caption>unclosed-caption\n";
    const hybrid = [_]struct { source: []const u8, tables: usize, words: []const []const u8 }{
        .{ .source = "{|\n" ++ fostered ++ bad_row ++ "|}", .tables = 0, .words = &.{ "fostered-prefix", "asset caption", "bad-cell", "unclosed-caption" } },
        .{ .source = "{|\n" ++ fostered ++ "<track>prefix</track>" ++ bad_row ++ "|}", .tables = 0, .words = &.{ "fostered-prefix", "asset caption", "bad-cell", "unclosed-caption" } },
        .{ .source = "{|\n" ++ fostered ++ bad_row ++ "<tr><td>committed-cell</td></tr>\n|}", .tables = 1, .words = &.{ "fostered-prefix", "asset caption", "bad-cell", "unclosed-caption", "committed-cell" } },
        .{ .source = "{|\n" ++ fostered ++ "|}", .tables = 0, .words = &.{ "fostered-prefix", "asset caption" } },
    };
    for (hybrid) |case| {
        errdefer std.debug.print("hybrid row caption source: {s}\n", .{case.source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(try std.fmt.allocPrint(a, "{s}{s}{s}", .{ earlier, case.source, later }));
        var tables: usize = 0;
        for (blocks) |block_value| if (block_value.table) |table| {
            tables += 1;
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            try std.testing.expectEqualStrings("committed-cell", try flattened(a, table.rows[0].cells[0].spans));
        };
        try std.testing.expectEqual(case.tables, tables);
        try Check.roundtrip(a, &renderer, blocks, &.{ "kept note", "outside note", "media note" }, &.{ "Kept.jpg", "Outside.jpg" }, case.words, false);
    }

    const case_rows = [_][]const u8{
        "<TR lang=fr dir=rtl><TH colspan=2>[[cat|header]]<ref>header note</ref>[[File:Row.jpg|thumb|row asset]]</TH></TR>\n<TR><TD rowspan=2>[[dog|cell]]<ref>cell note</ref></TD><TD>tail</TD></TR>\n<TR><TD>last</TD></TR>\n",
        "<tR lang=fr dir=rtl><tH colspan=2>[[cat|header]]<ref>header note</ref>[[File:Row.jpg|thumb|row asset]]</tH></tR>\n<tR><tD rowspan=2>[[dog|cell]]<ref>cell note</ref></tD><Td>tail</Td></tR>\n<Tr><td>last</td></Tr>\n",
    };
    for (case_rows) |rows_source| {
        errdefer std.debug.print("case-insensitive hybrid source: {s}\n", .{rows_source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const source = try std.fmt.allocPrint(a, "{s}{{|\n{s}{s}|}}{s}", .{ earlier, fostered, rows_source, later });
        const blocks = try renderer.renderBody(source);
        try Check.roundtrip(a, &renderer, blocks, &.{ "kept note", "outside note", "media note", "header note", "cell note" }, &.{ "Kept.jpg", "Outside.jpg", "Row.jpg" }, &.{ "fostered-prefix", "asset caption", "header", "row asset", "cell", "tail", "last" }, true);
    }
}

test "internal label keeps nested external source and formatting through DPR2" {
    const Check = struct {
        fn values(a: A, spans: anytype, expected: []const u8, target: []const u8, linked_end: usize, external: bool, bold_text: ?[]const u8) !void {
            const bold_start = if (bold_text) |value| std.mem.indexOf(u8, expected, value) orelse return error.TestUnexpectedResult else expected.len;
            const bold_end = bold_start + (if (bold_text) |value| value.len else 0);
            var text: std.ArrayList(u8) = .empty;
            var offset: usize = 0;
            for (spans) |span| {
                const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                try std.testing.expect(!code);
                const parts = [_][]const u8{ span.text, if (@hasField(@TypeOf(span), "trail")) span.trail else "" };
                for (parts) |part| {
                    try text.appendSlice(a, part);
                    for (part) |_| {
                        try std.testing.expect(offset < expected.len);
                        try std.testing.expectEqualStrings(if (offset < linked_end) target else "", span.target);
                        if (offset < linked_end) {
                            if (external) try std.testing.expect(span.kind == .external_link) else try std.testing.expect(span.kind == .link);
                        } else try std.testing.expect(span.kind == .text);
                        try std.testing.expectEqual(offset >= bold_start and offset < bold_end, bold);
                        offset += 1;
                    }
                }
            }
            try std.testing.expectEqualStrings(expected, text.items);
            try std.testing.expectEqual(expected.len, offset);
        }
        fn refused(a: A, spans: anytype, prefix: []const u8, has_inner: bool, misnested: bool) !void {
            const expected = try std.fmt.allocPrint(a, "{s}label tail{s}{s}]] after", .{ prefix, if (misnested) " end" else "", if (has_inner) " one" else "" });
            const label_start = prefix.len;
            const label_end = label_start + "label".len;
            const bold_end = label_start + "label tail".len;
            const italic_end = if (misnested) label_start + "label tail end".len else label_start;
            const inner_start = label_start + (if (misnested) "label tail end ".len else "label tail ".len);
            const inner_end = inner_start + "one".len;
            var visible: std.ArrayList(u8) = .empty;
            var offset: usize = 0;
            for (spans) |span| {
                const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                try std.testing.expect(!code);
                const parts = [_][]const u8{ span.text, if (@hasField(@TypeOf(span), "trail")) span.trail else "" };
                for (parts) |part| {
                    try visible.appendSlice(a, part);
                    for (part) |_| {
                        try std.testing.expect(offset < expected.len);
                        const external = offset >= label_start and offset < label_end;
                        const inner = has_inner and offset >= inner_start and offset < inner_end;
                        try std.testing.expectEqualStrings(if (external) "https://example.test" else if (inner) "Inner" else "", span.target);
                        if (external) try std.testing.expect(span.kind == .external_link) else if (inner) try std.testing.expect(span.kind == .link) else try std.testing.expect(span.kind == .text);
                        try std.testing.expectEqual(offset >= label_start and offset < bold_end, bold);
                        try std.testing.expectEqual(offset >= label_start and offset < italic_end, italic);
                        offset += 1;
                    }
                }
            }
            try std.testing.expectEqualStrings(expected, visible.items);
            try std.testing.expectEqual(expected.len, offset);
        }
        fn wire(a: A, spans: []const Span, expected: []const u8, target: []const u8, linked_end: usize, external: bool, bold_text: ?[]const u8) !void {
            try values(a, spans, expected, target, linked_end, external, bold_text);
            const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
            const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
            const sections = [_]Section{.{ .blocks = &blocks }};
            const blob = @import("blob_encoder");
            const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, &.{}, &.{});
            const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "nested external internal label", .language, .{ .code = "en", .heading = "English" });
            try values(a, decoded.entry.sections[0].blocks[0].spans, expected, target, linked_end, external, bold_text);
        }
    };
    // Separate the external close from the internal pair; adjacent triple
    // brackets are not this fixture's parsing authority.
    const cases = [_]struct { source: []const u8, text: []const u8, bold: ?[]const u8 = null }{
        .{ .source = "[[Target|[https://example.test <b>שָׁלוֹם</b>] tail]] after", .text = "[https://example.test שָׁלוֹם] tail after", .bold = "שָׁלוֹם" },
        .{ .source = "[[Target|[https://example.test '''é'''] tail]] after", .text = "[https://example.test é] tail after", .bold = "é" },
        .{ .source = "[[Target|[https://example.test <b>&amp;copy;</b>] tail]] after", .text = "[https://example.test &copy;] tail after", .bold = "&copy;" },
        .{ .source = "[[Target|[https://example.test label]]]s after", .text = "[https://example.test label]s after" },
        .{ .source = "[[Target|[https://example.test <b>é</b>]]]s after", .text = "[https://example.test é]s after", .bold = "é" },
        .{ .source = "[[Target|[https://example.test] tail]] after", .text = "[https://example.test] tail after" },
        .{ .source = "[[Target|[https://example.test ] tail]] after", .text = "[https://example.test ] tail after" },
        .{ .source = "[[Target|[https://example.test?q=&lt;x&gt;] tail]] after", .text = "[https://example.test?q=<x>] tail after" },
        .{ .source = "[[Target|[https://example.test?q=&lt;x&gt; <b>é</b>] tail]] after", .text = "[https://example.test?q=<x> é] tail after", .bold = "é" },
        .{ .source = "[[Target|[https://example.test https://example.test] tail]] after", .text = "[https://example.test https://example.test] tail after" },
        .{ .source = "[[Target|[https://example.test <nowiki><b>literal</b> &amp;copy;</nowiki>] tail]] after", .text = "[https://example.test <b>literal</b> &copy;] tail after" },
        .{ .source = "[[Target|https://example.test tail]] after", .text = "https://example.test tail after" },

        .{ .source = "[[Target|[https://example.test <b>label] tail</b>]] after", .text = "[https://example.test label] tail after", .bold = "label] tail" },
        .{ .source = "[[Target|[https://example.test '''é] tail''']] after", .text = "[https://example.test é] tail after", .bold = "é] tail" },
    };
    for (cases) |case| {
        errdefer std.debug.print("nested external label source: {s}\n", .{case.source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        const linked_end = std.mem.indexOf(u8, case.text, " after") orelse return error.TestUnexpectedResult;
        try Check.wire(a, blocks[0].spans, case.text, "Target", linked_end, false, case.bold);
        try std.testing.expect(!renderer.fallbacks.any());
    }

    // One phase-visible opening bracket absorbs one adjacent closer before
    // the ordinary letter trail. Protected bodies and ordinary labels do not.
    const adjacent = [_]struct { source: []const u8, label: []const u8, trail: []const u8, rest: []const u8 }{
        .{ .source = "[[Target|[https://example.test label]]]s after", .label = "[https://example.test label]", .trail = "s", .rest = " after" },
        .{ .source = "[[Target|<span title=\"[\">label</span>]]]s after", .label = "<span title=\"[\">label</span>", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<span bogus=\"[\">label</span>]]]s after", .label = "<span bogus=\"[\">label</span>", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<pre/ title=\"[\">label</pre>]]]s after", .label = "<pre/ title=\"[\">label</pre>", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|x</pre title=\"[\">]]]s after", .label = "x</pre title=\"[\">", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<meta itemprop content=\"[\">label]]]s after", .label = "<meta itemprop content=\"[\">label", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<meta itemprop\x0bcontent=\"[\">label]]]s after", .label = "<meta itemprop\x0bcontent=\"[\">label]", .trail = "s", .rest = " after" },
        .{ .source = "[[Target|<link itemprop href=\"[\">label]]]s after", .label = "<link itemprop href=\"[\">label", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<meta title=\"[\">label]]]s after", .label = "<meta title=\"[\">label]", .trail = "s", .rest = " after" },
        .{ .source = "[[Target|<meta data-note=\"itemprop content\" title=\"[\">label]]]s after", .label = "<meta data-note=\"itemprop content\" title=\"[\">label]", .trail = "s", .rest = " after" },
        .{ .source = "[[Target|<bogus title=\"[\">label</bogus>]]]s after", .label = "<bogus title=\"[\">label</bogus>]", .trail = "s", .rest = " after" },
        .{ .source = "[[Target|label]]]s after", .label = "label", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<nowiki>[literal</nowiki>]]]s after", .label = "<nowiki>[literal</nowiki>", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<source>[literal</source>]]]s after", .label = "<source>[literal</source>", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|<!-- [ -->label]]]s after", .label = "<!-- [ -->label", .trail = "", .rest = "]s after" },
        .{ .source = "[[Target|&#91;literal]]]s after", .label = "&#91;literal", .trail = "", .rest = "]s after" },
    };
    for (adjacent) |case| {
        var iterator: ir.InlineIterator = .{ .input = case.source, .renderer_boundaries = true };
        const token = iterator.next() orelse return error.TestUnexpectedResult;
        try std.testing.expect(token.kind == .link);
        try std.testing.expectEqualStrings("Target", token.target);
        try std.testing.expectEqualStrings(case.label, token.text);
        try std.testing.expectEqualStrings(case.trail, token.trail);
        try std.testing.expectEqualStrings(case.rest, case.source[iterator.cursor..]);
    }
    const negative = [_]struct { source: []const u8, text: []const u8, linked_end: usize }{
        .{ .source = "[[Target|<span title=\"[\">label</span>]]]s after", .text = "label]s after", .linked_end = "label".len },
        .{ .source = "[[Target|<span bogus=\"[\">label</span>]]]s after", .text = "label]s after", .linked_end = "label".len },
        .{ .source = "[[Target|<meta itemprop=x content=y title=\"[\">label]]]s after", .text = "label]s after", .linked_end = "label".len },
        .{ .source = "[[Target|<meta title=\"[\">label]]]s after", .text = "<meta title=\"[\">label]s after", .linked_end = "<meta title=\"[\">label]s".len },
        .{ .source = "[[Target|<bogus title=\"[\">label</bogus>]]]s after", .text = "<bogus title=\"[\">label</bogus>]s after", .linked_end = "<bogus title=\"[\">label</bogus>]s".len },
        .{ .source = "[[Target|label]]]s after", .text = "label]s after", .linked_end = "label".len },
        .{ .source = "[[Target|<nowiki>[literal</nowiki>]]]s after", .text = "[literal]s after", .linked_end = "[literal".len },
        .{ .source = "[[Target|<!-- [ -->label]]]s after", .text = "label]s after", .linked_end = "label".len },
        .{ .source = "[[Target|&#91;literal]]]s after", .text = "[literal]s after", .linked_end = "[literal".len },
    };
    for (negative) |case| {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        try Check.wire(a, blocks[0].spans, case.text, "Target", case.linked_end, false, null);
    }
    // A block-spanning label uses the parsed label extent, including the
    // absorbed closer, rather than the earlier raw balanced-pair endpoint.
    {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody("[[Target|[https://example.test\nlabel]]]s after");
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        const expected = "[https://example.test label]s after";
        try Check.wire(a, blocks[0].spans, expected, "Target", expected.len - " after".len, false, null);
    }
    // The direct inherited-link API must select the same normalization phase.
    {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans("[https://example.test <b>label] tail</b>", .{ .kind = .link, .target = "Target" });
        const expected = "[https://example.test label] tail";
        try Check.wire(a, spans, expected, "Target", expected.len, false, "label] tail");
        try std.testing.expect(!renderer.fallbacks.any());
    }
    // A nested internal link refuses the outer. Its external link remains
    // active, so formatting crosses the real external close in ordinary mode.
    const refused_cases = [_]struct { source: []const u8, prefix: []const u8, inner: bool = false, misnested: bool = false, check_literal: bool = true }{
        .{ .source = "[[Outer|[https://example.test <b>label] tail</b> [[Inner|one]]]] after", .prefix = "[[Outer|", .inner = true },
        .{ .source = "[[Outer|[https://example.test '''label] tail''' [[Inner|one]]]] after", .prefix = "[[Outer|", .inner = true },
        .{ .source = "[[Outer|[https://example.test <b><i>label] tail</b> end</i> [[Inner|one]]]] after", .prefix = "[[Outer|", .inner = true, .misnested = true },
        .{ .source = "[[Bad\nTitle|[https://example.test <b>label] tail</b>]] after", .prefix = "[[Bad Title|" },
        .{ .source = "[[Bad\rTitle|[https://example.test <b>label] tail</b>]] after", .prefix = "[[Bad Title|" },
        .{ .source = "[[__NOEDITSECTION__|[https://example.test <b>label] tail</b>]] after", .prefix = "[[|", .check_literal = false },
        .{ .source = "[[<nowiki>Bad</nowiki>|[https://example.test <b>label] tail</b>]] after", .prefix = "[[Bad|" },
    };
    for (refused_cases) |case| {
        errdefer std.debug.print("refused outer external phase source: {s}\n", .{case.source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        try Check.refused(a, blocks[0].spans, case.prefix, case.inner, case.misnested);
        if (case.check_literal) try std.testing.expect(renderer.fallbacks.literal_markup);
        try std.testing.expect(!renderer.fallbacks.unclosed_formatting);
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, &.{}, &.{});
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "refused outer external phase", .language, .{ .code = "en", .heading = "English" });
        try Check.refused(a, decoded.entry.sections[0].blocks[0].spans, case.prefix, case.inner, case.misnested);
    }
    // Many raw openers share a single close. Internal-label mode must walk
    // their text without repeatedly probing the remaining external token.
    {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var source: std.ArrayList(u8) = .empty;
        var expected: std.ArrayList(u8) = .empty;
        try source.appendSlice(a, "[[Target|");
        for (0..1024) |_| {
            try source.appendSlice(a, "[https://example.test ");
            try expected.appendSlice(a, "[https://example.test ");
        }
        try source.appendSlice(a, "<b>label] tail</b>]] after");
        try expected.appendSlice(a, "label] tail after");
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source.items);
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        try Check.wire(a, blocks[0].spans, expected.items, "Target", expected.items.len - " after".len, false, "label] tail");
        try std.testing.expect(!renderer.fallbacks.any());
    }
    // Ordinary external labels and bare internal URLs keep their existing path.
    {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody("[https://example.test <b>é</b>] after");
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        try Check.wire(a, blocks[0].spans, "é after", "https://example.test", "é".len, true, "é");
    }
    // Existing external-parent API behavior is pinned, not newly asserted as
    // upstream nested-anchor semantics.
    const external_parent = [_]struct { source: []const u8, text: []const u8 }{
        .{ .source = "[https://inner.test <b>label</b>]", .text = "<b>label</b>" },
        .{ .source = "[https://inner.test]", .text = "https://inner.test" },
        .{ .source = "[https://inner.test?q=&lt;x&gt; label]", .text = "<x> label" },
        .{ .source = "https://inner.test", .text = "https://inner.test" },
    };
    for (external_parent) |case| {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(case.source, .{ .kind = .external_link, .target = "https://outer.test" });
        try Check.wire(a, spans, case.text, "https://outer.test", case.text.len, true, null);
    }
}

test "hybrid HTML captions retain visible content and effects through DPR2" {
    const Case = struct {
        source: []const u8,
        caption: []const u8,
        cell: []const u8 = "cell[2]",
        notes: []const []const u8,
        files: []const []const u8 = &.{ "Kept.jpg", "Cap.jpg" },
        exact_grid: bool = true,
        styled_caption: bool = true,
    };
    const Check = struct {
        fn text(a: A, spans: anytype) ![]const u8 {
            var out: std.ArrayList(u8) = .empty;
            for (spans) |span| {
                if (span.kind == .line_break) try out.append(a, '\n') else try out.appendSlice(a, span.text);
                if (@hasField(@TypeOf(span), "trail")) try out.appendSlice(a, span.trail);
            }
            return out.items;
        }
        fn blocks(a: A, values: anytype, case: Case) !void {
            var tables: usize = 0;
            var outside: usize = 0;
            for (values) |block_value| {
                if (block_value.table) |table| {
                    tables += 1;
                    try std.testing.expectEqualStrings(case.caption, try text(a, table.caption));
                    // The raw-row fixture asserts content, not upstream's
                    // ambiguous implicit-empty-row geometry. |- is explicit.
                    if (case.exact_grid) {
                        try std.testing.expectEqual(@as(usize, 1), table.rows.len);
                        try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
                        const cell = table.rows[0].cells[0];
                        try std.testing.expect(cell.header);
                        try std.testing.expectEqual(@as(u16, 2), cell.colspan);
                        try std.testing.expectEqual(@as(u16, 1), cell.rowspan);
                    }
                    var cell_texts: usize = 0;
                    for (table.rows) |row| for (row.cells) |cell| {
                        const visible = try text(a, cell.spans);
                        if (std.mem.eql(u8, visible, case.cell)) {
                            cell_texts += 1;
                            var actions: usize = 0;
                            for (cell.spans) |span| if (std.mem.eql(u8, span.target, "Cell")) {
                                actions += 1;
                                try std.testing.expectEqualStrings("cell", span.text);
                                try std.testing.expect(span.kind == .link);
                                try std.testing.expectEqualStrings("", span.language);
                                try std.testing.expectEqualStrings("", span.direction);
                            };
                            try std.testing.expectEqual(@as(usize, 1), actions);
                        }
                    };
                    try std.testing.expectEqual(@as(usize, 1), cell_texts);
                    var caption_actions: usize = 0;
                    var asset_actions: usize = 0;
                    for (table.caption) |span| {
                        const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                        const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                        try std.testing.expect(!code);
                        if (std.mem.eql(u8, span.target, "Caption")) {
                            caption_actions += 1;
                            try std.testing.expectEqualStrings("caption", span.text);
                            try std.testing.expect(span.kind == .link);
                            try std.testing.expect(bold);
                            try std.testing.expectEqualStrings("fr", span.language);
                            try std.testing.expectEqualStrings("rtl", span.direction);
                        }
                        if (std.mem.eql(u8, span.target, "File:Cap.jpg")) {
                            asset_actions += 1;
                            try std.testing.expectEqualStrings("asset", span.text);
                            try std.testing.expect(span.kind == .link);
                            try std.testing.expect(!bold);
                            try std.testing.expectEqualStrings("fr", span.language);
                            try std.testing.expectEqualStrings("rtl", span.direction);
                            try std.testing.expect(std.mem.indexOf(u8, span.classes, "wikidict-media-file-4361702e6a7067") != null);
                        }
                    }
                    try std.testing.expectEqual(@as(usize, if (case.styled_caption) 1 else 0), caption_actions);
                    try std.testing.expectEqual(@as(usize, if (case.styled_caption) 1 else 0), asset_actions);
                }
                for (block_value.spans) |span| if (std.mem.indexOf(u8, span.text, "outside") != null) {
                    outside += 1;
                    try std.testing.expectEqualStrings("", span.target);
                    try std.testing.expectEqualStrings("", span.language);
                    try std.testing.expectEqualStrings("", span.direction);
                };
            }
            try std.testing.expectEqual(@as(usize, 1), tables);
            try std.testing.expectEqual(@as(usize, 1), outside);
        }
        fn effects(a: A, references: anytype, media: anytype, case: Case) !void {
            try std.testing.expectEqual(case.notes.len, references.len);
            for (references, case.notes) |reference_value, expected| try std.testing.expectEqualStrings(expected, try text(a, reference_value.spans));
            try std.testing.expectEqual(case.files.len, media.len);
            for (media, case.files) |item, file| try std.testing.expectEqualStrings(file, item.file);
        }
    };
    const earlier = "kept<ref name=kept>kept note</ref>[[File:Kept.jpg|thumb|kept asset]]\n";
    const later = "\noutside<ref name=kept/>\n<references/>";
    const row = "<tr><th colspan=2>[[Cell|cell]]<ref>cell note</ref></th></tr>";
    const caption = "<caption lang=fr dir=rtl><b>[[Caption|caption]]</b><ref>caption note</ref>[[File:Cap.jpg|thumb|asset]]</caption>";
    const cases = [_]Case{
        .{ .source = "{|\n" ++ row ++ caption ++ "\n|}", .caption = "caption[3]asset", .notes = &.{ "kept note", "cell note", "caption note" }, .exact_grid = false },
        .{ .source = "{|\n|-\n" ++ row ++ caption ++ "\n|}", .caption = "caption[3]asset", .notes = &.{ "kept note", "cell note", "caption note" } },
        .{
            .source = "{|\n|+ [[Wiki|wiki]]<ref>wiki note</ref>\n|-\n" ++ row ++ caption ++ "\n|+ [[After|after caption]]<ref>after note</ref>\n|}",
            .caption = "wiki[2]\ncaption[4]asset\nafter caption[5]",
            .cell = "cell[3]",
            .notes = &.{ "kept note", "wiki note", "cell note", "caption note", "after note" },
        },
        .{
            .source = "{|\n|+ [[Wiki|wiki]]<ref>wiki note</ref>\n|-\n" ++ row ++ "<caption></caption>\n|}",
            .caption = "wiki[2]",
            .cell = "cell[3]",
            .notes = &.{ "kept note", "wiki note", "cell note" },
            .files = &.{"Kept.jpg"},
            .styled_caption = false,
        },
        .{
            .source = "{|\n|-\n<tr><th colspan=2>[[Cell|cell]]<ref>cell note</ref><nowiki><caption>fake</caption></nowiki></th></tr>" ++ caption ++ "\n|}",
            .caption = "caption[3]asset",
            .cell = "cell[2]<caption>fake</caption>",
            .notes = &.{ "kept note", "cell note", "caption note" },
        },
    };
    for (cases) |case| {
        errdefer std.debug.print("hybrid retained caption source: {s}\n", .{case.source});
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const values = try renderer.renderBody(try std.fmt.allocPrint(a, "{s}{s}{s}", .{ earlier, case.source, later }));
        try Check.blocks(a, values, case);
        const references = try renderer.finishReferences();
        try Check.effects(a, references, renderer.media.items, case);
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = values }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "hybrid retained caption", .language, .{ .code = "en", .heading = "English" });
        try Check.blocks(a, decoded.entry.sections[0].blocks, case);
        try Check.effects(a, decoded.entry.references, decoded.entry.media, case);
    }
}

test "native Poem independent parse restores external labels and resets new holders through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn spans(alloc: A, values: anytype, expected: []const u8, target: []const u8, bold: bool, role: []const u8, direction: []const u8) !void {
            var text: std.ArrayList(u8) = .empty;
            for (values) |span| {
                try std.testing.expect(span.kind != .line_break);
                try text.appendSlice(alloc, span.text);
                try std.testing.expect(span.kind == .link);
                try std.testing.expectEqualStrings(target, span.target);
                try std.testing.expectEqualStrings(role, @tagName(span.role));
                try std.testing.expectEqualStrings(direction, span.direction);
                try std.testing.expectEqual(bold, if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold);
                try std.testing.expect(!(if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code));
                try std.testing.expect(std.mem.indexOf(u8, span.text, native_poem_prefix) == null);
                var poem = false;
                var classes = std.mem.tokenizeAny(u8, span.classes, " \t\r\n");
                while (classes.next()) |class| poem = poem or std.mem.eql(u8, class, "wikidict-poem");
                try std.testing.expect(poem);
            }
            try std.testing.expectEqualStrings(expected, text.items);
        }
        fn multiline(alloc: A, blocks: anytype, expected: []const u8, target: []const u8) !void {
            const S = @TypeOf(blocks[0].spans[0]);
            var owned: std.ArrayList(S) = .empty;
            var all: std.ArrayList(u8) = .empty;
            for (blocks, 0..) |block_value, index| {
                if (index != 0) try all.append(alloc, '\n');
                try std.testing.expect(block_value.table == null);
                for (block_value.spans) |span| {
                    if (span.kind == .line_break) {
                        try all.append(alloc, '\n');
                        continue;
                    }
                    try all.appendSlice(alloc, span.text);
                    if (std.mem.indexOf(u8, span.classes, "wikidict-poem") != null) {
                        try owned.append(alloc, span);
                    } else {
                        try std.testing.expect(span.kind == .link);
                        try std.testing.expectEqualStrings("A", span.target);
                    }
                }
            }
            try spans(alloc, owned.items, expected, target, false, "normal", "");
            var words = std.mem.tokenizeAny(u8, all.items, " \t\r\n");
            var normalized: std.ArrayList(u8) = .empty;
            while (words.next()) |word| {
                if (normalized.items.len != 0) try normalized.append(alloc, ' ');
                try normalized.appendSlice(alloc, word);
            }
            const complete = try std.fmt.allocPrint(alloc, "head {s} tail", .{expected});
            try std.testing.expectEqualStrings(complete, normalized.items);
        }
    };
    const cases = [_]struct { body: []const u8, visible: []const u8, target: []const u8 = "A", bold: bool = false }{
        .{ .body = "[https://example.test label]", .visible = "label" },
        .{ .body = "[https://example.test <b>label</b>]", .visible = "label", .bold = true },
        .{ .body = "[https://example.test <b>label] tail</b>", .visible = "label tail", .bold = true },
        .{ .body = "[[B|[https://inner.test kept] tail]]", .visible = "[https://inner.test kept] tail", .target = "B" },
        .{ .body = "https://example.test", .visible = "https://example.test" },
        .{ .body = "[https://example.test]", .visible = "https://example.test" },
        .{ .body = "[https://example.test ]", .visible = "https://example.test" },
    };
    for (cases) |case| {
        const scope = try poemPhaseTestToken(a, 0);
        const prepared = try std.fmt.allocPrint(a, "{s}<poem>{s}</poem>", .{ scope, case.body });
        const token = try poemPhaseTestLiteralToken(a, 1, prepared);
        const output = try std.fmt.allocPrint(a, "[[A|{s}]]", .{token});
        const items = [_]PoemPhaseItem{
            .{ .token = scope, .kind = .scope },
            .{ .token = token, .kind = .literal, .tag = "poem", .body = prepared },
        };
        const phase = (try parsePoemPhaseAlloc(a, output, null, try poemPhaseTestRecord(a, output, "", &items))).?;
        var renderer: Renderer = .{ .a = a, .context = .{ .poem_phase = phase } };
        const spans = try renderer.parseSpans(output, .{ .role = .example, .direction = "rtl" });
        try Check.spans(a, spans, case.visible, case.target, case.bold, "example", "rtl");
        try std.testing.expectEqual(@as(usize, 0), renderer.poem_depth);
        try std.testing.expect(!renderer.poem_base_style.poem_independent_parse);
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
        const sections = [_]Section{.{ .blocks = &blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, try renderer.finishReferences(), renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "Poem phase", .language, .{ .code = "en", .heading = "English" });
        try Check.spans(a, decoded.entry.sections[0].blocks[0].spans, case.visible, case.target, case.bold, "example", "rtl");
        const outside_holder = try renderer.parseSpans("[[C|[https://outside.test raw] tail]]", .{});
        try std.testing.expectEqualStrings("[https://outside.test raw] tail", try plainText(a, outside_holder));
        for (outside_holder) |span| {
            try std.testing.expect(span.kind == .link);
            try std.testing.expectEqualStrings("C", span.target);
            try std.testing.expect(std.mem.indexOf(u8, span.classes, "wikidict-poem") == null);
        }
        const outside = try renderer.parseSpans("[https://outside.test ordinary]", .{});
        try std.testing.expectEqualStrings("ordinary", try plainText(a, outside));
        for (outside) |span| {
            try std.testing.expect(span.kind == .external_link);
            try std.testing.expectEqualStrings("https://outside.test", span.target);
        }
    }

    // The real multiline body-link dispatcher must relinquish its outer target
    // only during the independent body, then resume the A-linked suffix.
    for ([_]struct { body: []const u8, visible: []const u8, target: []const u8 }{
        .{ .body = "[https://example.test label]", .visible = "label", .target = "A" },
        .{ .body = "[[B|[https://inner.test kept] tail]]", .visible = "[https://inner.test kept] tail", .target = "B" },
    }) |case| {
        const scope = try poemPhaseTestToken(a, 0);
        const prepared = try std.fmt.allocPrint(a, "{s}<poem>{s}</poem>", .{ scope, case.body });
        const token = try poemPhaseTestLiteralToken(a, 1, prepared);
        const output = try std.fmt.allocPrint(a, "[[A|head\n{s}\ntail]]", .{token});
        const items = [_]PoemPhaseItem{
            .{ .token = scope, .kind = .scope },
            .{ .token = token, .kind = .literal, .tag = "poem", .body = prepared },
        };
        const phase = (try parsePoemPhaseAlloc(a, output, null, try poemPhaseTestRecord(a, output, "", &items))).?;
        var renderer: Renderer = .{ .a = a, .context = .{ .poem_phase = phase } };
        const blocks = try renderer.renderBody(output);
        try Check.multiline(a, blocks, case.visible, case.target);
        try std.testing.expectEqualStrings("", renderer.body_link_target);
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, try renderer.finishReferences(), renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "multiline Poem phase", .language, .{ .code = "en", .heading = "English" });
        try Check.multiline(a, decoded.entry.sections[0].blocks, case.visible, case.target);
    }
}

test "recursive media registration keeps canonical uniqueness cap and caption effects through DPR2" {
    const Check = struct {
        fn values(a: A, blocks: anytype, references: anytype, media: anytype, visible: []const u8, notes: []const []const u8, files: []const []const u8, markers: []const usize) !void {
            try std.testing.expectEqual(notes.len, references.len);
            var text: std.ArrayList(u8) = .empty;
            var marker: usize = 0;
            for (blocks) |block_value| for (block_value.spans) |span| {
                try text.appendSlice(a, span.text);
                if (@hasField(@TypeOf(span), "trail")) try text.appendSlice(a, span.trail);
                if (span.role == .reference) {
                    try std.testing.expect(marker < markers.len);
                    try std.testing.expect(span.kind == .link);
                    try std.testing.expect(if (@hasField(@TypeOf(span), "flags")) span.flags.superscript else span.superscript);
                    try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "#reference-{d}", .{markers[marker]}), span.target);
                    try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "[{d}]", .{markers[marker]}), span.text);
                    marker += 1;
                }
            };
            try std.testing.expectEqualStrings(visible, text.items);
            try std.testing.expectEqual(markers.len, marker);
            for (references, notes) |reference_value, note| {
                var body: std.ArrayList(u8) = .empty;
                for (reference_value.spans) |span| {
                    try body.appendSlice(a, span.text);
                    if (@hasField(@TypeOf(span), "trail")) try body.appendSlice(a, span.trail);
                }
                try std.testing.expectEqualStrings(note, body.items);
            }
            try std.testing.expectEqual(files.len, media.len);
            for (media, files, 0..) |item, file, index| {
                try std.testing.expectEqualStrings(file, item.file);
                for (media[0..index]) |previous| try std.testing.expect(!std.mem.eql(u8, previous.file, item.file));
            }
        }
        fn roundtrip(a: A, r: *Renderer, blocks: []const Block, visible: []const u8, notes: []const []const u8, files: []const []const u8, markers: []const usize) !void {
            const references = try r.finishReferences();
            try std.testing.expectEqual(r.media.items.len, r.media_caption_spans.items.len);
            try values(a, blocks, references, r.media.items, visible, notes, files, markers);
            const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
            const sections = [_]Section{.{ .blocks = blocks }};
            const blob = @import("blob_encoder");
            const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, r.media.items);
            const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "recursive media", .language, .{ .code = "en", .heading = "English" });
            try values(a, decoded.entry.sections[0].blocks, decoded.entry.references, decoded.entry.media, visible, notes, files, markers);
        }
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Canonically equal names recurse before the outer record can commit.
    // The existing first registered (inner) metadata stays first; every visible
    // occurrence and unnamed reference still appears exactly once in source order.
    var same: Renderer = .{ .a = a, .context = .{} };
    const same_blocks = try same.renderBody("[[File:Same_file.jpg|thumb|outer<ref>one</ref> [[File:Same file.jpg|thumb|inner<ref>two</ref>]] tail<ref>three</ref>]] [[File:Same_file.jpg|thumb|again<ref>four</ref>]]");
    try Check.roundtrip(a, &same, same_blocks, "outer[1] inner[2] tail[3] again[4]", &.{ "one", "two", "three", "four" }, &.{"Same file.jpg"}, &.{ 1, 2, 3, 4 });
    try std.testing.expectEqualStrings("inner[2]", same.media.items[0].caption);
    try std.testing.expect(!same.fallbacks.any());
    // The recursive child consumes the final slot. The outer caption has already
    // parsed and must be reused despite refusing its new metadata registration.
    var capped: Renderer = .{ .a = a, .context = .{} };
    var files: [128][]const u8 = undefined;
    for (0..127) |index| {
        files[index] = try std.fmt.allocPrint(a, "Kept{d}.jpg", .{index});
        try capped.mediaFile(files[index], "");
    }
    files[127] = "Inner.jpg";
    const cap_blocks = try capped.renderBody("[[File:Outer.jpg|thumb|outer<ref>one</ref> [[File:Inner.jpg|thumb|inner<ref>two</ref>]] tail<ref>three</ref>]]");
    try Check.roundtrip(a, &capped, cap_blocks, "outer[1] inner[2] tail[3]", &.{ "one", "two", "three" }, &files, &.{ 1, 2, 3 });
    try std.testing.expect(capped.fallbacks.render_limit);
    for (cap_blocks) |block_value| for (block_value.spans) |span| {
        try std.testing.expect(std.mem.indexOf(u8, span.classes, "wikidict-media-file-4f757465722e6a7067") == null);
    };
    const prior_refs = capped.refs.items.len;
    try capped.mediaFile("Too late.jpg", "not parsed<ref>bad</ref>");
    try std.testing.expectEqual(prior_refs, capped.refs.items.len);
    try std.testing.expectEqual(@as(usize, 128), capped.media.items.len);
    // Metadata-only callers retain their void-registration behavior. A duplicate
    // discovered during capture keeps the inner record and cannot parse twice.
    var metadata: Renderer = .{ .a = a, .context = .{} };
    try metadata.mediaFile("Meta.jpg", "outer<ref>one</ref> [[File:Meta.jpg|thumb|inner<ref>two</ref>]] tail<ref>three</ref>");
    const metadata_refs = try metadata.finishReferences();
    try Check.values(a, &[_]Block{}, metadata_refs, metadata.media.items, "", &.{ "one", "two", "three" }, &.{"Meta.jpg"}, &.{});
    try std.testing.expectEqualStrings("inner[2]", metadata.media.items[0].caption);
    try std.testing.expectEqual(metadata.media.items.len, metadata.media_caption_spans.items.len);
    try metadata.mediaFile("Meta.jpg", "not parsed<ref>bad</ref>");
    try std.testing.expectEqual(@as(usize, 3), metadata.refs.items.len);
    var refused: Renderer = .{ .a = a, .context = .{} };
    try refused.mediaFile("", "not parsed<ref>bad</ref>");
    try refused.mediaFile("Unknown.bin", "not parsed<ref>bad</ref>");
    try std.testing.expectEqual(@as(usize, 0), refused.refs.items.len);
    try std.testing.expectEqual(@as(usize, 0), refused.media.items.len);
    try std.testing.expectEqual(@as(usize, 0), refused.media_caption_spans.items.len);
}

const FormattingScopeTest = struct {
    fn text(a: A, spans: anytype) ![]const u8 {
        var result: std.ArrayList(u8) = .empty;
        for (spans) |span| {
            if (span.kind == .line_break) try result.append(a, '\n') else try result.appendSlice(a, span.text);
            if (@hasField(@TypeOf(span), "trail")) try result.appendSlice(a, span.trail);
        }
        return result.toOwnedSlice(a);
    }
    fn shapes(a: A, blocks: anytype, kinds: []const []const u8, values: []const []const u8) !void {
        try std.testing.expectEqual(kinds.len, blocks.len);
        for (blocks, kinds, values) |block_value, kind, value| {
            try std.testing.expectEqualStrings(kind, @tagName(block_value.kind));
            try std.testing.expect(block_value.table == null);
            try std.testing.expectEqualStrings(value, try text(a, block_value.spans));
            if (block_value.kind == .definition) {
                try std.testing.expectEqualStrings("#", block_value.list_path);
                try std.testing.expectEqualStrings("1", block_value.number);
                try std.testing.expectEqual(@as(u8, 1), block_value.depth);
            }
            if (block_value.kind == .heading) try std.testing.expectEqual(@as(u8, 2), block_value.level);
        }
    }
    fn word(a: A, blocks: anytype, needle: []const u8, expected: Style) !void {
        var whole: std.ArrayList(u8) = .empty;
        for (blocks, 0..) |block_value, index| {
            if (index != 0) try whole.append(a, '\n');
            try whole.appendSlice(a, try text(a, block_value.spans));
        }
        const begin = std.mem.indexOf(u8, whole.items, needle) orelse return error.TestUnexpectedResult;
        try std.testing.expect(std.mem.indexOfPos(u8, whole.items, begin + needle.len, needle) == null);
        var offset: usize = 0;
        var checked: usize = 0;
        for (blocks, 0..) |block_value, index| {
            if (index != 0) offset += 1;
            for (block_value.spans) |span| {
                const len = span.text.len + if (@hasField(@TypeOf(span), "trail")) span.trail.len else @as(usize, 0);
                if (span.kind == .line_break) {
                    offset += 1;
                    continue;
                }
                const end = offset + len;
                if (end > begin and offset < begin + needle.len) {
                    try std.testing.expectEqualStrings(@tagName(expected.kind), @tagName(span.kind));
                    try std.testing.expectEqualStrings(expected.target, span.target);
                    try std.testing.expectEqualStrings(expected.language, span.language);
                    try std.testing.expectEqualStrings(expected.direction, span.direction);
                    try std.testing.expectEqualStrings(@tagName(expected.role), @tagName(span.role));
                    try std.testing.expectEqual(expected.small, if (@hasField(@TypeOf(span), "flags")) span.flags.small else span.small);
                    try std.testing.expectEqual(expected.bold, if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold);
                    try std.testing.expectEqual(expected.italic, if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic);
                    try std.testing.expectEqual(expected.code, if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code);
                    if (expected.classes.len == 0) {
                        try std.testing.expectEqualStrings("", span.classes);
                    } else {
                        var wanted = std.mem.tokenizeAny(u8, expected.classes, " \t\r\n");
                        while (wanted.next()) |class| {
                            var found = false;
                            var actual = std.mem.tokenizeAny(u8, span.classes, " \t\r\n");
                            while (actual.next()) |token| found = found or std.mem.eql(u8, class, token);
                            try std.testing.expect(found);
                        }
                    }
                    checked += @min(end, begin + needle.len) - @max(offset, begin);
                }
                offset = end;
            }
        }
        try std.testing.expectEqual(needle.len, checked);
    }
    fn encode(a: A, r: *Renderer, blocks: []const Block) !@import("blob_encoder").presentation_types.Stored {
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, try r.finishReferences(), r.media.items);
        return blob.presentation_codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .code = "en", .heading = "English" });
    }
};
test "matched multiline formatting keeps scoped attributes and paragraph flow through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { source: []const u8, kinds: []const []const u8, texts: []const []const u8 };
    const cases = [_]Case{
        .{ .source = "<small class=note>\n# [[cat|item]]\n</small>", .kinds = &.{"definition"}, .texts = &.{"item"} },
        .{ .source = "<small class=\"note\"/>\n# [[cat|item]]\n</small>", .kinds = &.{"definition"}, .texts = &.{"item"} },
        .{ .source = "<small>prefix\n# [[cat|item]]\ntrailer</small> tail", .kinds = &.{ "paragraph", "definition", "paragraph" }, .texts = &.{ "prefix", "item", "trailer tail" } },
        .{ .source = "<small>prefix\n# [[cat|item]]\ntrailer</small>\nnext", .kinds = &.{ "paragraph", "definition", "paragraph" }, .texts = &.{ "prefix", "item", "trailer next" } },
        .{ .source = "<small>prefix\n# [[cat|item]]\ntrailer\n\n</small>tail", .kinds = &.{ "paragraph", "definition", "paragraph", "paragraph" }, .texts = &.{ "prefix", "item", "trailer", "tail" } },
        .{ .source = "<small>prefix\n==French==</small>", .kinds = &.{"paragraph"}, .texts = &.{"prefix ==French=="} },
        .{ .source = "<small class=note>\n==French==\nbody\n</small> Outside", .kinds = &.{ "heading", "paragraph" }, .texts = &.{ "French", "body Outside" } },
        .{ .source = "<small class=note><nowiki>prefix\n# [[cat]]\n==French==</nowiki></small> tail", .kinds = &.{"paragraph"}, .texts = &.{"prefix # [[cat]] ==French== tail"} },
        .{ .source = "<small class=note>\n code\n</small> tail", .kinds = &.{ "preformatted", "paragraph" }, .texts = &.{ "code", "tail" } },
        .{ .source = "<small>one\n</small>tail", .kinds = &.{"paragraph"}, .texts = &.{"one tail"} },
        .{ .source = "<small>one\n\n</small>tail", .kinds = &.{ "paragraph", "paragraph" }, .texts = &.{ "one", "tail" } },
        .{ .source = "<small>one\nlast </small>tail", .kinds = &.{"paragraph"}, .texts = &.{"one last tail"} },
    };
    for (cases, 0..) |case, index| {
        errdefer std.debug.print("formatting case {d}: {s}\n", .{ index, case.source });
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(case.source);
        try FormattingScopeTest.shapes(a, blocks, case.kinds, case.texts);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        try FormattingScopeTest.shapes(a, saved.entry.sections[0].blocks, case.kinds, case.texts);
        try std.testing.expect(!r.fallbacks.any());
        if (index < 2) {
            for ([_]bool{ false, true }) |decoded| {
                if (decoded) try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "item", .{ .small = true, .classes = "note", .kind = .link, .target = "cat" }) else try FormattingScopeTest.word(a, blocks, "item", .{ .small = true, .classes = "note", .kind = .link, .target = "cat" });
            }
        }
        if (index == 2 or index == 3 or index == 4) {
            try FormattingScopeTest.word(a, blocks, "trailer", .{ .small = true });
            try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "trailer", .{ .small = true });
            const suffix = if (index == 3) "next" else "tail";
            try FormattingScopeTest.word(a, blocks, suffix, .{});
            try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, suffix, .{});
        }
    }
    // Native link trails are emitted as their own visible text spans. The
    // final s must take precedence over protected label-ending whitespace.
    var trailed: Renderer = .{ .a = a, .context = .{} };
    const trail_blocks = try trailed.renderBody("<small>one\n[[A|label<nowiki> </nowiki>]]s\n</small>tail");
    const trail_saved = try FormattingScopeTest.encode(a, &trailed, trail_blocks);
    try FormattingScopeTest.shapes(a, trail_blocks, &.{"paragraph"}, &.{"one label s tail"});
    try FormattingScopeTest.shapes(a, trail_saved.entry.sections[0].blocks, &.{"paragraph"}, &.{"one label s tail"});
    try FormattingScopeTest.word(a, trail_blocks, "s", .{ .kind = .link, .target = "A", .small = true });
    try FormattingScopeTest.word(a, trail_saved.entry.sections[0].blocks, "s", .{ .kind = .link, .target = "A", .small = true });
    try FormattingScopeTest.word(a, trail_saved.entry.sections[0].blocks, "tail", .{});
    var styled: Renderer = .{ .a = a, .context = .{} };
    const blocks = try styled.renderBody("before\n<small class=\"note IPA nyms\" lang=fr dir=rtl>prefix\n# [[cat|item]]<ref>one</ref> [[File:One.jpg|thumb|photo<ref>two</ref>]]\ntrailer</small> tail\nnext\n\noutside");
    const kinds = [_][]const u8{ "paragraph", "definition", "paragraph", "paragraph" };
    const texts = [_][]const u8{ "before prefix", "item[1] photo[2]", "trailer tail next", "outside" };
    try FormattingScopeTest.shapes(a, blocks, &kinds, &texts);
    const saved = try FormattingScopeTest.encode(a, &styled, blocks);
    try FormattingScopeTest.shapes(a, saved.entry.sections[0].blocks, &kinds, &texts);
    for (blocks[0..3]) |block_value| try std.testing.expect(block_value.relation_note);
    try std.testing.expect(!blocks[3].relation_note);
    try std.testing.expectEqual(@as(usize, 2), saved.entry.references.len);
    try std.testing.expectEqualStrings("one", try FormattingScopeTest.text(a, saved.entry.references[0].spans));
    try std.testing.expectEqualStrings("two", try FormattingScopeTest.text(a, saved.entry.references[1].spans));
    try std.testing.expectEqual(@as(usize, 1), saved.entry.media.len);
    try std.testing.expectEqualStrings("One.jpg", saved.entry.media[0].file);
    try std.testing.expectEqualStrings("photo[2]", saved.entry.media[0].caption);
    for ([_][]const u8{ "before", "tail", "next", "outside" }) |word| {
        try FormattingScopeTest.word(a, blocks, word, .{});
        try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, word, .{});
    }
    const inherited: Style = .{ .small = true, .classes = "note IPA nyms", .language = "fr", .direction = "rtl", .role = .pronunciation };
    try FormattingScopeTest.word(a, blocks, "prefix", inherited);
    try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "prefix", inherited);
    var item_style = inherited;
    item_style.kind = .link;
    item_style.target = "cat";
    try FormattingScopeTest.word(a, blocks, "item", item_style);
    try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "item", item_style);
    try FormattingScopeTest.word(a, blocks, "trailer", inherited);
    try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "trailer", inherited);
    try std.testing.expect(styled.body_language_direction == null);
    try std.testing.expectEqualStrings("", styled.body_formatting_attributes.classes);
    try std.testing.expectEqual(@as(u8, 0), @as(u8, @bitCast(styled.block_formatting)));
    const plain = try styled.renderBody("plain");
    try FormattingScopeTest.word(a, plain, "plain", .{});
    var nested: Renderer = .{ .a = a, .context = .{} };
    const nested_blocks = try nested.renderBody("<small class=note lang=fr dir=rtl>prefix\n<b lang=\"\" dir=ltr>bold\n# [[cat|item]]\ntrailer</b> after\n</small> outside");
    const nested_saved = try FormattingScopeTest.encode(a, &nested, nested_blocks);
    const nested_kinds = [_][]const u8{ "paragraph", "definition", "paragraph" };
    const nested_texts = [_][]const u8{ "prefix bold", "item", "trailer after outside" };
    try FormattingScopeTest.shapes(a, nested_blocks, &nested_kinds, &nested_texts);
    try FormattingScopeTest.shapes(a, nested_saved.entry.sections[0].blocks, &nested_kinds, &nested_texts);
    for ([_][]const u8{ "bold", "trailer" }) |word| {
        try FormattingScopeTest.word(a, nested_blocks, word, .{ .small = true, .bold = true, .classes = "note", .direction = "ltr" });
        try FormattingScopeTest.word(a, nested_saved.entry.sections[0].blocks, word, .{ .small = true, .bold = true, .classes = "note", .direction = "ltr" });
    }
    try FormattingScopeTest.word(a, nested_blocks, "after", .{ .small = true, .classes = "note", .language = "fr", .direction = "rtl" });
    try FormattingScopeTest.word(a, nested_saved.entry.sections[0].blocks, "outside", .{});
    var holder: Renderer = .{ .a = a, .context = .{} };
    const holder_blocks = try holder.renderBody("<small class=note>\n# [[A|[https://example.test label] tail]]\n</small> after");
    const holder_saved = try FormattingScopeTest.encode(a, &holder, holder_blocks);
    try FormattingScopeTest.word(a, holder_blocks, "https://example.test", .{ .kind = .link, .target = "A", .small = true, .classes = "note" });
    try FormattingScopeTest.word(a, holder_saved.entry.sections[0].blocks, "https://example.test", .{ .kind = .link, .target = "A", .small = true, .classes = "note" });
    try FormattingScopeTest.word(a, holder_blocks, "after", .{});
    try std.testing.expect(!holder.fallbacks.any());
}
test "formatting attributes survive fragment boundaries and restore parent scope through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const attrs: FormattingAttributes = .{ .classes = "note IPA", .role = .pronunciation, .relation_note = true, .language = "fr", .direction = "rtl" };
    for ([_][]const u8{ "trailer</small> tail", "trailer</small>\nnext", "trailer</small>\n\nnext" }, 0..) |source, index| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const end = std.mem.indexOf(u8, source, "</small>").?;
        const initial = [_]FragmentPreContext.Initial{.{ .body_end = end, .resume_at = end + "</small>".len, .kind = .formatting, .formatting = .{ .small = true }, .attributes = attrs }};
        const blocks = try r.renderBodyWithFragmentPre(source, .{ .initial = &initial });
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        const kinds: []const []const u8 = if (index == 2) &.{ "paragraph", "paragraph" } else &.{"paragraph"};
        const values: []const []const u8 = if (index == 0) &.{"trailer tail"} else if (index == 1) &.{"trailer next"} else &.{ "trailer", "next" };
        try FormattingScopeTest.shapes(a, blocks, kinds, values);
        try FormattingScopeTest.shapes(a, saved.entry.sections[0].blocks, kinds, values);
        try FormattingScopeTest.word(a, blocks, "trailer", .{ .small = true, .classes = "note IPA", .role = .pronunciation, .language = "fr", .direction = "rtl" });
        try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "trailer", .{ .small = true, .classes = "note IPA", .role = .pronunciation, .language = "fr", .direction = "rtl" });
        const suffix = if (index == 0) "tail" else "next";
        try FormattingScopeTest.word(a, blocks, suffix, .{});
        try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, suffix, .{});
        try std.testing.expect(r.body_language_direction == null);
        try std.testing.expectEqualStrings("", r.body_formatting_attributes.classes);
        try std.testing.expectEqual(@as(u8, 0), @as(u8, @bitCast(r.block_formatting)));
    }
    const source = "before<small class=note>inside";
    const opening = std.mem.indexOf(u8, source, "<small").?;
    const tag = syntax.tagAt(source, opening).?;
    const trailing = [_]FragmentPreContext.Trailing{.{ .opening_start = opening, .body_start = tag.end, .kind = .formatting, .formatting = .{ .small = true }, .attributes = .{ .classes = "note" } }};
    var r: Renderer = .{ .a = a, .context = .{} };
    const blocks = try r.renderBodyWithFragmentPre(source, .{ .trailing = &trailing });
    const saved = try FormattingScopeTest.encode(a, &r, blocks);
    try FormattingScopeTest.shapes(a, blocks, &.{"paragraph"}, &.{"beforeinside"});
    try FormattingScopeTest.shapes(a, saved.entry.sections[0].blocks, &.{"paragraph"}, &.{"beforeinside"});
    try FormattingScopeTest.word(a, blocks, "before", .{});
    try FormattingScopeTest.word(a, saved.entry.sections[0].blocks, "inside", .{ .small = true, .classes = "note" });
    try std.testing.expect(r.body_language_direction == null);
    try std.testing.expectEqualStrings("", r.body_formatting_attributes.classes);

    // Formatting continuation may not turn a leading-space block into an
    // ordinary paragraph. Legacy parsed-pre/link joins retain their own policy.
    const leading = "before\n<b class=note>\n pre";
    const leading_open = std.mem.indexOf(u8, leading, "<b").?;
    const leading_tag = syntax.tagAt(leading, leading_open).?;
    const leading_context = [_]FragmentPreContext.Trailing{.{ .opening_start = leading_open, .body_start = leading_tag.end, .kind = .formatting, .formatting = .{ .bold = true }, .attributes = .{ .classes = "note" } }};
    var pre: Renderer = .{ .a = a, .context = .{} };
    const pre_blocks = try pre.renderBodyWithFragmentPre(leading, .{ .trailing = &leading_context });
    const pre_saved = try FormattingScopeTest.encode(a, &pre, pre_blocks);
    try FormattingScopeTest.shapes(a, pre_blocks, &.{ "paragraph", "preformatted" }, &.{ "before", "pre" });
    try FormattingScopeTest.shapes(a, pre_saved.entry.sections[0].blocks, &.{ "paragraph", "preformatted" }, &.{ "before", "pre" });
    try FormattingScopeTest.word(a, pre_blocks, "pre", .{ .bold = true, .code = true, .classes = "note" });
    try FormattingScopeTest.word(a, pre_saved.entry.sections[0].blocks, "before", .{});

    const spaced = "trailer </small>tail";
    const spaced_end = std.mem.indexOf(u8, spaced, "</small>").?;
    const spaced_context = [_]FragmentPreContext.Initial{.{ .body_end = spaced_end, .resume_at = spaced_end + "</small>".len, .kind = .formatting, .formatting = .{ .small = true }, .attributes = attrs }};
    var spaced_renderer: Renderer = .{ .a = a, .context = .{} };
    const spaced_blocks = try spaced_renderer.renderBodyWithFragmentPre(spaced, .{ .initial = &spaced_context });
    const spaced_saved = try FormattingScopeTest.encode(a, &spaced_renderer, spaced_blocks);
    try FormattingScopeTest.shapes(a, spaced_blocks, &.{"paragraph"}, &.{"trailer tail"});
    try FormattingScopeTest.shapes(a, spaced_saved.entry.sections[0].blocks, &.{"paragraph"}, &.{"trailer tail"});
}

test "HTML list items preserve authored wiki sublists through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn shape(alloc: A, blocks: anytype, paths: []const []const u8, texts: []const []const u8, rich: bool) !void {
            try std.testing.expectEqual(paths.len, blocks.len);
            for (blocks, paths, texts) |block_value, path, expected_text| {
                const expected_kind = if (path.len == 0) "paragraph" else if (std.mem.eql(u8, path, ":")) "list_detail" else "list_item";
                try std.testing.expectEqualStrings(expected_kind, @tagName(block_value.kind));
                try std.testing.expectEqualStrings(path, block_value.list_path);
                try std.testing.expectEqual(@as(u8, @intCast(path.len)), block_value.depth);
                try std.testing.expectEqualStrings("", block_value.number);
                try std.testing.expect(block_value.table == null);
                try std.testing.expectEqualStrings(expected_text, trim(try FormattingScopeTest.text(alloc, block_value.spans)));
            }
            if (rich) {
                try FormattingScopeTest.word(alloc, blocks, "parent", .{ .small = true, .language = "fr", .direction = "rtl" });
                try FormattingScopeTest.word(alloc, blocks, "child", .{ .kind = .link, .target = "cat", .language = "fr", .direction = "rtl" });
                try FormattingScopeTest.word(alloc, blocks, "after", .{});
            }
        }
        fn protected(alloc: A, blocks: anytype) !void {
            var whole: std.ArrayList(u8) = .empty;
            for (blocks) |block_value| {
                try std.testing.expect(!std.mem.startsWith(u8, block_value.list_path, "**"));
                try whole.appendSlice(alloc, try FormattingScopeTest.text(alloc, block_value.spans));
                for (block_value.spans) |span| try std.testing.expect(span.kind != .link);
            }
            const parent = std.mem.indexOf(u8, whole.items, "parent") orelse return error.TestUnexpectedResult;
            try std.testing.expect(std.mem.indexOfPos(u8, whole.items, parent + "parent".len, "parent") == null);
            const child = std.mem.indexOf(u8, whole.items, "* child") orelse return error.TestUnexpectedResult;
            try std.testing.expect(std.mem.indexOfPos(u8, whole.items, child + "* child".len, "* child") == null);
        }
        fn dump(alloc: A, label: []const u8, phase: []const u8, blocks: anytype) !void {
            std.debug.print("html-wiki-item {s} {s} blocks={d}\n", .{ label, phase, blocks.len });
            for (blocks) |block_value| {
                std.debug.print("  kind={s} path={s} text=[{s}]\n", .{
                    @tagName(block_value.kind),                             block_value.list_path,
                    try FormattingScopeTest.text(alloc, block_value.spans),
                });
            }
        }
    };
    const Case = struct {
        label: []const u8,
        source: []const u8,
        paths: []const []const u8,
        texts: []const []const u8,
        rich: bool = false,
        protected: bool = false,
    };
    const cases = [_]Case{
        .{ .label = "wiki nested", .source = "<ul><li>parent\n* child\n</li></ul>", .paths = &.{ "*", "**" }, .texts = &.{ "parent", "child" } },
        .{ .label = "wiki linked attributes", .source = "<ul lang=fr dir=rtl><li><small>parent</small>\n* [[cat|child]]\n</li></ul>\nafter", .paths = &.{ "*", "**", "" }, .texts = &.{ "parent", "child", "after" }, .rich = true },
        .{ .label = "wiki in definition detail", .source = "<dl><dd>parent\n* child\n</dd></dl>", .paths = &.{ ":", ":*" }, .texts = &.{ "parent", "child" } },
        .{ .label = "explicit HTML nested", .source = "<ul><li>parent<ul><li>child</li></ul></li></ul>", .paths = &.{ "*", "**" }, .texts = &.{ "parent", "child" } },
        .{ .label = "same-line literal", .source = "<ul><li>parent * child</li></ul>", .paths = &.{"*"}, .texts = &.{"parent * child"} },
        .{ .label = "nowiki literal", .source = "<ul><li>parent\n<nowiki>* child</nowiki>\n</li></ul>", .paths = &.{}, .texts = &.{}, .protected = true },
        .{ .label = "pre literal", .source = "<ul><li>parent\n<pre>* child</pre>\n</li></ul>", .paths = &.{}, .texts = &.{}, .protected = true },
    };
    var failed = false;
    for (cases) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(case.source);
        const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
        try Check.dump(a, case.label, "native", blocks);
        try Check.dump(a, case.label, "DPR2", stored.entry.sections[0].blocks);
        // Observe both actual representations and all neighboring controls before
        // returning the expected baseline failure for the missing wiki sublist.
        if (case.protected) {
            Check.protected(a, blocks) catch {
                failed = true;
            };
            Check.protected(a, stored.entry.sections[0].blocks) catch {
                failed = true;
            };
        } else {
            Check.shape(a, blocks, case.paths, case.texts, case.rich) catch {
                failed = true;
            };
            Check.shape(a, stored.entry.sections[0].blocks, case.paths, case.texts, case.rich) catch {
                failed = true;
            };
        }
        if (renderer.fallbacks.any()) failed = true;
    }
    try std.testing.expect(!failed);
}
test "HTML wiki sublist repair preserves indentation and formatting boundaries through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn shape(alloc: A, blocks: anytype, paths: []const []const u8, texts: []const []const u8, numbers: []const []const u8) !void {
            try std.testing.expectEqual(paths.len, blocks.len);
            for (blocks, paths, texts, 0..) |value, path, text_value, index| {
                const kind = if (path.len == 0) "paragraph" else if (path[path.len - 1] == '*') "list_item" else if (path[path.len - 1] == '#') "definition" else "list_detail";
                try std.testing.expectEqualStrings(kind, @tagName(value.kind));
                try std.testing.expectEqualStrings(path, value.list_path);
                try std.testing.expectEqualStrings(if (numbers.len == 0) "" else numbers[index], value.number);
                try std.testing.expectEqual(@as(u8, @intCast(path.len)), value.depth);
                try std.testing.expectEqualStrings(text_value, trim(try FormattingScopeTest.text(alloc, value.spans)));
            }
        }
        fn words(alloc: A, blocks: anytype, small: bool, child_small: bool, literal_star: bool, inline_scope: bool, list_scope: bool) !void {
            try FormattingScopeTest.word(alloc, blocks, "parent", .{ .small = small, .language = "fr", .direction = "rtl", .classes = "note" });
            try FormattingScopeTest.word(alloc, blocks, "child", .{ .small = child_small, .kind = .link, .target = "cat", .language = if (inline_scope) "de" else "fr", .direction = if (inline_scope) "ltr" else "rtl", .classes = if (inline_scope) "note inner" else "note" });
            if (inline_scope) {
                try FormattingScopeTest.word(alloc, blocks, "before", .{ .small = true, .language = "de", .direction = "ltr", .classes = "note inner" });
                try FormattingScopeTest.word(alloc, blocks, "brief", .{ .small = true, .language = "fr", .direction = "rtl", .classes = "note" });
            }
            if (list_scope) {
                try FormattingScopeTest.word(alloc, blocks, "before", .{ .language = "fr", .direction = "rtl", .classes = "note" });
                try FormattingScopeTest.word(alloc, blocks, "continuation", .{ .small = true, .language = "fr", .direction = "rtl", .classes = "note" });
            }
            try FormattingScopeTest.word(alloc, blocks, "tail", .{ .language = "fr", .direction = "rtl", .classes = "note" });
            try FormattingScopeTest.word(alloc, blocks, "after", .{});
            if (literal_star) try std.testing.expect(std.mem.indexOf(u8, try FormattingScopeTest.text(alloc, blocks[0].spans), "* parent") != null);
        }
        fn one(alloc: A, case: anytype) !void {
            var renderer: Renderer = .{ .a = alloc, .context = .{} };
            const blocks = try renderer.renderBody(case.source);
            const stored = try FormattingScopeTest.encode(alloc, &renderer, blocks);
            try @This().shape(alloc, blocks, case.paths, case.texts, case.numbers);
            try @This().shape(alloc, stored.entry.sections[0].blocks, case.paths, case.texts, case.numbers);
            if (case.rich) {
                try @This().words(alloc, blocks, !case.inline_scope and !case.list_scope, case.child_small, case.literal_star, case.inline_scope, case.list_scope);
                try @This().words(alloc, stored.entry.sections[0].blocks, !case.inline_scope and !case.list_scope, case.child_small, case.literal_star, case.inline_scope, case.list_scope);
            } else {
                for (blocks) |value| {
                    try std.testing.expect(value.kind != .preformatted);
                    for (value.spans) |span| try std.testing.expect(!span.flags.code);
                }
            }
            if (case.numbered_scope) {
                try FormattingScopeTest.word(alloc, blocks, "child", .{ .small = true, .kind = .link, .target = "cat" });
                try FormattingScopeTest.word(alloc, stored.entry.sections[0].blocks, "child", .{ .small = true, .kind = .link, .target = "cat" });
                try FormattingScopeTest.word(alloc, blocks, "fourth", .{ .small = true });
                try FormattingScopeTest.word(alloc, stored.entry.sections[0].blocks, "fourth", .{ .small = true });
                try FormattingScopeTest.word(alloc, blocks, "fifth", .{});
                try FormattingScopeTest.word(alloc, stored.entry.sections[0].blocks, "fifth", .{});
                try FormattingScopeTest.word(alloc, blocks, "tail", .{});
                try FormattingScopeTest.word(alloc, stored.entry.sections[0].blocks, "tail", .{});
            }
            try std.testing.expect(!renderer.fallbacks.any());
            try std.testing.expect(!renderer.html_list_item_flow);
            try std.testing.expectEqualStrings("", renderer.body_formatting_attributes.classes);
            try std.testing.expectEqual(@as(u8, 0), @as(u8, @bitCast(renderer.block_formatting)));
        }
    };
    const Case = struct {
        source: []const u8,
        paths: []const []const u8,
        texts: []const []const u8,
        numbers: []const []const u8 = &.{},
        rich: bool = false,
        child_small: bool = false,
        literal_star: bool = false,
        inline_scope: bool = false,
        list_scope: bool = false,
        numbered_scope: bool = false,
    };
    const cases = [_]Case{
        .{ .source = "<ul><li>parent\n ordinary\n* child\n more\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent  ordinary", "child", "more", "after" } },
        .{ .source = "<dl><dd>parent\n ordinary\n* child\n more\n</dd></dl>\nafter", .paths = &.{ ":", ":*", ":", "" }, .texts = &.{ "parent  ordinary", "child", "more", "after" } },
        .{ .source = "<ul lang=fr dir=rtl><li class=note><small>parent\n* [[cat|child]]\n</small>tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" }, .rich = true, .child_small = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note><small>parent</small>\n* [[cat|child]]\ntail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" }, .rich = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note><small>* parent\n* [[cat|child]]\n</small>tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "* parent", "child", "tail", "after" }, .rich = true, .child_small = true, .literal_star = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note>parent <small>brief</small> <span class=inner lang=de dir=ltr><small>before\n* [[cat|child]]\n</small></span>tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent brief before", "child", "tail", "after" }, .rich = true, .child_small = true, .inline_scope = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note>parent\n* before<small>[[cat|child]]\n continuation</small> tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "beforechild", "continuation tail", "after" }, .rich = true, .child_small = true, .list_scope = true },
        .{ .source = "<ul><li>parent\n# first\n# second\n# before <small>[[cat|child]]\n# fourth</small>\n# fifth\n tail\n</li></ul>\nafter", .paths = &.{ "*", "*#", "*#", "*#", "*#", "*#", "*:", "" }, .texts = &.{ "parent", "first", "second", "before child", "fourth", "fifth", "tail", "after" }, .numbers = &.{ "", "1", "2", "3", "4", "5", "", "" }, .numbered_scope = true },
        .{ .source = "<ul><li>parent\n<nowiki>\n* literal\n</nowiki>\n* child\n</li></ul>", .paths = &.{ "*", "**" }, .texts = &.{ "parent  * literal", "child" } },
        .{ .source = "<ul><li>parent\n ordinary\n</li></ul>\nafter", .paths = &.{ "*", "" }, .texts = &.{ "parent  ordinary", "after" } },
    };
    var failed_cases: usize = 0;
    for (cases, 0..) |case, case_index| {
        Check.one(a, case) catch |err| {
            std.debug.print("HTML wiki repair case {d}: {s}\n{s}\n", .{ case_index, @errorName(err), case.source });
            failed_cases += 1;
        };
    }
    try std.testing.expectEqual(@as(usize, 0), failed_cases);
}

test "etymology tree branch HTML preserves parent-first relationships through DPR2" {
    const Check = struct {
        fn shape(a: A, blocks: anytype, values: []const []const u8, paths: []const []const u8) !void {
            try std.testing.expectEqual(values.len, blocks.len);
            for (blocks, values, paths) |item, value, path| {
                try std.testing.expect(item.kind == .list_item);
                try std.testing.expectEqualStrings(path, item.list_path);
                try std.testing.expectEqual(@as(u8, @intCast(path.len)), item.depth);
                try std.testing.expectEqualStrings("", item.number);
                try std.testing.expect(item.table == null);
                try std.testing.expectEqualStrings(value, try FormattingScopeTest.text(a, item.spans));
            }
        }
        fn actions(a: A, blocks: anytype) !void {
            try FormattingScopeTest.word(a, blocks, "RootNode", .{ .kind = .link, .target = "R", .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "AncestorA", .{ .kind = .link, .target = "A", .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "OldestC", .{ .kind = .link, .target = "C", .language = "la", .direction = "ltr", .italic = true, .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "AncestorB", .{ .kind = .link, .target = "B", .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "der.", .{ .kind = .link, .target = "Appendix:Glossary#derived terms", .classes = "etytree-label" });
            try FormattingScopeTest.word(a, blocks, "lbor.", .{ .kind = .link, .target = "Appendix:Glossary#learned borrowing", .classes = "etytree-label" });
        }
        fn effects(a: A, blocks: anytype, notes: anytype, media: anytype) !void {
            try std.testing.expectEqual(@as(usize, 2), blocks.len);
            try std.testing.expectEqualStrings("*", blocks[0].list_path);
            try std.testing.expectEqualStrings("**", blocks[1].list_path);
            try std.testing.expectEqual(@as(usize, 3), notes.len);
            const bodies = [_][]const u8{ "child-note", "caption-note", "root-note" };
            for (notes, bodies) |note, body| try std.testing.expectEqualStrings(body, try FormattingScopeTest.text(a, note.spans));
            const markers = [_][]const u8{ "#reference-3", "#reference-1", "#reference-2" };
            var next: usize = 0;
            for (blocks) |item| for (item.spans) |span| {
                if (span.role != .reference) continue;
                try std.testing.expect(next < markers.len);
                try std.testing.expectEqualStrings(markers[next], span.target);
                next += 1;
            };
            try std.testing.expectEqual(markers.len, next);
            try std.testing.expectEqual(@as(usize, 1), media.len);
            try std.testing.expectEqualStrings("Tree.svg", media[0].file);
            try std.testing.expectEqualStrings("image-caption[2]", media[0].caption);
        }
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Source-shaped oracle from Module:etymon/tree rev91079116:
    // R has ancestors A and B; A has ancestor C. The DOM is child-first.
    const source = "<div class=\"etytree-body\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><i lang=\"la\" dir=\"ltr\"><span class=\"etytree-term\">[[C|OldestC]]</span></i></div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[A|AncestorA]]</span><span class=\"etytree-label-container\"><span class=\"etytree-label\">[[Appendix:Glossary#derived terms|<abbr title=\"edge\">der.</abbr>]]</span></span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[B|AncestorB]]</span><span class=\"etytree-label-container\"><span class=\"etytree-label\">[[Appendix:Glossary#learned borrowing|<abbr title=\"edge\">lbor.</abbr>]]</span><abbr class=\"etytree-unc\" title=\"uncertain\">?</abbr></span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|RootNode]]</span></div></div>";
    const values = [_][]const u8{ "RootNode", "AncestorA der.", "OldestC", "AncestorB lbor.?" };
    const paths = [_][]const u8{ "*", "**", "***", "**" };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    try Check.shape(a, blocks, &values, &paths);
    try Check.actions(a, blocks);
    try std.testing.expect(!renderer.fallbacks.any());
    const decoded = try FormattingScopeTest.encode(a, &renderer, blocks);
    try Check.shape(a, decoded.entry.sections[0].blocks, &values, &paths);
    try Check.actions(a, decoded.entry.sections[0].blocks);

    // A visible group operation belongs between the parent and its terms.
    // The hidden JSON anchor is not a second source of rendered tree content.
    var grouped: Renderer = .{ .a = a, .context = .{} };
    const grouped_blocks = try grouped.renderBody("<div class=\"etytree-body\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[A|GroupA]]</span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[B|GroupB]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"><span class=\"etytree-group-label\"><span class=\"etytree-label\"><abbr title=\"blend\">blend</abbr></span><abbr class=\"etytree-unc\" title=\"uncertain\">?</abbr></span></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|RootNode]]</span></div></div><ul class=\"etymonid\" data-ety-tree-json=\"{&quot;term&quot;:&quot;HIDDEN&quot;,&quot;children&quot;:[]}\"></ul>");
    const group_values = [_][]const u8{ "RootNode", "blend?", "GroupA", "GroupB" };
    const group_paths = [_][]const u8{ "*", "**", "***", "***" };
    try Check.shape(a, grouped_blocks, &group_values, &group_paths);
    const grouped_decoded = try FormattingScopeTest.encode(a, &grouped, grouped_blocks);
    try Check.shape(a, grouped_decoded.entry.sections[0].blocks, &group_values, &group_paths);
    try std.testing.expect(!grouped.fallbacks.any());

    // Parse content once in original DOM order, although list nodes are reordered.
    var effects_renderer: Renderer = .{ .a = a, .context = .{} };
    const effect_blocks = try effects_renderer.renderBody("<div class=\"etytree-body\"><div class=\"etytree-block\">child<ref>child-note</ref> [[File:Tree.svg|thumb|image-caption<ref>caption-note</ref>]]</div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\">root<ref>root-note</ref></div></div>");
    const references = try effects_renderer.finishReferences();
    try Check.effects(a, effect_blocks, references, effects_renderer.media.items);
    try std.testing.expectEqual(effects_renderer.media.items.len, effects_renderer.media_caption_spans.items.len);
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    const sections = [_]Section{.{ .blocks = effect_blocks }};
    const blob = @import("blob_encoder");
    const encoded = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, effects_renderer.media.items);
    const effect_decoded = try blob.presentation_codec.decodeAlloc(a, encoded, "etymology tree", .language, .{ .code = "en", .heading = "English" });
    try Check.effects(a, effect_decoded.entry.sections[0].blocks, effect_decoded.entry.references, effect_decoded.entry.media);
    try std.testing.expect(!effects_renderer.fallbacks.any());

    // Missing connectors are not evidence of an edge. Validation has no effects,
    // and the ordinary fallback must register each authored reference just once.
    var malformed: Renderer = .{ .a = a, .context = .{} };
    const malformed_blocks = try malformed.renderBody("<div class=\"etytree-body\"><div class=\"etytree-block\">first<ref>first-note</ref></div><div class=\"etytree-block\">second<ref>second-note</ref></div></div>");
    const malformed_refs = try malformed.finishReferences();
    try std.testing.expectEqual(@as(usize, 2), malformed_refs.len);
    try std.testing.expectEqualStrings("first-note", try FormattingScopeTest.text(a, malformed_refs[0].spans));
    try std.testing.expectEqualStrings("second-note", try FormattingScopeTest.text(a, malformed_refs[1].spans));
    for (malformed_blocks) |item| try std.testing.expect(item.kind != .list_item);
    try std.testing.expect(!malformed.fallbacks.any());

    // A duplicate/hidden-ancestry arrow is visible, not invented ancestry.
    var duplicate_renderer: Renderer = .{ .a = a, .context = .{} };
    const duplicate_blocks = try duplicate_renderer.renderBody("<div class=\"etytree-body\"><div class=\"etytree-duplicate-connector\"><div><span class=\"etytree-dup-right\"></span><span class=\"etytree-dup-horiz\"></span><span class=\"etytree-dup-left\"></span><span class=\"etytree-dup-arrow\">▲</span></div></div><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|RootNode]]</span></div></div>");
    try Check.shape(a, duplicate_blocks, &.{"▲ RootNode"}, &.{"*"});
    const duplicate_decoded = try FormattingScopeTest.encode(a, &duplicate_renderer, duplicate_blocks);
    try Check.shape(a, duplicate_decoded.entry.sections[0].blocks, &.{"▲ RootNode"}, &.{"*"});
    try std.testing.expect(!duplicate_renderer.fallbacks.any());

    // Multiple containers can contain a labelled group or an unlabelled forest.
    // No term is invented for the container; the shared outer parent owns it.
    var nested_renderer: Renderer = .{ .a = a, .context = .{} };
    const nested_blocks = try nested_renderer.renderBody("<div class=\"etytree-body\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[A|A]]</span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[B|B]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"><span class=\"etytree-group-label\">blend?</span></span><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[C|C]]</span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[D|D]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"></span><span class=\"etytree-connector-vertical-short\"></span><span class=\"etytree-branch-mid\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[E|E]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|R]]</span></div></div>");
    const nested_values = [_][]const u8{ "R", "blend?", "A", "B", "C", "D", "E" };
    const nested_paths = [_][]const u8{ "*", "**", "***", "***", "**", "**", "**" };
    try Check.shape(a, nested_blocks, &nested_values, &nested_paths);
    const nested_decoded = try FormattingScopeTest.encode(a, &nested_renderer, nested_blocks);
    try Check.shape(a, nested_decoded.entry.sections[0].blocks, &nested_values, &nested_paths);
    for ([_][]const u8{ "R", "A", "B", "C", "D", "E" }) |value| {
        try FormattingScopeTest.word(a, nested_blocks, value, .{ .kind = .link, .target = value, .classes = "etytree-term" });
        try FormattingScopeTest.word(a, nested_decoded.entry.sections[0].blocks, value, .{ .kind = .link, .target = value, .classes = "etytree-term" });
    }
    try std.testing.expect(!nested_renderer.fallbacks.any());

    // A rejected geometry check must not resolve effectful class semantics.
    var pure_renderer: Renderer = .{ .a = a, .context = .{} };
    var pure_hints: SemanticHints = .{};
    pure_renderer.semantic_capture = &pure_hints;
    var pure_plan: Renderer.EtymologyTreePlan = .{ .renderer = &pure_renderer };
    try std.testing.expect((try pure_plan.sequence("<div class=\"etytree-block nyms scribunto-error\">first</div><div class=\"etytree-block\">second</div>", &.{}, 0, false)) == null);
    try std.testing.expect(!pure_hints.relation_note);
    try std.testing.expect(!pure_renderer.fallbacks.any());

    // Class hints are captured on the accepted node, without leaking to its
    // parent or a later ordinary paragraph in the same renderer.
    var hinted: Renderer = .{ .a = a, .context = .{} };
    const hinted_blocks = try hinted.renderBody("<div class=\"etytree-body\"><div class=\"etytree-block nyms scribunto-error\">child</div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\">parent</div></div>\n\nplain");
    try std.testing.expectEqual(@as(usize, 3), hinted_blocks.len);
    try std.testing.expect(!hinted_blocks[0].relation_note);
    try std.testing.expect(hinted_blocks[1].relation_note);
    try std.testing.expect(!hinted_blocks[2].relation_note);
    try std.testing.expect(hinted.fallbacks.rendered_lua_error);
    try std.testing.expect(hinted.semantic_capture == null);
}
